import type { WisdomArticle } from "./types";
import { educationImages, eduImage } from "./education-images";

/** Articles sourced verbatim from temp-content/p2.txt (link-scrubbed, headings normalized) */
export const p2Articles: WisdomArticle[] = [
  {
    id: "origins-of-jyotish",
    section: "introduction",
    title: { en: `Jyotish – Origins of Vedic Astrology`, hi: `ज्योतिष - वैदिक ज्योतिष की उत्पत्ति`, ja: `ジョーティッシュ – ヴェーダ占星術の起源`, ko: `Jyotish – 베다 점성술의 기원`,},
    related: ["jyotish-explained","jyotish-and-karma","paradigm-shift"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Origins of Vedic Astrology`, hi: `ज्योतिष - वैदिक ज्योतिष की उत्पत्ति`, ja: `ジョーティッシュ – ヴェーダ占星術の起源`, ko: `Jyotish – 베다 점성술의 기원`,} },
      { type: "paragraph", text: { en: `Summary: This article explores the origins of Vedic Astrology (Jyotish) and the process of Vedic cognition. It identifies the great Vedic Seer Maharishi Parashara as the ‘father of Jyotish Astrology’ and discusses his classical Jyotish text, the Brihat Parasara Hora Shastra.`, hi: `सारांश: यह लेख वैदिक ज्योतिष (ज्योतिष) की उत्पत्ति और वैदिक अनुभूति की प्रक्रिया की पड़ताल करता है। यह महान वैदिक द्रष्टा महर्षि पराशर को 'ज्योतिष के जनक' के रूप में पहचानता है और उनके शास्त्रीय ज्योतिष पाठ, बृहत पराशर होरा शास्त्र पर चर्चा करता है।`, ja: `概要: この記事では、ヴェーダ占星術 (ジョーティッシュ) の起源とヴェーダ認識のプロセスを探ります。この論文では、偉大なヴェーダの聖見者マハリシ・パラシャラを「ジョーティッシュの父」と特定し、彼の古典的なジョーティッシュのテキストであるブリハット・パラサラ・ホラ・シャストラについて論じています。`, ko: `요약: 이 기사는 베다 점성술(Jyotish)의 기원과 베다 인식 과정을 탐구합니다. 그것은 위대한 베다 예언자 마하리시 파라샤라(Maharishi Parashara)를 'Jyotish 점성술의 아버지'로 식별하고 그의 고전적인 Jyotish 텍스트인 Brihat Parasara Hora Shastra에 대해 논의합니다.`,} },
      { type: "heading", level: 3, text: { en: `Origins of Vedic Astrology and the Process of Vedic Cognition`, hi: `वैदिक ज्योतिष की उत्पत्ति और वैदिक अनुभूति की प्रक्रिया`, ja: `ヴェーダ占星術の起源とヴェーダ認識の過程`, ko: `베다 점성술의 기원과 베다 인지 과정`,} },
      { type: "paragraph", text: { en: `Ask a Western Astrologer about the origins of astrology and they will usually provide a chronological account describing how the subject passed from one culture to another, moving between countries and civilizations over time. Western modes of thought are comfortable with this approach because it aligns with our sense of history. We enjoy organising the past through names, dates, timelines, and geographical locations.`, hi: `किसी पश्चिमी ज्योतिषी से ज्योतिष की उत्पत्ति के बारे में पूछें और वे आम तौर पर एक कालानुक्रमिक विवरण प्रदान करेंगे जिसमें बताया जाएगा कि समय के साथ यह विषय एक संस्कृति से दूसरी संस्कृति में, देशों और सभ्यताओं के बीच कैसे स्थानांतरित हुआ। पश्चिमी विचारधारा इस दृष्टिकोण के साथ सहज है क्योंकि यह हमारे इतिहास बोध के अनुरूप है। हम नामों, तिथियों, समयसीमाओं और भौगोलिक स्थानों के माध्यम से अतीत को व्यवस्थित करने का आनंद लेते हैं।`, ja: `西洋占星術師に占星術の起源について尋ねると、通常、その主題が時間の経過とともに国や文明の間を移動しながら、ある文化から別の文化にどのように伝わったかを時系列で説明してくれるでしょう。西洋の思考様式は、このアプローチが私たちの歴史感覚と一致しているため、このアプローチに満足しています。私たちは、名前、日付、タイムライン、地理的な場所を通じて過去を整理することを楽しんでいます。`, ko: `서양 점성술사에게 점성술의 기원에 대해 물어보면 그들은 일반적으로 주제가 어떻게 한 문화에서 다른 문화로 전달되었는지, 시간이 지남에 따라 국가와 문명 간에 이동하는지 설명하는 연대순 설명을 제공할 것입니다. 서양의 사고방식은 이러한 접근 방식이 우리의 역사의식과 일치하기 때문에 이를 편안하게 받아들입니다. 우리는 이름, 날짜, 타임라인, 지리적 위치를 통해 과거를 정리하는 것을 즐깁니다.`,} },
      { type: "paragraph", text: { en: `Ask a Jyotish Astrologer the same question and the answer is likely to be that it “came from God” [1]. This is a crucial point and highlights a fundamental distinction between Jyotish and Western Astrology. According to Vedic tradition, the knowledge of Jyotish Astrology, just like the knowledge of maintaining perfect health through Ayurveda and the vast body of Vedic Science as a whole, was not invented but rather revealed or cognized.`, hi: `यही प्रश्न किसी ज्योतिषी से पूछें और उत्तर संभवतः यही होगा कि यह "ईश्वर की ओर से आया" [1]। यह एक महत्वपूर्ण बिंदु है और ज्योतिष और पश्चिमी ज्योतिष के बीच एक बुनियादी अंतर को उजागर करता है। वैदिक परंपरा के अनुसार, ज्योतिष का ज्ञान, आयुर्वेद के माध्यम से उत्तम स्वास्थ्य बनाए रखने के ज्ञान और समग्र रूप से वैदिक विज्ञान के विशाल समूह की तरह, आविष्कार नहीं किया गया था बल्कि प्रकट या पहचाना गया था।`, ja: `ジョーティッシュ師に同じ質問をすると、おそらく「神から来たもの」という答えが返ってくるでしょう [1]。これは重要な点であり、ジョーティッシュと西洋占星術の根本的な違いを強調しています。ヴェーダの伝統によれば、ジョーティッシュの知識は、アーユルヴェーダやヴェーダ科学全体を通じて完全な健康を維持する知識と同様、発明されたものではなく、明らかにされたか認識されたものです。`, ko: `Jyotish 점성가에게 동일한 질문을 하면 대답은 "신에게서 왔다"는 것 같습니다[1]. 이것은 중요한 점이며 Jyotish와 Western Astrology의 근본적인 차이점을 강조합니다. 베다 전통에 따르면, 조티쉬 점성술에 대한 지식은 아유르베다와 베다 과학 전체를 통해 완벽한 건강을 유지하는 지식과 마찬가지로 발명된 것이 아니라 오히려 드러나거나 인식되었습니다.`,} },
      { type: "paragraph", text: { en: `Jyotish was neither discovered nor created by human beings, nor was it gradually developed through experimentation over centuries.`, hi: `ज्योतिष की खोज न तो मनुष्य द्वारा की गई, न ही इसे बनाया गया, न ही इसे सदियों से प्रयोग के माध्यम से धीरे-धीरे विकसित किया गया।`, ja: `ジョーティッシュは人間によって発見または作成されたものではなく、何世紀にもわたる実験を通じて徐々に開発されたものでもありません。`, ko: `조티쉬는 인간이 발견하거나 창조한 것이 아니며, 수세기에 걸쳐 실험을 통해 점진적으로 발전한 것도 아닙니다.`,} },
      { type: "paragraph", text: { en: `There are few clear equivalents within Western thought to explain the process of Vedic cognition. Perhaps the closest comparison would be moments of extraordinary artistic inspiration, creative genius, or scientific insight, where the complete understanding of a great work, invention, or theorem seems to appear in the mind instantly.`, hi: `वैदिक अनुभूति की प्रक्रिया को समझाने के लिए पश्चिमी विचारधारा में कुछ स्पष्ट समकक्ष मौजूद हैं। शायद निकटतम तुलना असाधारण कलात्मक प्रेरणा, रचनात्मक प्रतिभा, या वैज्ञानिक अंतर्दृष्टि के क्षण होंगे, जहां किसी महान कार्य, आविष्कार या प्रमेय की पूरी समझ तुरंत दिमाग में प्रकट होती है।`, ja: `西洋思想の中に、ヴェーダの認識プロセスを説明する明確な同等物はほとんどありません。おそらく、最も近い例は、並外れた芸術的インスピレーション、創造的な天才、または科学的洞察の瞬間であり、偉大な作品、発明、または定理の完全な理解が瞬時に頭の中に現れるように見える場合です。`, ko: `베다 인식의 과정을 설명하기 위해 서양 사상 내에서 명확하게 동등한 것은 거의 없습니다. 아마도 가장 가까운 비교는 위대한 작품, 발명 또는 정리에 대한 완전한 이해가 마음 속에 즉시 나타나는 것처럼 보이는 특별한 예술적 영감, 창의적인 천재 또는 과학적 통찰력의 순간일 것입니다.`,} },
      { type: "heading", level: 3, text: { en: `Modern ‘Download’ Analogy to Vedic Cognition Process`, hi: `वैदिक अनुभूति प्रक्रिया का आधुनिक 'डाउनलोड' सादृश्य`, ja: `現代の「ダウンロード」をヴェーダの認知プロセスに喩える`, ko: `베다 인지 과정에 대한 현대의 '다운로드' 비유`,} },
      { type: "paragraph", text: { en: `All of the great works of Vedic Science are said to have originated through revealed knowledge or cognition within the consciousness of highly evolved sages, seers, and Rishis of ancient times. These individuals devoted entire lifetimes to the practice of Yoga and meditation, enabling them to access higher states of awareness. Their level of consciousness was far beyond what most people experience in everyday life.`, hi: `कहा जाता है कि वैदिक विज्ञान के सभी महान कार्य प्राचीन काल के अत्यधिक विकसित ऋषियों, द्रष्टाओं और ऋषियों की चेतना के भीतर प्रकट ज्ञान या अनुभूति के माध्यम से उत्पन्न हुए थे। इन व्यक्तियों ने अपना पूरा जीवन योग और ध्यान के अभ्यास में समर्पित कर दिया, जिससे उन्हें जागरूकता की उच्च अवस्था तक पहुंचने में मदद मिली। उनकी चेतना का स्तर अधिकांश लोगों द्वारा रोजमर्रा की जिंदगी में अनुभव किए गए स्तर से कहीं अधिक था।`, ja: `ヴェーダ科学の偉大な著作はすべて、古代の高度に進化した賢者、先見者、聖師たちの意識の中に明らかにされた知識や認識を通じて生まれたと言われています。これらの人々は生涯をヨガと瞑想の実践に捧げ、より高い意識状態にアクセスできるようにしました。彼らの意識レベルは、ほとんどの人が日常生活で経験するレベルをはるかに超えていました。`, ko: `베다 과학의 모든 위대한 작품은 고대의 고도로 진화된 현자, 선견자, 리쉬의 의식 속에 드러난 지식이나 인식을 통해 유래되었다고 합니다. 이 사람들은 전 생애를 요가와 명상 수련에 바쳤고, 이를 통해 더 높은 인식 상태에 접근할 수 있었습니다. 그들의 의식 수준은 대부분의 사람들이 일상 생활에서 경험하는 수준을 훨씬 뛰어넘었습니다.`,} },
      { type: "paragraph", text: { en: `A useful modern analogy is the Internet. Imagine connecting a personal computer to a remote server—or even to “The Cloud”—and downloading all the information required directly into the machine. Naturally, we must know how to operate the computer correctly and possess the necessary password—perhaps comparable to using the correct Sanskrit mantras—to gain access to the information stored remotely. This analogy reflects the Vedic Model of Reality, in which the universe and all living beings are viewed as parts of an interconnected whole.`, hi: `एक उपयोगी आधुनिक सादृश्य इंटरनेट है। कल्पना करें कि एक पर्सनल कंप्यूटर को रिमोट सर्वर से या यहां तक ​​कि "द क्लाउड" से कनेक्ट किया जाए और सभी आवश्यक जानकारी सीधे मशीन में डाउनलोड की जाए। स्वाभाविक रूप से, हमें पता होना चाहिए कि कंप्यूटर को सही तरीके से कैसे संचालित किया जाए और दूर से संग्रहीत जानकारी तक पहुंच प्राप्त करने के लिए आवश्यक पासवर्ड होना चाहिए - शायद सही संस्कृत मंत्रों का उपयोग करने के बराबर। यह सादृश्य वास्तविकता के वैदिक मॉडल को दर्शाता है, जिसमें ब्रह्मांड और सभी जीवित प्राणियों को एक दूसरे से जुड़े पूरे हिस्से के रूप में देखा जाता है।`, ja: `現代で役立つ例えはインターネットです。パーソナル コンピュータをリモート サーバー (または「クラウド」) に接続し、必要なすべての情報をマシンに直接ダウンロードすることを想像してください。当然のことながら、リモートに保存されている情報にアクセスするには、コンピューターの正しい操作方法を理解し、必要なパスワード (おそらく正しいサンスクリット語のマントラを使用することに匹敵します) を所有している必要があります。このアナロジーは、宇宙とすべての生き物が相互に接続された全体の一部として見なされる、現実のヴェーダ モデルを反映しています。`, ko: `유용한 현대 비유는 인터넷입니다. 개인용 컴퓨터를 원격 서버 또는 "클라우드"에 연결하고 필요한 모든 정보를 컴퓨터에 직접 다운로드한다고 상상해 보십시오. 당연히 원격으로 저장된 정보에 액세스하려면 컴퓨터를 올바르게 작동하는 방법을 알아야 하며 올바른 산스크리트어 만트라를 사용하는 것과 비슷한 필요한 비밀번호를 소유해야 합니다. 이 비유는 우주와 모든 생명체가 상호 연결된 전체의 일부로 간주되는 베다 현실 모델을 반영합니다.`,} },
      { type: "paragraph", text: { en: `If we continue with this analogy, it becomes clear that the information stored on a server exists whether or not our computer, tablet, or phone can access it. The same principle applies to the knowledge of Vedic Astrology. The information within the “Cosmic Computer” is always present, waiting to be accessed. During certain ages, direct access to this knowledge may be available to a small number of enlightened individuals.`, hi: `यदि हम इस सादृश्य को जारी रखते हैं, तो यह स्पष्ट हो जाता है कि सर्वर पर संग्रहीत जानकारी मौजूद है, चाहे हमारा कंप्यूटर, टैबलेट या फोन उस तक पहुंच सके या नहीं। यही सिद्धांत वैदिक ज्योतिष के ज्ञान पर भी लागू होता है। "कॉस्मिक कंप्यूटर" के भीतर जानकारी हमेशा मौजूद रहती है, पहुंच की प्रतीक्षा में। कुछ युगों के दौरान, इस ज्ञान तक सीधी पहुंच कुछ प्रबुद्ध व्यक्तियों के लिए उपलब्ध हो सकती है।`, ja: `この例えを続けると、コンピューター、タブレット、または携帯電話がアクセスできるかどうかに関係なく、サーバーに保存されている情報が存在することが明らかになります。同じ原則がヴェーダ占星術の知識にも当てはまります。 「宇宙コンピュータ」内の情報は常に存在し、アクセスされるのを待っています。特定の年齢の間は、少数の啓発された個人がこの知識に直接アクセスできる場合があります。`, ko: `이 비유를 계속하면 컴퓨터, 태블릿 또는 휴대폰이 액세스할 수 있는지 여부에 관계없이 서버에 저장된 정보가 존재한다는 것이 분명해집니다. 베다 점성술에 대한 지식에도 동일한 원칙이 적용됩니다. “우주 컴퓨터” 내의 정보는 항상 존재하며 접근을 기다리고 있습니다. 특정 시대에는 소수의 깨달은 개인이 이 지식에 직접 접근할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `In the current Dark Age of Kali Yuga [2], direct cognition is considered unavailable. As a result, we rely upon the cognized wisdom passed down by enlightened sages from previous ages.`, hi: `कलियुग [2] के वर्तमान अंधकार युग में प्रत्यक्ष ज्ञान अनुपलब्ध माना जाता है। परिणामस्वरूप, हम पिछले युगों के प्रबुद्ध संतों द्वारा पारित ज्ञान पर भरोसा करते हैं।`, ja: `現在のカリユガの暗黒時代 [2] では、直接認識は不可能であると考えられています。その結果、私たちは前の時代から啓発された賢者たちによって伝えられた認識された知恵に依存しています。`, ko: `현재 칼리 유가(Kali Yuga)의 암흑기[2]에서는 직접적인 인지가 불가능한 것으로 간주됩니다. 결과적으로 우리는 이전 시대의 깨달은 성인들이 물려준 인식된 지혜에 의존합니다.`,} },
      { type: "heading", level: 3, text: { en: `Maharishi Parashara – ‘Father’ of Vedic Astrology`, hi: `महर्षि पराशर - वैदिक ज्योतिष के 'पिता'`, ja: `マハリシ・パラシャラ – ヴェーダ占星術の「父」`, ko: `마하리시 파라샤라(Maharishi Parashara) - 베다 점성술의 '아버지'`,} },
      { type: "paragraph", text: { en: `The Vedic Sage, or Seer, most widely regarded as the “father of Jyotish Astrology” is Maharishi Parashara (Maha meaning “great” and Rishi meaning “seer”) [3]. His Sanskrit work, the Brihat Parasara Hora Shastra [4], remains one of the most important and influential texts in Vedic Astrology.`, hi: `वैदिक ऋषि, या द्रष्टा, जिन्हें व्यापक रूप से "ज्योतिष के जनक" के रूप में माना जाता है, महर्षि पराशर हैं (महा का अर्थ है "महान" और ऋषि का अर्थ है "द्रष्टा") [3]। उनका संस्कृत कार्य, बृहत पारासर होरा शास्त्र [4], वैदिक ज्योतिष में सबसे महत्वपूर्ण और प्रभावशाली ग्रंथों में से एक है।`, ja: `「ジョーティッシュの父」として最も広くみなされているヴェーダの賢者、または先見者は、マハリシ・パラシャラ（マハは「偉大な」を意味し、リシは「先見者」を意味する）です[3]。彼のサンスクリット語の著作である『ブリハット パラサラ ホラ シャストラ』 [4] は、依然としてヴェーダ占星術において最も重要かつ影響力のあるテキストの 1 つです。`, ko: `"Jyotish 점성술의 아버지"로 가장 널리 알려진 베다 현자 또는 예언자는 마하리시 파라샤라(Maha는 "위대한"을 의미하고 Rishi는 "선견자"를 의미)입니다[3]. 그의 산스크리트 작품인 브리하트 파라사라 호라 샤스트라(Brihat Parasara Hora Shastra)[4]는 베다 점성술에서 가장 중요하고 영향력 있는 문헌 중 하나로 남아 있습니다.`,} },
      eduImage(educationImages.parashara, {
        en: "Maharishi Parashara, father of Vedic astrology", hi: "वैदिक ज्योतिष के जनक महर्षि पराशर", ja: "ヴェーダ占星術の父、マハリシ・パラシャラ", ko: "베다 점성술의 아버지, 마하리시 파라샤라(Maharishi Parashara)",
      }),
      { type: "paragraph", text: { en: `From the Vedic perspective, exactly when or where Parashara lived is of secondary importance. Even if his teachings had been lost over the course of time, it would not fundamentally matter because the knowledge was never considered to be personally his. The wisdom itself existed independently and was simply cognized through him. Future Rishis born in other ages could once again re-cognize the complete body of Jyotish Shastra and make it available for the benefit of humanity.`, hi: `वैदिक दृष्टिकोण से, पराशर कब और कहाँ रहते थे, इसका गौण महत्व है। भले ही उनकी शिक्षाएँ समय के साथ खो गई हों, इससे बुनियादी तौर पर कोई फर्क नहीं पड़ता क्योंकि ज्ञान को कभी भी व्यक्तिगत रूप से उनका नहीं माना गया। ज्ञान स्वयं स्वतंत्र रूप से अस्तित्व में था और केवल उसके माध्यम से पहचाना गया था। अन्य युगों में जन्मे भविष्य के ऋषि एक बार फिर ज्योतिष शास्त्र के संपूर्ण स्वरूप को पहचान सकते हैं और इसे मानवता के लाभ के लिए उपलब्ध करा सकते हैं।`, ja: `ヴェーダの観点からは、パラシャラが正確にいつ、どこに住んでいたかは二番目に重要です。たとえ彼の教えが時間の経過とともに失われていたとしても、その知識は彼の個人的なものとは決して考えられなかったので、それは基本的に問題ではありません。知恵自体は独立して存在し、彼を通して認識されただけです。他の時代に生まれた将来の聖者は、ジョーティッシュ・シャストラの完全な体を再び認識し、それを人類の利益のために利用できるようにするかもしれません。`, ko: `베다의 관점에서 파라샤라가 정확히 언제, 어디서 살았는지는 이차적으로 중요합니다. 비록 그의 가르침이 시간이 지나면서 사라졌다고 해도 근본적으로 문제가 되지 않습니다. 왜냐하면 그 지식이 결코 개인적으로 그의 것으로 간주되지 않았기 때문입니다. 지혜 자체는 독립적으로 존재했으며 단순히 그를 통해 인식되었습니다. 다른 시대에 태어난 미래의 리쉬들은 다시 한 번 Jyotish Shastra의 완전한 몸을 인식하고 그것을 인류의 이익을 위해 사용할 수 있게 만들 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "paragraph", text: { en: `[1] The Vedic concept of God differs significantly from the idea of a distant, judgemental deity often associated with the Abrahamic traditions. In the Vedic understanding, the all-pervading “GOD” may be viewed as a three-letter acronym representing fundamental principles of nature: G – Generator (personified as Brahma), O – Operator (personified as Vishnu), and D – Destroyer (personified as Maheshwara or Shiva). This divine reality is not something separate from us; rather, we exist within it, just as a fish exists within the ocean. Some describe it as the “field of creative intelligence.” There are also many interesting parallels between this Vedic Model of Reality and modern scientific models.`, hi: `[1] ईश्वर की वैदिक अवधारणा, अक्सर इब्राहीम परंपराओं से जुड़े एक दूर के, निर्णयात्मक देवता के विचार से काफी भिन्न है। वैदिक समझ में, सर्वव्यापी "ईश्वर" को प्रकृति के मूलभूत सिद्धांतों का प्रतिनिधित्व करने वाले तीन अक्षरों के संक्षिप्त रूप के रूप में देखा जा सकता है: जी - जेनरेटर (ब्रह्मा के रूप में व्यक्त), ओ - संचालक (विष्णु के रूप में व्यक्त), और डी - विध्वंसक (महेश्वर या शिव के रूप में व्यक्त)। यह दिव्य वास्तविकता हमसे अलग कुछ नहीं है; बल्कि, हम इसके भीतर मौजूद हैं, जैसे मछली समुद्र के भीतर मौजूद है। कुछ लोग इसे "रचनात्मक बुद्धि का क्षेत्र" के रूप में वर्णित करते हैं। वास्तविकता के इस वैदिक मॉडल और आधुनिक वैज्ञानिक मॉडल के बीच कई दिलचस्प समानताएं भी हैं।`, ja: `[1] ヴェーダの神の概念は、アブラハムの伝統によく関連付けられている遠く離れた裁きの神という概念とは大きく異なります。ヴェーダの理解では、すべてに浸透している「GOD」は、自然の基本原理を表す 3 文字の頭字語と見なされます。G – 生成者 (ブラフマーとして擬人化)、O – 操作者 (ヴィシュヌとして擬人化)、D – 破壊者 (マヘシュワラまたはシヴァとして擬人化)。この神聖な現実は私たちから切り離されたものではありません。むしろ、魚が海の中に存在するのと同じように、私たちはその中に存在します。それを「創造的知性の分野」と表現する人もいます。このヴェーダの現実モデルと現代の科学モデルの間には、興味深い類似点も数多くあります。`, ko: `[1] 베다의 신 개념은 종종 아브라함 전통과 연관되어 있는 멀리 떨어져 있는 심판의 신이라는 개념과 상당히 다릅니다. 베다의 이해에서 모든 곳에 퍼져 있는 "GOD"는 자연의 기본 원리를 나타내는 세 글자 약어로 볼 수 있습니다. G – 제너레이터(브라마로 의인화), O – 운영자(비슈누로 의인화), D – 파괴자(마헤슈와라 또는 시바로 의인화). 이 신성한 현실은 우리와 분리된 것이 아닙니다. 오히려 물고기가 바다 속에 존재하는 것처럼 우리는 그 안에 존재합니다. 어떤 사람들은 이를 “창의적 지능의 분야”라고 표현합니다. 이 현실의 베다 모델과 현대 과학 모델 사이에는 흥미로운 유사점이 많이 있습니다.`,} },
      { type: "paragraph", text: { en: `[2] Vedic literature describes four major ages, or great cycles of time, each characterised by distinct qualities. Most, though not all, scholars maintain that humanity is currently living in the age of Kali Yuga. There is ongoing debate regarding exactly when this age began—many place its commencement around 3102 BCE, following the departure of Krishna from His earthly incarnation—and how long it will continue. Some estimates suggest approximately another 17,000 years, while others propose a much longer duration. Certain scholars also suggest the existence of smaller cycles operating within the larger Yuga framework.`, hi: `[2] वैदिक साहित्य में चार प्रमुख युगों या समय के महान चक्रों का वर्णन किया गया है, जिनमें से प्रत्येक की विशेषता अलग-अलग है। अधिकांश, हालांकि सभी नहीं, विद्वान मानते हैं कि मानवता वर्तमान में कलियुग के युग में जी रही है। इस बारे में बहस चल रही है कि यह युग कब शुरू हुआ - कई लोग कृष्ण के अपने सांसारिक अवतार से प्रस्थान के बाद, 3102 ईसा पूर्व के आसपास इसकी शुरुआत मानते हैं - और यह कब तक जारी रहेगा। कुछ अनुमान लगभग 17,000 वर्ष और सुझाते हैं, जबकि अन्य इससे कहीं अधिक लंबी अवधि प्रस्तावित करते हैं। कुछ विद्वान बड़े युग ढांचे के भीतर संचालित होने वाले छोटे चक्रों के अस्तित्व का भी सुझाव देते हैं।`, ja: `[2] ヴェーダ文献には 4 つの主要な時代、または大きな時間のサイクルが記述されており、それぞれが異なる性質によって特徴付けられています。すべてではありませんが、ほとんどの学者は、人類は現在カリユガの時代に生きていると主張しています。この時代が正確にいつ始まったかについては、議論が続いている。多くの人はクリシュナが地上での転生を離れた後、紀元前 3102 年頃から始まったとしている。そして、それがいつまで続くのか。さらに約 17,000 年を示唆する推定もあれば、さらに長い期間を示唆する推定もあります。一部の学者は、より大きなユガの枠組みの中で動作する小さなサイクルの存在も示唆しています。`, ko: `[2] 베다 문헌은 각각 뚜렷한 특성을 특징으로 하는 네 가지 주요 시대, 즉 시간의 큰 순환을 설명합니다. 전부는 아니지만 대부분의 학자들은 인류가 현재 Kali Yuga 시대에 살고 있다고 주장합니다. 이 시대가 정확히 언제 시작되었는지(많은 사람들이 크리슈나가 지상 화신에서 떠난 후인 기원전 3102년경에 시작된다고 생각함)와 그 기간이 얼마나 지속될 것인지에 관해 지속적인 논쟁이 있습니다. 일부 추정에서는 약 17,000년이 더 걸릴 것으로 제안하는 반면 다른 추정에서는 훨씬 더 긴 기간을 제안합니다. 일부 학자들은 또한 더 큰 Yuga 체계 내에서 작동하는 더 작은 주기의 존재를 제안합니다.`,} },
      { type: "paragraph", text: { en: `[3] Parashara is credited with cognizing the rules, principles, and systematic framework that form the basis of Jyotish.`, hi: `[3] पराशर को ज्योतिष का आधार बनाने वाले नियमों, सिद्धांतों और व्यवस्थित ढांचे को पहचानने का श्रेय दिया जाता है।`, ja: `[3] パラシャラは、ジョーティッシュの基礎を形成する規則、原則、体系的な枠組みを認識したと信じられています。`, ko: `[3] Parashara는 Jyotish의 기초를 형성하는 규칙, 원칙 및 체계적인 프레임워크를 인식한 것으로 알려져 있습니다.`,} },
      { type: "paragraph", text: { en: `[4] Scholars continue to debate which chapters of the currently available printed editions of the Brihat Parasara Hora Shastra can be directly attributed to Parashara and which may originate from the Sage Jaimini. Although the two systems sometimes appear to differ, it is generally accepted that Parashara’s methods are particularly suited to the present age of Kali Yuga, while Jaimini’s teachings may have been intended for a different age.`, hi: `[4] विद्वान इस बात पर बहस जारी रखते हैं कि बृहत पराशर होरा शास्त्र के वर्तमान में उपलब्ध मुद्रित संस्करणों के कौन से अध्याय सीधे तौर पर पराशर को दिए जा सकते हैं और कौन से अध्याय ऋषि जैमिनी से उत्पन्न हो सकते हैं। हालाँकि दोनों प्रणालियाँ कभी-कभी भिन्न दिखाई देती हैं, यह आम तौर पर स्वीकार किया जाता है कि पराशर की पद्धतियाँ विशेष रूप से कलियुग के वर्तमान युग के लिए उपयुक्त हैं, जबकि जैमिनी की शिक्षाएँ एक अलग युग के लिए अभिप्रेत हो सकती हैं।`, ja: `[4] 学者たちは、ブリハット・パラシャラ・ホラ・シャーストラの現在入手可能な印刷版のどの章がパラシャラに直接帰することができ、どの章が聖者ジャイミニに由来する可能性があるかについて議論を続けています。 2 つのシステムは異なるように見えることもありますが、パラシャラのメソッドは特に現在のカリ ユガの時代に適しているのに対し、ジャイミニの教えは別の時代を対象としたものである可能性があることが一般に認められています。`, ko: `[4] 학자들은 Brihat Parasara Hora Shastra의 현재 사용 가능한 인쇄판 중 어떤 장이 Parashara에 직접적으로 귀속될 수 있는지 그리고 Sage Jaimini에서 유래했을 수 있는지에 대해 계속해서 논쟁을 벌이고 있습니다. 두 시스템이 때때로 다른 것처럼 보이지만 Parashara의 방법은 Kali Yuga의 현재 시대에 특히 적합한 반면 Jaimini의 가르침은 다른 시대를 위해 의도되었을 수 있다는 것이 일반적으로 인정됩니다.`,} },
    ],
  },
  {
    id: "jyotish-and-karma",
    section: "introduction",
    title: { en: `Jyotish and Karma`, hi: `ज्योतिष और कर्म`, ja: `ジョーティッシュとカルマ`, ko: `조티쉬와 카르마`,},
    related: ["three-types-karma","predictive-capabilities","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish and Karma`, hi: `ज्योतिष और कर्म`, ja: `ジョーティッシュとカルマ`, ko: `조티쉬와 카르마`,} },
      { type: "paragraph", text: { en: `Summary: This article explores the principles of karma and reincarnation within the framework of Jyotish Astrology. It discusses the various categories of karma, explains how returning karmas can be identified, and describes how Vedic Astrology's remedial measures may help modify their effects.`, hi: `सारांश: यह लेख ज्योतिष के ढांचे के भीतर कर्म और पुनर्जन्म के सिद्धांतों की पड़ताल करता है। यह कर्म की विभिन्न श्रेणियों पर चर्चा करता है, बताता है कि लौटने वाले कर्मों की पहचान कैसे की जा सकती है, और वर्णन करता है कि वैदिक ज्योतिष के उपचारात्मक उपाय उनके प्रभावों को संशोधित करने में कैसे मदद कर सकते हैं।`, ja: `概要: この記事では、ジョーティッシュの枠組みの中でカルマと輪廻の原則を探ります。カルマのさまざまなカテゴリについて説明し、戻ってきたカルマをどのように識別できるかを説明し、ヴェーダ占星術の改善法がその影響を修正するのにどのように役立つかを説明します。`, ko: `요약: 이 기사는 Jyotish 점성술의 틀 내에서 카르마와 환생의 원리를 탐구합니다. 카르마의 다양한 범주에 대해 논의하고, 되돌아오는 카르마를 식별하는 방법을 설명하며, 베다 점성술의 치료 조치가 카르마의 효과를 수정하는 데 어떻게 도움이 될 수 있는지 설명합니다.`,} },
      { type: "heading", level: 3, text: { en: `Vedic Astrology, Karma and Reincarnation`, hi: `वैदिक ज्योतिष, कर्म और पुनर्जन्म`, ja: `ヴェーダ占星術、カルマ、輪廻転生`, ko: `베다 점성술, 카르마 및 환생`,} },
      { type: "paragraph", text: { en: `In the West, the words kama and karma are often confused and sometimes mispronounced. Kama refers to desire, and many people are familiar with the Kama Sutra. Karma, on the other hand, literally means action. Since actions are constantly taking place, karma is continually being generated throughout the world.`, hi: `पश्चिम में, काम और कर्म शब्द अक्सर भ्रमित होते हैं और कभी-कभी गलत उच्चारण भी किया जाता है। काम का तात्पर्य इच्छा से है, और बहुत से लोग कामसूत्र से परिचित हैं। दूसरी ओर, कर्म का शाब्दिक अर्थ क्रिया है। चूंकि क्रियाएं लगातार हो रही हैं, इसलिए दुनिया भर में कर्म लगातार उत्पन्न हो रहे हैं।`, ja: `西洋では、カーマとカルマという言葉はしばしば混同され、時々誤って発音されます。カーマとは欲望を意味し、カーマスートラは多くの人に親しまれています。一方、カルマは文字通り行為を意味します。行為は常に行われているため、世界中でカルマが生成され続けています。`, ko: `서양에서는 카마(kama)와 카르마(karma)라는 단어가 종종 혼동되고 때로는 잘못 발음되기도 합니다. 카마(Kama)는 욕망을 의미하며, 많은 사람들이 카마 수트라(Kama Sutra)를 잘 알고 있습니다. 반면에 카르마는 문자 그대로 행동을 의미합니다. 행동이 끊임없이 일어나고 있기 때문에 카르마는 전 세계적으로 지속적으로 생성됩니다.`,} },
      { type: "paragraph", text: { en: `The concept of karma carries many subtle meanings and layers of interpretation. On an individual level, karma is generally understood as the returning consequences of our past actions—summed up by the phrase, "as you sow, so shall you reap." Within the Vedic tradition, karma can extend across multiple incarnations. Karma is also closely connected with the concept of samskara (or sanskara)—the deep-rooted impressions and latent desires within the mind that motivate us to perform particular actions [1].`, hi: `कर्म की अवधारणा में कई सूक्ष्म अर्थ और व्याख्या की परतें हैं। व्यक्तिगत स्तर पर, कर्म को आम तौर पर हमारे पिछले कार्यों के रिटर्निंग परिणामों के रूप में समझा जाता है - वाक्यांश द्वारा संक्षेपित, "जैसा बोओगे, वैसा काटोगे।" वैदिक परंपरा के भीतर, कर्म कई अवतारों में विस्तारित हो सकता है। कर्म संस्कार (या संस्कार) की अवधारणा से भी निकटता से जुड़ा हुआ है - मन के भीतर गहरी जड़ें जमाए हुए संस्कार और अव्यक्त इच्छाएं जो हमें विशेष कार्य करने के लिए प्रेरित करती हैं [1]।`, ja: `カルマの概念には、多くの微妙な意味と解釈の層があります。個人レベルでは、カルマは一般に、私たちの過去の行為の結果として理解されており、「蒔いた種を刈り取ることになる」という言葉に要約されます。ヴェーダの伝統では、カルマは複数の転生にまたがって広がる可能性があります。カルマはまた、サムスカーラ (またはサンスカーラ) の概念、つまり特定の行動を実行する動機となる心の中に根深い印象や潜在的な願望と密接に関係しています [1]。`, ko: `카르마의 개념은 많은 미묘한 의미와 해석의 층위를 담고 있습니다. 개인 수준에서 카르마는 일반적으로 우리의 과거 행동이 되돌아오는 결과로 이해됩니다. "뿌린 대로 거둘 것입니다."라는 문구로 요약됩니다. 베다 전통 내에서 카르마는 여러 화신으로 확장될 수 있습니다. 카르마는 또한 우리가 특정 행동을 수행하도록 동기를 부여하는 마음 속의 뿌리 깊은 인상과 잠재된 욕구인 삼스카라(또는 산스카라)의 개념과도 밀접하게 연결되어 있습니다[1].`,} },
      { type: "paragraph", text: { en: `According to Vedic Astrology, the soul (for want of a better term in the English language) does not take birth randomly. Vedic Masters teach that it incarnates into a human body—primarily—with specific physical traits determined by previous karmas. The family into which one is born, its social standing, and even the country of birth are likewise influenced by past karmic actions.`, hi: `वैदिक ज्योतिष के अनुसार, आत्मा (अंग्रेजी भाषा में बेहतर शब्द के अभाव में) अचानक जन्म नहीं लेती है। वैदिक गुरु सिखाते हैं कि यह मुख्य रूप से पिछले कर्मों द्वारा निर्धारित विशिष्ट शारीरिक लक्षणों के साथ मानव शरीर में अवतरित होता है। जिस परिवार में किसी का जन्म हुआ है, उसकी सामाजिक स्थिति और यहां तक ​​कि जन्म का देश भी पिछले कर्मों से प्रभावित होता है।`, ja: `ヴェーダ占星術によれば、魂（英語でより適切な言葉が見つかりませんが）はランダムに誕生するものではありません。ヴェーダのマスターは、それは主に過去のカルマによって決定された特定の身体的特徴を持って人間の体に転生すると教えています。人が生まれた家族、社会的地位、さらには生まれた国も同様に、過去のカルマ行為の影響を受けます。`, ko: `베다 점성술에 따르면 영혼(영어로 더 나은 용어가 필요함)은 무작위로 탄생하지 않습니다. 베다 스승들은 그것이 주로 이전 카르마에 의해 결정된 특정한 신체적 특성을 가지고 인간의 몸으로 화신한다고 가르칩니다. 사람이 태어난 가족, 사회적 지위, 심지어 출생 국가도 마찬가지로 과거 카르마 행위의 영향을 받습니다.`,} },
      { type: "paragraph", text: { en: `Vedic Astrology further teaches that we are not victims of our birth chart or the planetary combinations contained within it. The planets cannot be blamed for our present circumstances or challenges. Whatever we are experiencing today, whether perceived as favourable or unfavourable, is simply the manifestation of returning karmas. The planets indicate these karmas, but they do not create them.`, hi: `वैदिक ज्योतिष आगे सिखाता है कि हम अपनी जन्म कुंडली या उसमें मौजूद ग्रह संयोजनों के शिकार नहीं हैं। हमारी वर्तमान परिस्थितियों या चुनौतियों के लिए ग्रहों को दोष नहीं दिया जा सकता। आज हम जो कुछ भी अनुभव कर रहे हैं, चाहे वह अनुकूल हो या प्रतिकूल, वह केवल लौट रहे कर्मों का प्रकटीकरण है। ग्रह इन कर्मों को इंगित करते हैं, लेकिन वे उन्हें बनाते नहीं हैं।`, ja: `ヴェーダ占星術はさらに、私たちは出生図やそこに含まれる惑星の組み合わせの犠牲者ではないことを教えています。私たちの現在の状況や課題を惑星のせいにすることはできません。私たちが今日経験していることは、それが好ましいものであるか、好ましくないものであるかにかかわらず、カルマの戻りの現れにすぎません。惑星はこれらのカルマを示しますが、それらを生み出すわけではありません。`, ko: `베다 점성술은 우리가 출생 차트나 그 안에 포함된 행성 조합의 희생자가 아니라고 더 가르칩니다. 우리의 현재 상황이나 도전에 대해 행성을 비난할 수는 없습니다. 오늘날 우리가 경험하고 있는 모든 것은 유리하든 불리하든지 간에 단순히 카르마가 되돌아오는 현상일 뿐입니다. 행성은 이러한 카르마를 나타내지만 카르마를 창조하지는 않습니다.`,} },
      { type: "paragraph", text: { en: `In Jyotish, the planets are often described as the "Cosmic Postman." During this lifetime, they deliver some of the consequences of actions carried over from previous incarnations. We tend to label these karmas as "positive" when they bring growth, happiness, or success, and "negative" when they result in obstacles or difficulties [2]. Yet these labels are largely subjective. From a higher level of consciousness, the distinction between positive and negative karma disappears—things simply are as they are.`, hi: `ज्योतिष में, ग्रहों को अक्सर "ब्रह्मांडीय डाकिया" के रूप में वर्णित किया जाता है। इस जीवनकाल के दौरान, वे पिछले अवतारों से किए गए कार्यों के कुछ परिणाम देते हैं। हम इन कर्मों को "सकारात्मक" के रूप में लेबल करते हैं जब वे विकास, खुशी या सफलता लाते हैं, और "नकारात्मक" के रूप में लेबल करते हैं जब उनके परिणामस्वरूप बाधाएं या कठिनाइयां आती हैं [2]। फिर भी ये लेबल काफी हद तक व्यक्तिपरक हैं। चेतना के उच्च स्तर से, सकारात्मक और नकारात्मक कर्म के बीच का अंतर गायब हो जाता है - चीजें बस वैसी ही हैं जैसी वे हैं।`, ja: `ジョーティッシュでは、惑星はしばしば「宇宙の郵便配達員」として描写されます。この生涯の間に、彼らは前の転生から引き継がれた行為の結果の一部をもたらします。私たちは、これらのカルマが成長、幸福、成功をもたらす場合には「ポジティブ」とラベル付けし、障害や困難をもたらす場合には「ネガティブ」とラベル付けする傾向があります[2]。しかし、これらのラベルは主に主観的なものです。より高い意識レベルからは、ポジティブなカルマとネガティブなカルマの区別はなくなり、物事は単にありのままになります。`, ko: `Jyotish에서는 행성을 종종 "우주 우체부"로 묘사합니다. 이번 생애 동안 그들은 이전 환생에서 이어진 행동의 결과 중 일부를 전달합니다. 우리는 이러한 카르마가 성장, 행복 또는 성공을 가져올 때 "긍정적" 카르마로 분류하고 장애물이나 어려움을 초래할 때 "부정적" 카르마로 분류하는 경향이 있습니다[2]. 그러나 이러한 라벨은 대체로 주관적입니다. 더 높은 수준의 의식에서는 긍정적인 카르마와 부정적인 카르마의 구별이 사라지고 사물은 있는 그대로 존재합니다.`,} },
      { type: "paragraph", text: { en: `A self-realized Vedic Master was once asked about free will and destiny. He replied that life consists of a combination of both. As an example, he explained that our height is largely predetermined, whereas our weight is influenced by our choices and actions. The audience immediately understood the point and laughed.`, hi: `एक बार एक आत्म-साक्षात्कारी वैदिक गुरु से स्वतंत्र इच्छा और नियति के बारे में पूछा गया। उन्होंने उत्तर दिया कि जीवन दोनों के संयोजन से बनता है। उदाहरण के तौर पर उन्होंने बताया कि हमारी ऊंचाई काफी हद तक पूर्व निर्धारित होती है, जबकि हमारा वजन हमारी पसंद और कार्यों से प्रभावित होता है। दर्शकों को तुरंत बात समझ आ गई और वे हंस पड़े.`, ja: `自己を実現したヴェーダのマスターは、かつて自由意志と運命について尋ねられました。彼は、人生は両方の組み合わせで構成されていると答えました。一例として、私たちの身長はほぼ決まっているのに対し、体重は私たちの選択や行動によって影響を受けると彼は説明しました。聴衆はすぐに要点を理解し、笑いました。`, ko: `자칭 베다 스승이 자유 의지와 운명에 관해 질문을 받은 적이 있습니다. 그는 인생은 두 가지의 조합으로 구성된다고 대답했습니다. 예를 들어, 그는 우리의 키가 대체로 미리 결정되어 있는 반면, 체중은 우리의 선택과 행동에 의해 영향을 받는다고 설명했습니다. 청중들은 곧바로 그 내용을 이해하고 웃었다.`,} },
      { type: "paragraph", text: { en: `In everyday life, many of our actions are karmically neutral. Following a reasonably vegetarian lifestyle is often said to support this balance.`, hi: `रोजमर्रा की जिंदगी में, हमारे कई कार्य कर्म की दृष्टि से तटस्थ होते हैं। अक्सर कहा जाता है कि उचित शाकाहारी जीवनशैली का पालन इस संतुलन को बनाए रखने में सहायक होता है।`, ja: `日常生活では、私たちの行動の多くはカルマ的に中立です。適度にベジタリアンのライフスタイルに従うことが、このバランスをサポートするとよく言われます。`, ko: `일상 생활에서 우리의 많은 행동은 카르마적으로 중립적입니다. 합리적으로 채식주의 생활 방식을 따르는 것이 종종 이러한 균형을 유지하는 것으로 알려져 있습니다.`,} },
      { type: "paragraph", text: { en: `Not only do our actions matter, but so do the intentions behind them. Through regular meditation and spiritual practices, our intentions become more aligned with evolution and natural growth, rather than being driven solely by impressions and tendencies carried over from previous lifetimes.`, hi: `न केवल हमारे कार्य मायने रखते हैं, बल्कि उनके पीछे के इरादे भी मायने रखते हैं। नियमित ध्यान और आध्यात्मिक प्रथाओं के माध्यम से, हमारे इरादे केवल पिछले जन्मों से प्राप्त छापों और प्रवृत्तियों से प्रेरित होने के बजाय, विकास और प्राकृतिक विकास के साथ अधिक संरेखित हो जाते हैं।`, ja: `私たちの行動が重要であるだけでなく、その背後にある意図も重要です。定期的な瞑想やスピリチュアルな実践を通じて、私たちの意図は前世から引き継がれた印象や傾向だけによって動かされるのではなく、進化や自然な成長とより一致するようになります。`, ko: `우리의 행동뿐만 아니라 그 뒤에 숨은 의도도 중요합니다. 정기적인 명상과 영적인 수행을 통해 우리의 의도는 전생에서 이어진 인상과 경향에 의해서만 움직이는 것이 아니라 진화와 자연적인 성장에 더욱 일치하게 됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Prediction and ‘Prevention’ in Jyotish`, hi: `ज्योतिष में भविष्यवाणी और 'रोकथाम'`, ja: `ジョーティッシュ語の予測と「予防」`, ko: `Jyotish의 예측과 '예방'`,} },
      { type: "paragraph", text: { en: `Jyotish enables us to both identify and redirect returning karmas. In this sense, it can truly be viewed as the ultimate Karmic Engineering System.`, hi: `ज्योतिष हमें लौटने वाले कर्मों को पहचानने और पुनर्निर्देशित करने में सक्षम बनाता है। इस अर्थ में, इसे वास्तव में परम कार्मिक इंजीनियरिंग प्रणाली के रूप में देखा जा सकता है।`, ja: `Jyotish を使用すると、戻ってくるカルマを特定し、リダイレクトすることができます。この意味で、それはまさに究極のカルマ工学システムとみなすことができます。`, ko: `Jyotish를 사용하면 돌아오는 카르마를 식별하고 방향을 바꿀 수 있습니다. 이런 의미에서 이는 진정한 카르마 공학 시스템(Karmic Engineering System)으로 볼 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `1. Detecting Returning Karmas in Vedic Astrology`, hi: `1. वैदिक ज्योतिष में रिटर्निंग कर्मों का पता लगाना`, ja: `1. ヴェーダ占星術で戻ってくるカルマを検出する`, ko: `1. 베다 점성술에서 카르마가 돌아오는 것을 감지`,} },
      { type: "paragraph", text: { en: `The major karmic influences and significant events likely to arise during an individual's current incarnation can be predicted through Jyotish. This involves interpreting the "code" contained within the planetary arrangements present at the moment of birth. Just as DNA contains the information that shapes human physiology, the planetary configuration at birth contains the code that reflects returning karmas [3].`, hi: `किसी व्यक्ति के वर्तमान अवतार के दौरान उत्पन्न होने वाले प्रमुख कार्मिक प्रभावों और महत्वपूर्ण घटनाओं की भविष्यवाणी ज्योतिष के माध्यम से की जा सकती है। इसमें जन्म के समय मौजूद ग्रहों की व्यवस्था के भीतर निहित "कोड" की व्याख्या करना शामिल है। जिस तरह डीएनए में वह जानकारी होती है जो मानव शरीर विज्ञान को आकार देती है, जन्म के समय ग्रहों के विन्यास में वह कोड होता है जो लौटते हुए कर्मों को दर्शाता है [3]।`, ja: `個人の現在の転生中に起こる可能性のある主要なカルマ的影響と重大な出来事は、ジョーティッシュを通じて予測できます。これには、誕生の瞬間に存在する惑星配置に含まれる「コード」を解釈することが含まれます。 DNA に人間の生理機能を形作る情報が含まれているのと同じように、出生時の惑星の配置には、戻ってくるカルマを反映するコードが含まれています [3]。`, ko: `개인의 현재 환생 동안 발생할 가능성이 있는 주요 카르마 영향과 중요한 사건은 Jyotish를 통해 예측할 수 있습니다. 여기에는 탄생 순간에 존재하는 행성 배열에 포함된 "코드"를 해석하는 것이 포함됩니다. DNA에 인간 생리학을 형성하는 정보가 포함되어 있는 것처럼, 출생 시 행성 구성에는 되돌아오는 카르마를 반영하는 코드가 포함되어 있습니다[3].`,} },
      { type: "paragraph", text: { en: `Predictions can be made across all major areas of life, including Artha, Dharma, Kama, and Moksha.`, hi: `अर्थ, धर्म, काम और मोक्ष सहित जीवन के सभी प्रमुख क्षेत्रों के बारे में भविष्यवाणियाँ की जा सकती हैं।`, ja: `予測は、アルタ、ダルマ、カーマ、モクシャなど、人生の主要な領域すべてにわたって行うことができます。`, ko: `Artha, Dharma, Kama 및 Moksha를 포함한 삶의 모든 주요 영역에 걸쳐 예측이 가능합니다.`,} },
      { type: "paragraph", text: { en: `Artha encompasses wealth in its broadest sense—financial prosperity, children, knowledge, food, health, and other forms of abundance.`, hi: `अर्थ अपने व्यापक अर्थों में धन को शामिल करता है - वित्तीय समृद्धि, बच्चे, ज्ञान, भोजन, स्वास्थ्य और प्रचुरता के अन्य रूप।`, ja: `アルタには、経済的繁栄、子供、知識、食べ物、健康、その他の形の豊かさなど、最も広い意味での富が含まれます。`, ko: `Artha는 재정적 번영, 자녀, 지식, 음식, 건강 및 기타 형태의 풍요 등 가장 넓은 의미의 부를 포함합니다.`,} },
      { type: "paragraph", text: { en: `Dharma relates to duty, character, righteous action, and activities that support evolution and natural law, including one's career path and life purpose.`, hi: `धर्म का संबंध कर्तव्य, चरित्र, धार्मिक कार्य और गतिविधियों से है जो किसी के करियर पथ और जीवन उद्देश्य सहित विकास और प्राकृतिक कानून का समर्थन करते हैं।`, ja: `ダルマは義務、性格、正義の行動、そして進化と自然法を支える活動（キャリアパスや人生の目的を含む）に関連しています。`, ko: `다르마는 개인의 진로와 삶의 목적을 포함하여 진화와 자연법을 지원하는 의무, 성품, 의로운 행동 및 활동과 관련이 있습니다.`,} },
      { type: "paragraph", text: { en: `Kama refers to desire and therefore includes relationships, pleasures of the senses, aspirations, and worldly enjoyments.`, hi: `काम का तात्पर्य इच्छा से है और इसलिए इसमें रिश्ते, इंद्रियों का सुख, आकांक्षाएं और सांसारिक आनंद शामिल हैं।`, ja: `カーマは欲望を指し、したがって人間関係、感覚の喜び、願望、世俗的な楽しみが含まれます。`, ko: `카마는 욕망을 의미하므로 관계, 감각의 즐거움, 열망, 세속적 즐거움을 포함합니다.`,} },
      { type: "paragraph", text: { en: `Moksha concerns spiritual development, personal growth, and the journey toward Self-realization.`, hi: `मोक्ष का संबंध आध्यात्मिक विकास, व्यक्तिगत विकास और आत्म-प्राप्ति की ओर यात्रा से है।`, ja: `モクシャは、精神的な発達、個人の成長、自己実現への旅に関係しています。`, ko: `목샤는 영적 발전, 개인적 성장, 자아 실현을 향한 여정에 관한 것입니다.`,} },
      { type: "paragraph", text: { en: `Jyotish can also indicate when these karmic influences are likely to manifest. This is achieved through the unique Maha Dasa system of Vedic Astrology [4], which is based on the Moon's position in the Nakshatras (constellations) at the time of birth.`, hi: `ज्योतिष यह भी संकेत दे सकता है कि ये कार्मिक प्रभाव कब प्रकट होने की संभावना है। यह वैदिक ज्योतिष की अनूठी महादशा प्रणाली [4] के माध्यम से प्राप्त किया जाता है, जो जन्म के समय नक्षत्रों में चंद्रमा की स्थिति पर आधारित है।`, ja: `ジョーティッシュは、これらのカルマ的影響がいつ現れる可能性があるかを示すこともできます。これは、出生時のナクシャトラ (星座) における月の位置に基づいた、ヴェーダ占星術の独自のマハ ダサ システム [4] によって実現されます。`, ko: `Jyotish는 또한 이러한 카르마 영향이 나타날 가능성이 있는 시기를 나타낼 수도 있습니다. 이는 탄생 당시 나크샤트라(별자리)에서 달의 위치를 ​​기반으로 하는 베다 점성술의 독특한 마하다사 시스템[4]을 통해 달성됩니다.`,} },
      { type: "heading", level: 3, text: { en: `2. Deflecting Returning Karmas in Vedic Astrology`, hi: `2. वैदिक ज्योतिष में कर्मों की वापसी को विक्षेपित करना`, ja: `2. ヴェーダ占星術で戻ってくるカルマをそらす`, ko: `2. 베다 점성술에서 돌아오는 카르마를 편향시키다`,} },
      { type: "paragraph", text: { en: `The Vedic tradition promotes a life that is healthy, happy, and fulfilling. Consequently, Vedic Astrology contains a wide range of remedial measures intended to significantly reduce the impact of returning negative karmas. These remedies help restore balance, harmony, and well-being.`, hi: `वैदिक परंपरा ऐसे जीवन को बढ़ावा देती है जो स्वस्थ, सुखी और पूर्ण हो। नतीजतन, वैदिक ज्योतिष में नकारात्मक कर्मों के प्रभाव को महत्वपूर्ण रूप से कम करने के उद्देश्य से उपचारात्मक उपायों की एक विस्तृत श्रृंखला शामिल है। ये उपाय संतुलन, सद्भाव और कल्याण बहाल करने में मदद करते हैं।`, ja: `ヴェーダの伝統は、健康で幸せで充実した生活を促進します。その結果、ヴェーダ占星術には、ネガティブなカルマの帰還による影響を大幅に軽減することを目的とした幅広い改善法が含まれています。これらの治療法は、バランス、調和、幸福を回復するのに役立ちます。`, ko: `베다 전통은 건강하고 행복하며 만족스러운 삶을 장려합니다. 결과적으로 베다 점성술에는 부정적인 카르마 반환의 영향을 크게 줄이기 위한 광범위한 교정 조치가 포함되어 있습니다. 이러한 치료법은 균형, 조화, 웰빙을 회복하는 데 도움이 됩니다.`,} },
      { type: "paragraph", text: { en: `Their effectiveness is based on the understanding that we are all part of an interconnected whole. By participating in Vedic ceremonies such as Yagnas, Yagyas, or Homas, performing prescribed acts of charity, reciting specific Sanskrit mantras, or wearing suitable gemstones, it is believed that returning karmas can be modified or deflected to a considerable degree.`, hi: `उनकी प्रभावशीलता इस समझ पर आधारित है कि हम सभी एक दूसरे से जुड़े पूरे हिस्से का हिस्सा हैं। यज्ञ, यज्ञ या होम जैसे वैदिक समारोहों में भाग लेने, दान के निर्धारित कार्य करने, विशिष्ट संस्कृत मंत्रों का पाठ करने, या उपयुक्त रत्न पहनने से, यह माना जाता है कि लौटने वाले कर्मों को काफी हद तक संशोधित या विक्षेपित किया जा सकता है।`, ja: `それらの有効性は、私たち全員が相互に接続された全体の一部であるという理解に基づいています。ヤグナス、ヤギャ、ホーマなどのヴェーダの儀式に参加したり、所定の慈善行為を行ったり、特定のサンスクリット語のマントラを暗唱したり、適切な宝石を身に着けたりすることによって、戻ってきたカルマをかなりの程度修正または偏向できると考えられています。`, ko: `그 효과는 우리 모두가 상호 연결된 전체의 일부라는 이해에 기초합니다. Yagnas, Yagyas 또는 Homas와 같은 베다 의식에 참여하고, 규정된 자선 행위를 수행하고, 특정 산스크리트어 만트라를 낭송하거나, 적절한 보석을 착용함으로써 카르마가 돌아오거나 상당한 정도로 편향될 수 있다고 믿어집니다.`,} },
      { type: "paragraph", text: { en: `As a result, an individual may not need to experience the full karmic consequences during the present lifetime. At the same time, Jyotish remedies can strengthen the beneficial effects of positive karmas. For this reason, Jyotish may rightly be considered the ultimate Karmic Engineering System.`, hi: `परिणामस्वरूप, किसी व्यक्ति को वर्तमान जीवनकाल के दौरान पूर्ण कर्म परिणामों का अनुभव करने की आवश्यकता नहीं हो सकती है। साथ ही, ज्योतिष उपाय सकारात्मक कर्मों के लाभकारी प्रभाव को मजबूत कर सकते हैं। इस कारण से, ज्योतिष को सर्वोत्तम कार्मिक इंजीनियरिंग प्रणाली माना जा सकता है।`, ja: `その結果、人は今生でカルマの結果をすべて経験する必要がないかもしれません。同時に、ジョーティッシュの治療法は、ポジティブなカルマの有益な効果を強化することができます。このため、ジョーティッシュは究極のカルマ工学システムであると考えるのが当然かもしれません。`, ko: `결과적으로 개인은 현 생애 동안 완전한 카르마 결과를 경험할 필요가 없을 수도 있습니다. 동시에 Jyotish 치료법은 긍정적인 카르마의 유익한 효과를 강화할 수 있습니다. 이러한 이유로 Jyotish는 궁극적인 Karmic Engineering System으로 간주될 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `3. Spiritual Practices Deflect Negative Karma`, hi: `3. आध्यात्मिक अभ्यास नकारात्मक कर्म को दूर करता है`, ja: `3. スピリチュアルな実践はネガティブなカルマをそらす`, ko: `3. 영적 실천은 부정적인 카르마를 빗나가게 합니다`,} },
      { type: "paragraph", text: { en: `Returning karmas can also be profoundly influenced by the spiritual practices we undertake during this lifetime.`, hi: `कर्मों की वापसी भी इस जीवनकाल के दौरान हमारे द्वारा की जाने वाली आध्यात्मिक प्रथाओं से गहराई से प्रभावित हो सकती है।`, ja: `カルマの返却は、私たちがこの生涯で行うスピリチュアルな実践にも大きく影響される可能性があります。`, ko: `돌아오는 카르마는 또한 이번 생애 동안 우리가 수행하는 영적 수행에 의해 깊은 영향을 받을 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Most experienced Jyotish astrologers will agree that regular meditation and sadhana (spiritual practice) noticeably reduce the predicted effects of difficult karmas. Many spiritual Masters have taught that destiny itself can be transformed through daily meditation, chanting, pranayama, and related disciplines.`, hi: `अधिकांश अनुभवी ज्योतिषी इस बात से सहमत होंगे कि नियमित ध्यान और साधना (आध्यात्मिक अभ्यास) कठिन कर्मों के अनुमानित प्रभावों को काफी कम कर देते हैं। कई आध्यात्मिक गुरुओं ने सिखाया है कि दैनिक ध्यान, जप, प्राणायाम और संबंधित अनुशासनों के माध्यम से भाग्य को बदला जा सकता है।`, ja: `ほとんどの経験豊富なジョーティッシュ師は、定期的な瞑想とサーダナ (霊性修行) が、予測される困難なカルマの影響を著しく軽減することに同意するでしょう。多くのスピリチュアルなマスターは、毎日の瞑想、詠唱、プラーナヤーマ、および関連する修行を通じて運命そのものを変えることができると教えてきました。`, ko: `대부분의 경험이 풍부한 Jyotish 점성가들은 정기적인 명상과 사다나(영적 수행)가 어려운 카르마의 예상 효과를 눈에 띄게 감소시킨다는 데 동의할 것입니다. 많은 영적 스승들은 매일의 명상, 구호, 프라나야마 및 관련 훈련을 통해 운명 자체가 바뀔 수 있다고 가르쳤습니다.`,} },
      { type: "paragraph", text: { en: `The great Spiritual Master Paramahansa Yogananda [5] affirmed this principle when he stated that as an individual moves "into the orbit of the Divine, they move out of the orbit of planetary influences."`, hi: `महान आध्यात्मिक गुरु परमहंस योगानंद [5] ने इस सिद्धांत की पुष्टि की जब उन्होंने कहा कि जैसे ही कोई व्यक्ति "ईश्वर की कक्षा में जाता है, वे ग्रहों के प्रभाव की कक्षा से बाहर चले जाते हैं।"`, ja: `偉大なスピリチュアルマスター、パラマハンサ・ヨガナンダ[5]は、個人が「神の軌道に入るにつれて、惑星の影響の軌道から外に出る」と述べ、この原則を肯定しました。`, ko: `위대한 영적 스승인 파라마한사 요가난다(Paramahansa Yogananda)[5]는 개인이 "신성의 궤도로 들어갈 때 행성 영향의 궤도에서 벗어난다"고 말하면서 이 원칙을 확증했습니다.`,} },
      { type: "paragraph", text: { en: `Those fortunate enough to have a Self-realized Spiritual Master (Guru) should also recognize the power of the Guru's Grace, which can remove major obstacles and greatly lessen the impact of returning negative karmas.`, hi: `जो भाग्यशाली हैं कि उन्हें आत्म-साक्षात्कारी आध्यात्मिक गुरु (गुरु) मिला है, उन्हें गुरु की कृपा की शक्ति को भी पहचानना चाहिए, जो बड़ी बाधाओं को दूर कर सकती है और नकारात्मक कर्मों के प्रभाव को बहुत कम कर सकती है।`, ja: `自己実現したスピリチュアルマスター（グル）を持つ幸運な人々は、大きな障害を取り除き、ネガティブなカルマを返すことによる影響を大幅に軽減できるグルの恩寵の力も認識すべきです。`, ko: `자아실현 영적 스승(구루)을 가질 만큼 운이 좋은 사람들은 주요 장애물을 제거하고 부정적인 카르마 반환의 영향을 크게 줄일 수 있는 구루의 은총의 힘을 인식해야 합니다.`,} },
    ],
  },
  {
    id: "three-types-karma",
    section: "introduction",
    title: { en: `Three Types of Karma – Sanchita, Prarabdha and Agami`, hi: `कर्म के तीन प्रकार - संचित, प्रारब्ध और अगामी`, ja: `3 種類のカルマ – サンチタ、プララブダ、アガミ`, ko: `카르마의 세 가지 유형 - Sanchita, Prarabdha 및 Agami`,},
    related: ["jyotish-and-karma","mahadashas","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Three Types of Karma – Sanchita, Prarabdha and Agami`, hi: `कर्म के तीन प्रकार - संचित, प्रारब्ध और अगामी`, ja: `3 種類のカルマ – サンチタ、プララブダ、アガミ`, ko: `카르마의 세 가지 유형 - Sanchita, Prarabdha 및 Agami`,} },
      { type: "paragraph", text: { en: `The Vedas clearly describe three primary categories of karma: Sanchita, Prarabdha, and Agami. Jyotish Astrology is primarily concerned with the Prarabdha aspect of karma [6]. However, when Self-realization is attained, all karmas associated with previous lives are transcended.`, hi: `वेद स्पष्ट रूप से कर्म की तीन प्राथमिक श्रेणियों का वर्णन करते हैं: संचित, प्रारब्ध और अगामी। ज्योतिष मुख्य रूप से कर्म के प्रारब्ध पहलू से संबंधित है [6]। हालाँकि, जब आत्म-साक्षात्कार प्राप्त हो जाता है, तो पिछले जन्मों से जुड़े सभी कर्मों से मुक्ति मिल जाती है।`, ja: `ヴェーダには、カルマの 3 つの主要なカテゴリ、サンチタ、プララブダ、アガミが明確に説明されています。ジョーティッシュは主にカルマのプララブダの側面に関係しています [6]。しかし、自己実現が達成されると、前世に関連したすべてのカルマが超越されます。`, ko: `Vedas는 카르마의 세 가지 기본 범주인 Sanchita, Prarabdha 및 Agami를 명확하게 설명합니다. Jyotish 점성술은 주로 카르마의 Prarabdha 측면과 관련이 있습니다 [6]. 그러나 진아 깨달음을 얻으면 전생과 관련된 모든 카르마가 초월됩니다.`,} },
      { type: "paragraph", text: { en: `On a personal note: I have complete confidence in the effectiveness of Jyotish remedial measures for reducing suffering in this lifetime. Nevertheless, certain questions remain. Are we genuinely reducing karmas, or merely postponing them to a future incarnation? Can karma truly be modified in this way? Or does an individual possess sufficient positive karma within their karmic "storehouse"—their own karmic credit account—to encounter a Jyotish astrologer and receive guidance regarding these remedies in the first place? Such questions are perhaps best answered by an enlightened Master.`, hi: `एक निजी टिप्पणी पर: मुझे इस जीवनकाल में कष्टों को कम करने के लिए ज्योतिष उपचार उपायों की प्रभावशीलता पर पूरा भरोसा है। फिर भी, कुछ प्रश्न बने हुए हैं। क्या हम वास्तव में कर्मों को कम कर रहे हैं, या केवल उन्हें भविष्य के अवतार के लिए स्थगित कर रहे हैं? क्या कर्म को सचमुच इस तरह से संशोधित किया जा सकता है? या क्या किसी व्यक्ति के पास अपने कर्म "भंडार" - अपने स्वयं के कर्म क्रेडिट खाते - के भीतर एक ज्योतिषी ज्योतिषी से मिलने और पहले स्थान पर इन उपायों के बारे में मार्गदर्शन प्राप्त करने के लिए पर्याप्त सकारात्मक कर्म हैं? ऐसे प्रश्नों का उत्तर शायद एक प्रबुद्ध गुरु द्वारा सबसे अच्छा दिया जा सकता है।`, ja: `個人的なメモですが、私はこの世での苦しみを軽減するためのジョーティッシュの改善法の有効性に完全な自信を持っています。それにもかかわらず、いくつかの疑問が残ります。私たちは本当にカルマを減らしているのでしょうか、それとも単にカルマを将来の転生に延期しているだけなのでしょうか？カルマは本当にこのように修正できるのでしょうか?それとも、個人は、そもそもジョーティッシュ師に会い、これらの治療法に関する指導を受けるのに十分な、カルマの「倉庫」、つまり自分自身のカルマ信用口座の中に十分なポジティブなカルマを持っているのでしょうか？このような質問には、おそらく啓発されたマスターが最もよく答えてくれます。`, ko: `개인적으로: 나는 이번 생애의 고통을 줄이기 위한 Jyotish 치료 조치의 효과에 대해 완전한 확신을 가지고 있습니다. 그럼에도 불구하고 몇 가지 질문이 남아 있습니다. 우리는 진정으로 카르마를 줄이는 것인가, 아니면 단순히 미래의 화신으로 연기하는 것인가? 카르마가 정말로 이런 식으로 수정될 수 있습니까? 아니면 개인이 자신의 카르마 "창고"(자신의 카르마 신용 계정) 내에 Jyotish 점성가를 만나고 이러한 치료법에 대한 지침을 받을 수 있을 만큼 충분한 긍정적 카르마를 보유하고 있습니까? 그러한 질문에 대해서는 깨달은 스승이 가장 잘 대답할 수 있을 것입니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "heading", level: 3, text: { en: `[1]`, hi: `[1]`, ja: `[1]`, ko: `[1]`,} },
      { type: "paragraph", text: { en: `Samskaras are deep-rooted impressions and desires left within the mind by past actions, including those from previous lifetimes. In the Vedic understanding, the mind is not confined to the brain; rather, it extends beyond and surrounds the body. One Vedic pundit described these latent impressions as "post-it notes attached to the soul."`, hi: `संस्कार पिछले जन्मों सहित पिछले कर्मों द्वारा मन में छोड़े गए गहरे प्रभाव और इच्छाएँ हैं। वैदिक समझ में, मन मस्तिष्क तक ही सीमित नहीं है; बल्कि, यह शरीर से आगे तक फैलता है और उसे घेर लेता है। एक वैदिक पंडित ने इन अव्यक्त छापों को "आत्मा से जुड़े पोस्ट-इट नोट्स" के रूप में वर्णित किया।`, ja: `サムスカーラとは、前世を含む過去の行為によって心の中に残された根深い印象や願望です。ヴェーダの理解では、心は脳に限定されません。むしろ、それは身体を超えて広がり、身体を取り囲んでいます。あるヴェーダの専門家は、これらの潜在的な印象を「魂に貼り付けられた付箋」と表現しました。`, ko: `삼스카라(Samskaras)는 전생의 행동을 포함하여 과거의 행동에 의해 마음속에 남겨진 뿌리 깊은 인상과 욕망입니다. 베다의 이해에서 마음은 뇌에만 국한되지 않습니다. 오히려 그것은 몸을 넘어 확장되어 몸을 둘러쌉니다. 한 베다 전문가는 이러한 잠재 인상을 "영혼에 붙인 포스트잇"이라고 묘사했습니다.`,} },
      { type: "paragraph", text: { en: `Karma is frequently illustrated as a wheel. Latent impressions in the mind generate actions, those actions create new impressions, and future actions are then influenced by those impressions. The process continues cyclically. Through meditation and spiritual practices, however, this cycle can be broken. Karma and samskara are therefore inseparably connected.`, hi: `कर्म को अक्सर एक पहिये के रूप में चित्रित किया जाता है। मन में गुप्त संस्कार क्रियाएं उत्पन्न करते हैं, वे क्रियाएं नए प्रभाव पैदा करती हैं और भविष्य की क्रियाएं उन संस्कारों से प्रभावित होती हैं। यह प्रक्रिया चक्रीय रूप से जारी रहती है। हालाँकि, ध्यान और आध्यात्मिक अभ्यास के माध्यम से, इस चक्र को तोड़ा जा सकता है। इसलिए कर्म और संस्कार अविभाज्य रूप से जुड़े हुए हैं।`, ja: `カルマは車輪として描かれることがよくあります。心の潜在的な印象が行動を生み出し、その行動が新たな印象を生み出し、その後の行動はその印象に影響を受けます。このプロセスは周期的に継続します。しかし、瞑想やスピリチュアルな実践を通じて、このサイクルを断ち切ることができます。したがって、カルマとサムスカーラは切り離せない関係にあります。`, ko: `카르마는 종종 바퀴로 묘사됩니다. 마음 속에 잠재된 인상은 행동을 만들고, 그 행동은 새로운 인상을 만들고, 미래의 행동은 그 인상의 영향을 받습니다. 프로세스는 주기적으로 계속됩니다. 그러나 명상과 영적인 수행을 통해 이러한 순환은 깨질 수 있습니다. 따라서 카르마와 삼스카라는 뗄래야 뗄 수 없는 관계입니다.`,} },
      { type: "heading", level: 3, text: { en: `[2]`, hi: `[2]`, ja: `[2]`, ko: `[2]`,} },
      { type: "paragraph", text: { en: `What creates negative karma? One Vedic scholar explained it simply: "doing to others what we would not wish done to ourselves." This principle may reasonably be extended to our treatment of all living beings and the natural environment.`, hi: `नकारात्मक कर्म क्या बनाता है? एक वैदिक विद्वान ने इसे सरलता से समझाया: "दूसरों के साथ वह करना जो हम नहीं चाहते कि हमारे साथ किया जाए।" इस सिद्धांत को उचित रूप से सभी जीवित प्राणियों और प्राकृतिक पर्यावरण के प्रति हमारे उपचार तक बढ़ाया जा सकता है।`, ja: `何がマイナスのカルマを生み出すのでしょうか？あるヴェーダ学者はそれを簡単に説明しました、「自分にしてほしくないことを他人にすること」です。この原則は、すべての生き物と自然環境の扱いにも合理的に拡張できます。`, ko: `부정적인 카르마를 만드는 것은 무엇입니까? 한 베다 학자는 이를 간단하게 설명했습니다. "우리가 자신에게 행해지고 싶지 않은 일을 다른 사람에게 행하는 것." 이 원칙은 모든 생명체와 자연 환경을 다루는 데까지 합리적으로 확장될 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `[3]`, hi: `[3]`, ja: `[3]`, ko: `[3]`,} },
      { type: "paragraph", text: { en: `Karmic influences affecting every aspect of life are interpreted in Vedic Astrology through the positions of the nine planets within the twelve zodiac signs, twelve houses, and twenty-seven Nakshatras, as shown in a person's birth chart calculated using the sidereal zodiac.`, hi: `जीवन के हर पहलू को प्रभावित करने वाले कर्म प्रभावों की व्याख्या वैदिक ज्योतिष में बारह राशियों, बारह घरों और सत्ताईस नक्षत्रों के भीतर नौ ग्रहों की स्थिति के माध्यम से की जाती है, जैसा कि किसी व्यक्ति के जन्म चार्ट में नक्षत्र राशि चक्र का उपयोग करके गणना की जाती है।`, ja: `人生のあらゆる側面に影響を与えるカルマの影響は、恒星黄道帯を使用して計算された人の出生図に示されるように、ヴェーダ占星術では、12 の星座、12 ハウス、27 のナクシャトラ内の 9 つの惑星の位置を通じて解釈されます。`, ko: `삶의 모든 측면에 영향을 미치는 카르마의 영향은 항성 황도대를 사용하여 계산된 사람의 출생 차트에 표시된 대로 베다 점성술에서 12개의 황도대 별자리, 12개의 집, 27개의 나크샤트라 내의 9개 행성의 위치를 ​​통해 해석됩니다.`,} },
      { type: "heading", level: 3, text: { en: `[4]`, hi: `[4]`, ja: `[4]`, ko: `[4]`,} },
      { type: "paragraph", text: { en: `The timing of karmic influences that are likely to become prominent in life is calculated through the Vimsottari Maha Dasha system, based on the natal position of the Moon within one of the twenty-seven Nakshatras.`, hi: `जीवन में प्रमुख होने की संभावना वाले कर्म प्रभावों के समय की गणना विम्सोत्तरी महादशा प्रणाली के माध्यम से की जाती है, जो सत्ताईस नक्षत्रों में से एक के भीतर चंद्रमा की जन्मकालीन स्थिति पर आधारित होती है।`, ja: `人生において顕著になる可能性のあるカルマ的影響のタイミングは、27 のナクシャトラの 1 つにおける月の出生位置に基づいて、ヴィムショッタリ マハ ダシャ システムを通じて計算されます。`, ko: `인생에서 두드러지게 나타날 가능성이 있는 카르마 영향의 시기는 27개의 나크샤트라 중 하나에 있는 달의 출생 위치를 기준으로 Vimsottari Maha Dasha 시스템을 통해 계산됩니다.`,} },
      { type: "heading", level: 3, text: { en: `[5]`, hi: `[5]`, ja: `[5]`, ko: `[5]`,} },
      { type: "paragraph", text: { en: `Paramahansa Yogananda (1893–1952) was a Self-realized sage who spent a significant portion of his life in the West teaching yoga and Vedic philosophy. His most widely read and highly recommended work is the Autobiography of a Yogi, published by the Yogoda Satsanga Society of India.`, hi: `परमहंस योगानंद (1893-1952) एक आत्म-साक्षात्कारी संत थे, जिन्होंने अपने जीवन का एक महत्वपूर्ण हिस्सा पश्चिम में योग और वैदिक दर्शन की शिक्षा देने में बिताया। उनका सबसे अधिक पढ़ा जाने वाला और अत्यधिक अनुशंसित कार्य योगदा सत्संग सोसाइटी ऑफ इंडिया द्वारा प्रकाशित एक योगी की आत्मकथा है।`, ja: `パラマハンサ ヨガナンダ (1893 ～ 1952 年) は、人生のかなりの部分を西洋で過ごし、ヨガとヴェーダ哲学を教えた自己実現の聖者でした。彼の最も広く読まれ、強く推奨されている著書は、インドのヨゴダ・サットサンガ協会から出版された『あるヨギの自伝』です。`, ko: `파라마한사 요가난다(1893~1952)는 서양에서 요가와 베다 철학을 가르치며 인생의 상당 부분을 보낸 자각한 현자였습니다. 그의 가장 널리 읽히고 적극 권장되는 작품은 인도 요고다 사차 협회(Yogoda Satsanga Society of India)에서 출판한 요기의 자서전(Autobiography of a Yogi)입니다.`,} },
      { type: "paragraph", text: { en: `2013 Edition: ISBN-10: 818953551X`, hi: `2013 संस्करण: आईएसबीएन-10: 818953551एक्स`, ja: `2013 年版: ISBN-10: 818953551X`, ko: `2013년 판: ISBN-10: 818953551X`,} },
      { type: "paragraph", text: { en: `ISBN-13: 978-8189535513`, hi: `आईएसबीएन-13: 978-8189535513`, ja: `ISBN-13: 978-8189535513`, ko: `ISBN-13: 978-8189535513`,} },
      { type: "heading", level: 3, text: { en: `[6]`, hi: `[6]`, ja: `[6]`, ko: `[6]`,} },
      { type: "heading", level: 3, text: { en: `Categories of Karma`, hi: `कर्म की श्रेणियाँ`, ja: `カルマのカテゴリー`, ko: `카르마의 종류`,} },
      { type: "paragraph", text: { en: `• Sanchita – The accumulated storehouse of all karmas from previous births.`, hi: `• संचिता - पिछले जन्मों के सभी कर्मों का संचित भण्डार।`, ja: `• サンチタ – 前世からのすべてのカルマが蓄積された倉庫。`, ko: `• 산치타 – 전생의 모든 카르마가 축적된 창고입니다.`,} },
      { type: "paragraph", text: { en: `• Prarabdha – The portion of Sanchita karma that must be experienced and worked through in the current lifetime. It is often said that Prarabdha karma is best suited to support our evolutionary growth in this incarnation.`, hi: `• प्रारब्ध - संचित कर्म का वह भाग जिसे वर्तमान जीवनकाल में अनुभव किया जाना चाहिए और काम किया जाना चाहिए। यह अक्सर कहा जाता है कि प्रारब्ध कर्म इस अवतार में हमारे विकासवादी विकास का समर्थन करने के लिए सबसे उपयुक्त है।`, ja: `• プララブダ – サンチタ カルマのうち、今生で経験し、乗り越えなければならない部分。プララブダのカルマは、この転生における私たちの進化的成長をサポートするのに最も適しているとよく言われます。`, ko: `• Prarabdha – 현생에서 경험하고 해결해야 하는 Sanchita 카르마의 일부입니다. Prarabdha 카르마는 이 화신에서 우리의 진화적 성장을 지원하는 데 가장 적합하다고 종종 말합니다.`,} },
      { type: "paragraph", text: { en: `• Agami – The new karma generated in this lifetime that will be carried forward into future incarnations.`, hi: `• अगामी - इस जीवनकाल में उत्पन्न नए कर्म जिन्हें भविष्य के अवतारों में आगे बढ़ाया जाएगा।`, ja: `• アガミ – この生涯で生成され、将来の転生に引き継がれる新しいカルマ。`, ko: `• 아가미(Agami) – 이번 생애에 생성된 새로운 카르마로 미래의 화신으로 이어집니다.`,} },
      { type: "paragraph", text: { en: `Jyotish – Sidereal Zodiac`, hi: `ज्योतिष - नाक्षत्र राशि चक्र`, ja: `ジョーティッシュ – 恒星黄道帯`, ko: `Jyotish – 항성 황도대`,} },
      { type: "paragraph", text: { en: `Summary: This article explores the differences between the zodiacs used in Vedic Astrology and Western Astrology. It explains why Jyotish relies on the fixed Sidereal Zodiac rather than the movable Tropical Zodiac, thereby addressing one of the main objections astronomers raise against astrology. The article also illustrates how Sun signs, Ascendants, and planetary positions can appear in different zodiac signs when calculated using these two systems.`, hi: `सारांश: यह लेख वैदिक ज्योतिष और पश्चिमी ज्योतिष में प्रयुक्त राशियों के बीच अंतर की पड़ताल करता है। यह बताता है कि ज्योतिष चल उष्णकटिबंधीय राशि चक्र के बजाय निश्चित नाक्षत्र राशि चक्र पर भरोसा क्यों करता है, जिससे खगोलविदों द्वारा ज्योतिष के खिलाफ उठाए गए मुख्य आपत्तियों में से एक को संबोधित किया जाता है। लेख यह भी बताता है कि इन दो प्रणालियों का उपयोग करके गणना करने पर सूर्य चिन्ह, लग्न और ग्रहों की स्थिति विभिन्न राशियों में कैसे दिखाई दे सकती है।`, ja: `概要: この記事では、ヴェーダ占星術と西洋占星術で使用される黄道帯の違いについて説明します。これは、ジョーティッシュが移動可能な熱帯黄道帯ではなく、固定された恒星黄道帯に依存している理由を説明し、それによって天文学者が占星術に対して提起する主な反対の 1 つに対処します。この記事では、これら 2 つのシステムを使用して計算した場合に、太陽星座、アセンダント、惑星の位置がさまざまな星座でどのように表示されるかについても説明します。`, ko: `요약: 이 기사에서는 베다 점성술과 서양 점성술에 사용되는 황도대 간의 차이점을 탐구합니다. 이는 Jyotish가 이동 가능한 열대 황도대보다는 고정된 항성 황도대에 의존하는 이유를 설명하여 천문학자들이 점성술에 대해 제기하는 주요 반대 의견 중 하나를 해결합니다. 이 기사에서는 또한 이 두 시스템을 사용하여 계산할 때 태양 별자리, 어센던트 및 행성 위치가 서로 다른 황도대 별자리에 나타날 수 있는 방법을 설명합니다.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish Uses the Fixed Sidereal Zodiac`, hi: `ज्योतिष स्थिर नक्षत्र राशि चक्र का उपयोग करता है`, ja: `ジョーティッシュは固定恒星黄道帯を使用します`, ko: `Jyotish는 고정 항성 황도대를 사용합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish Astrology employs a different zodiac system from the one commonly used in Western Astrology.`, hi: `ज्योतिष पश्चिमी ज्योतिष में आमतौर पर उपयोग की जाने वाली राशि से भिन्न राशि प्रणाली का उपयोग करता है।`, ja: `ジョーティッシュは、西洋占星術で一般的に使用されているものとは異なる黄道帯システムを採用しています。`, ko: `Jyotish 점성술은 서양 점성술에서 일반적으로 사용되는 것과는 다른 황도대 시스템을 사용합니다.`,} },
      { type: "paragraph", text: { en: `Both Jyotish and Western Astrology are based on an imaginary celestial sphere surrounding the Earth. In each system, this sphere is divided into twelve equal sections of 30 degrees each, much like the segments of an orange. The same zodiac sign names—Aries, Taurus, Gemini, and so on—are used in both traditions. The Sun appears to move through each zodiac sign in approximately one month.`, hi: `ज्योतिष और पश्चिमी ज्योतिष दोनों ही पृथ्वी के चारों ओर एक काल्पनिक खगोलीय क्षेत्र पर आधारित हैं। प्रत्येक प्रणाली में, इस गोले को नारंगी के खंडों की तरह, प्रत्येक 30 डिग्री के बारह बराबर खंडों में विभाजित किया गया है। दोनों परंपराओं में समान राशि चिन्हों के नाम—मेष, वृषभ, मिथुन इत्यादि—का उपयोग किया जाता है। ऐसा प्रतीत होता है कि सूर्य लगभग एक महीने में प्रत्येक राशि से होकर गुजरता है।`, ja: `ジョーティッシュと西洋占星術はどちらも、地球を取り囲む想像上の天球に基づいています。各システムでは、この球は、オレンジのセグメントとよく似た、それぞれ 30 度の 12 の等しいセクションに分割されます。どちらの伝統でも、同じ星座の名前 (牡羊座、牡牛座、双子座など) が使用されています。太陽は約 1 か月かけて各星座を移動するように見えます。`, ko: `Jyotish와 Western Astrology는 모두 지구를 둘러싼 가상의 천구를 기반으로합니다. 각 시스템에서 이 구는 오렌지 조각과 마찬가지로 각각 30도씩 동일한 12개의 섹션으로 나뉩니다. 양자리, 황소자리, 쌍둥이자리 등 동일한 황도대 표시 이름이 두 전통 모두에서 사용됩니다. 태양은 대략 한 달에 걸쳐 각 황도대 별자리를 통과하는 것으로 보입니다.`,} },
      { type: "paragraph", text: { en: `Jyotish uses the fixed, or Sidereal Zodiac. The term sidereal means "with respect to the stars." The starting point of the Sidereal Zodiac is permanently fixed using the background of the seemingly non-moving stars within our galaxy as a reference [1]. As a result, the zodiac signs remain consistently aligned with the stellar constellations. The beginning of the first sign, Aries, therefore remains fixed in Vedic Astrology, and all the other zodiac signs maintain their permanent relationship to the distant background stars.`, hi: `ज्योतिष स्थिर, या नाक्षत्र राशि चक्र का उपयोग करता है। नाक्षत्र शब्द का अर्थ है "सितारों के संबंध में।" संदर्भ के रूप में हमारी आकाशगंगा के भीतर प्रतीत होने वाले गतिहीन तारों की पृष्ठभूमि का उपयोग करके नाक्षत्र राशि चक्र का प्रारंभिक बिंदु स्थायी रूप से तय किया गया है [1]। परिणामस्वरूप, राशियाँ तारकीय नक्षत्रों के साथ लगातार संरेखित रहती हैं। इसलिए, पहली राशि मेष की शुरुआत वैदिक ज्योतिष में तय रहती है, और अन्य सभी राशियाँ दूर के पृष्ठभूमि सितारों के साथ अपना स्थायी संबंध बनाए रखती हैं।`, ja: `Jyotish は固定黄道帯、つまり恒星黄道帯を使用します。恒星という用語は「星に関して」を意味します。恒星黄道帯の開始点は、銀河内の一見動かない星の背景を参照として使用して永続的に固定されます [1]。その結果、黄道十二宮は常に星座と一致した状態を保ちます。したがって、最初の星座の始まりである牡羊座はヴェーダ占星術では固定されたままであり、他のすべての星座は遠くの背景の星との永続的な関係を維持します。`, ko: `Jyotish는 고정 또는 항성 황도대를 사용합니다. 항성이라는 용어는 "별과 관련하여"를 의미합니다. 항성 황도대의 시작점은 우리 은하계 내에서 겉보기에 움직이지 않는 별들의 배경을 기준으로 하여 영구적으로 고정되어 있습니다 [1]. 결과적으로, 황도대 별자리는 항성 별자리와 일관되게 정렬되어 있습니다. 따라서 첫 번째 별자리의 시작인 양자리는 베다 점성술에서 고정되어 있으며, 다른 모든 황도대 별자리는 먼 배경 별과 영구적인 관계를 유지합니다.`,} },
      { type: "paragraph", text: { en: `Western Astrology, by contrast, uses the Tropical Zodiac, which is movable. The starting point of this zodiac gradually shifts relative to the background of the fixed stars because it is tied to the position of the equinox. This movement occurs due to the astronomically observed phenomenon known as the precession of the equinoxes [2].`, hi: `इसके विपरीत, पश्चिमी ज्योतिष उष्णकटिबंधीय राशि चक्र का उपयोग करता है, जो गतिशील है। इस राशि का प्रारंभिक बिंदु धीरे-धीरे स्थिर तारों की पृष्ठभूमि के सापेक्ष बदलता रहता है क्योंकि यह विषुव की स्थिति से बंधा होता है। यह हलचल खगोलीय रूप से देखी गई घटना के कारण होती है जिसे विषुव की पूर्वता के रूप में जाना जाता है [2]।`, ja: `対照的に、西洋占星術では、移動可能なトロピカル ゾディアックが使用されます。この黄道帯の開始点は、春分点の位置に関連付けられているため、恒星の背景に対して徐々に移動します。この動きは、春分点の歳差運動として知られる天文学的に観察される現象によって発生します [2]。`, ko: `대조적으로, 서양 점성술은 움직일 수 있는 열대 황도대를 사용합니다. 이 황도대의 시작점은 분점의 위치에 묶여 있기 때문에 고정된 별의 배경을 기준으로 점차 이동합니다. 이러한 움직임은 분점 세차 운동으로 알려진 천문학적으로 관찰된 현상으로 인해 발생합니다[2].`,} },
      { type: "paragraph", text: { en: `Consequently, in Western Astrology the sign referred to as Aries slowly changes its position in the sky relative to the fixed stars over long periods of time. It is not permanently connected to a specific stellar constellation. Many people, including students of Western Astrology, find this fact quite surprising when they first encounter it.`, hi: `नतीजतन, पश्चिमी ज्योतिष में मेष राशि का चिन्ह लंबे समय तक स्थिर तारों के सापेक्ष आकाश में धीरे-धीरे अपनी स्थिति बदलता रहता है। यह किसी विशिष्ट तारकीय तारामंडल से स्थायी रूप से जुड़ा नहीं है। पश्चिमी ज्योतिष के छात्रों सहित कई लोगों को जब पहली बार इस तथ्य का सामना होता है तो उन्हें यह तथ्य काफी आश्चर्यजनक लगता है।`, ja: `その結果、西洋占星術では牡羊座と呼ばれる星座は、長い時間をかけて恒星に対する空の位置をゆっくりと変化させます。 It is not permanently connected to a specific stellar constellation.西洋占星術の学生を含む多くの人は、この事実に初めて遭遇すると、非常に驚​​くべきことに気づきます。`, ko: `결과적으로, 서양 점성술에서 양자리라고 불리는 별자리는 오랜 시간에 걸쳐 고정된 별을 기준으로 하늘에서 그 위치가 천천히 변합니다. 특정 별의 별자리와 영구적으로 연결되어 있지 않습니다. 서양 점성술 학생을 포함한 많은 사람들은 이 사실을 처음 접했을 때 매우 놀랍다고 생각합니다.`,} },
      { type: "paragraph", text: { en: `Astronomers frequently criticize Western Astrology because the Tropical Zodiac moves relative to the fixed stars. Since the position of Aries gradually shifts over time, they question the validity of associating it with a fixed area of the sky. However, this criticism does not apply to Jyotish because it uses a fixed Sidereal Zodiac rather than a movable one.`, hi: `खगोलशास्त्री अक्सर पश्चिमी ज्योतिष की आलोचना करते हैं क्योंकि उष्णकटिबंधीय राशि चक्र स्थिर तारों के सापेक्ष चलता है। चूंकि मेष राशि की स्थिति समय के साथ धीरे-धीरे बदलती है, वे इसे आकाश के एक निश्चित क्षेत्र के साथ जोड़ने की वैधता पर सवाल उठाते हैं। हालाँकि, यह आलोचना ज्योतिष पर लागू नहीं होती है क्योंकि यह चल राशि के बजाय एक निश्चित नक्षत्र राशि का उपयोग करता है।`, ja: `天文学者は、熱帯黄道帯が恒星に対して相対的に移動するため、西洋占星術を頻繁に批判します。牡羊座の位置は時間の経過とともに徐々に変化するため、牡羊座を空の固定領域と関連付けることの妥当性を疑問視しています。ただし、ジョーティッシュでは可動黄道帯ではなく固定恒星黄道帯が使用されているため、この批判は当てはまりません。`, ko: `천문학자들은 열대 황도대가 고정된 별을 기준으로 움직이기 때문에 서양 점성술을 자주 비판합니다. 양자리의 위치는 시간이 지남에 따라 점차 변하기 때문에 이를 하늘의 고정된 영역과 연관시키는 타당성에 의문을 제기합니다. 그러나 이러한 비판은 Jyotish에는 적용되지 않습니다. 왜냐하면 이동 가능한 항성 황도대 대신 고정된 항성 황도대를 사용하기 때문입니다.`,} },
      { type: "heading", level: 3, text: { en: `Ayanamsa – Angular Difference Between the Two Zodiacs`, hi: `अयनांश - दो राशियों के बीच कोणीय अंतर`, ja: `アヤナムサ – 2 つの黄道帯の角度の違い`, ko: `Ayanamsa – 두 황도대 사이의 각도 차이`,} },
      { type: "paragraph", text: { en: `The angular separation between the Sidereal and Tropical zodiacs is known as the ayanamsa (ayanāṃśa or ayanamsha), and this difference increases gradually over time [3]. Although both zodiacs were approximately aligned around 1,700 years ago, the Tropical Zodiac used by Western astrologers has since shifted away from that original position.`, hi: `नाक्षत्र और उष्णकटिबंधीय राशियों के बीच कोणीय अलगाव को अयनांश (अयनांश या अयनांश) के रूप में जाना जाता है, और यह अंतर समय के साथ धीरे-धीरे बढ़ता है [3]। हालाँकि लगभग 1,700 साल पहले दोनों राशियाँ लगभग एक सीध में थीं, पश्चिमी ज्योतिषियों द्वारा प्रयुक्त उष्णकटिबंधीय राशि चक्र तब से उस मूल स्थिति से दूर चला गया है।`, ja: `恒星黄道帯と熱帯黄道帯の間の角度の分離はアヤナムサ (ayanāṃśa または ayanamsha) として知られており、この差は時間の経過とともに徐々に増加します [3]。両方の黄道帯は約 1,700 年前にはほぼ一直線上にありましたが、西洋占星術師が使用した熱帯黄道帯はそれ以来、元の位置からずれています。`, ko: `항성 황도대와 열대 황도대 사이의 각도 분리는 아야남사(ayanāṃśa 또는 ayanamsha)로 알려져 있으며, 이 차이는 시간이 지남에 따라 점차 증가합니다[3]. 두 황도대 모두 대략 1,700년 전에 정렬되었지만, 서양 점성가들이 사용하는 열대 황도대는 그 이후로 원래 위치에서 멀어졌습니다.`,} },
      { type: "paragraph", text: { en: `As of 2021, the difference between the two zodiacs is approximately 24 degrees. Therefore, if the Sun is positioned at 29 degrees Virgo in the Tropical Zodiac, it will be located at approximately 29° – 24° = 5° Virgo in the Sidereal Zodiac. In this example, the Sun remains in Virgo in both systems.`, hi: `2021 तक, दोनों राशियों के बीच का अंतर लगभग 24 डिग्री है। इसलिए, यदि सूर्य उष्णकटिबंधीय राशि चक्र में 29 डिग्री कन्या राशि पर स्थित है, तो यह नक्षत्र राशि चक्र में लगभग 29° - 24° = 5° कन्या राशि पर स्थित होगा। इस उदाहरण में, सूर्य दोनों प्रणालियों में कन्या राशि में रहता है।`, ja: `2021 年の時点で、2 つの星座の差は約 24 度です。したがって、太陽が熱帯黄道帯の乙女座 29 度に位置する場合、恒星黄道帯では約 29 度 – 24 度 = 5 度の乙女座に位置することになります。この例では、太陽はどちらの星系でも乙女座に留まります。`, ko: `2021년 현재 두 황도대의 차이는 약 24도 정도이다. 따라서 태양이 열대 황도대에서 처녀자리 29도에 위치한다면 항성 황도대에서는 대략 처녀자리 29° – 24° = 5°에 위치하게 됩니다. 이 예에서 태양은 두 시스템 모두에서 처녀자리에 남아 있습니다.`,} },
      { type: "paragraph", text: { en: `However, if the Sun lies between 0° and 24° Virgo in the Tropical Zodiac, it will fall into Leo in the Sidereal Zodiac used by Vedic Astrology. In other words, it moves backwards (anti-clockwise) by the amount of the ayanamsa—around 24 degrees—and enters the previous sign [4].`, hi: `हालाँकि, यदि सूर्य उष्णकटिबंधीय राशि चक्र में 0° और 24° कन्या राशि के बीच स्थित है, तो यह वैदिक ज्योतिष द्वारा प्रयुक्त नाक्षत्र राशि चक्र में सिंह राशि में आ जाएगा। दूसरे शब्दों में, यह अयनांश की मात्रा से पीछे की ओर (वामावर्त) चलता है - लगभग 24 डिग्री - और पिछले चिह्न [4] में प्रवेश करता है।`, ja: `ただし、太陽が熱帯黄道帯の乙女座0°と24°の間にある場合、ヴェーダ占星術で使用される恒星黄道帯では太陽は獅子座に該当します。言い換えれば、アヤナムサの量だけ後方 (反時計回り) に移動し (約 24 度)、前のサインに入ります [4]。`, ko: `그러나 태양이 열대 황도대에서 처녀자리 0°에서 24° 사이에 있으면 베다 점성술에서 사용하는 항성 황도대에서는 사자자리에 해당합니다. 즉, 아야남사 양(약 24도)만큼 뒤로(시계 반대 방향) 이동하고 이전 기호[4]를 입력합니다.`,} },
      { type: "paragraph", text: { en: `This means that a person's Sun sign may differ between the two systems. Someone considered a Virgo in Western Astrology may actually be a Leo according to Jyotish. The same principle applies not only to the Sun but also to all planetary positions and the Ascendant. These sign differences can help explain many of the inconsistencies and anomalies encountered when charts are interpreted solely through modern Western Astrology.`, hi: `इसका मतलब यह है कि किसी व्यक्ति की सूर्य राशि दोनों प्रणालियों के बीच भिन्न हो सकती है। पश्चिमी ज्योतिष में कन्या राशि को माना जाने वाला कोई व्यक्ति वास्तव में ज्योतिष के अनुसार सिंह राशि हो सकता है। यही सिद्धांत न केवल सूर्य पर बल्कि सभी ग्रह स्थितियों और लग्न पर भी लागू होता है। ये संकेत अंतर उन कई विसंगतियों और विसंगतियों को समझाने में मदद कर सकते हैं जो तब सामने आती हैं जब चार्ट की व्याख्या केवल आधुनिक पश्चिमी ज्योतिष के माध्यम से की जाती है।`, ja: `これは、人の太陽星座が 2 つのシステム間で異なる可能性があることを意味します。西洋占星術で乙女座と考えられている人は、ジョーティッシュによれば、実際には獅子座である可能性があります。同じ原理が太陽だけでなく、すべての惑星の位置とアセンダントにも当てはまります。これらのサインの違いは、現代の西洋占星術だけでチャートを解釈したときに遭遇する矛盾や異常の多くを説明するのに役立ちます。`, ko: `이는 사람의 태양 별자리가 두 시스템 간에 다를 수 있음을 의미합니다. Jyotish에 따르면 서양 점성술에서 처녀자리로 간주되는 사람은 실제로 사자자리일 수도 있습니다. 동일한 원리가 태양뿐만 아니라 모든 행성 위치와 승천에도 적용됩니다. 이러한 부호 차이는 차트를 현대 서양 점성술을 통해서만 해석할 때 발생하는 많은 불일치와 이상 현상을 설명하는 데 도움이 될 수 있습니다.`,} },
    ],
  },
  {
    id: "nakshatras-stellar-1",
    section: "nakshatras",
    title: { en: `Nakshatras – Stellar Constellations`, hi: `नक्षत्र - तारकीय नक्षत्र`, ja: `ナクシャトラ – 恒星星座`, ko: `낙샤트라(Nakshatras) – 별의 별자리`,},
    related: ["nakshatras-human-physiology","sidereal-zodiac-p3","mahadashas"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Nakshatras – Stellar Constellations`, hi: `नक्षत्र - तारकीय नक्षत्र`, ja: `ナクシャトラ – 恒星星座`, ko: `낙샤트라(Nakshatras) – 별의 별자리`,} },
      { type: "paragraph", text: { en: `Jyotish places considerable importance on the stellar constellations known as Nakshatras. They play a vital role in chart interpretation, compatibility analysis, and determining favourable timings for important activities through Muhurtha.`, hi: `ज्योतिष तारकीय नक्षत्रों को काफी महत्व देता है जिन्हें नक्षत्र कहा जाता है। वे चार्ट व्याख्या, अनुकूलता विश्लेषण और मुहूर्त के माध्यम से महत्वपूर्ण गतिविधियों के लिए अनुकूल समय निर्धारित करने में महत्वपूर्ण भूमिका निभाते हैं।`, ja: `ジョーティッシュは、ナクシャトラとして知られる恒星の星座を非常に重視しています。彼らは、チャートの解釈、互換性分析、およびムハルタを通じて重要な活動に有利なタイミングを決定する上で重要な役割を果たします。`, ko: `Jyotish는 Nakshatras로 알려진 별의 별자리에 상당한 중요성을 둡니다. 이들은 차트 해석, 호환성 분석 및 Muhurtha를 통한 중요한 활동에 대한 유리한 타이밍을 결정하는 데 중요한 역할을 합니다.`,} },
      { type: "paragraph", text: { en: `There are 27 Nakshatras, often referred to as Lunar Mansions, distributed evenly throughout the sky. Technically speaking, they are arranged as equal sectors along the ecliptic.`, hi: `27 नक्षत्र हैं, जिन्हें अक्सर चंद्र भवन कहा जाता है, जो पूरे आकाश में समान रूप से वितरित हैं। तकनीकी रूप से कहें तो, उन्हें क्रांतिवृत्त के साथ समान क्षेत्रों के रूप में व्यवस्थित किया गया है।`, ja: `しばしば月の邸宅と呼ばれる 27 のナクシャトラが空全体に均等に分布しています。技術的に言えば、それらは黄道に沿って等しいセクターとして配置されます。`, ko: `종종 달의 저택(Lunar Mansions)이라고 불리는 27개의 나크샤트라(Nakshatra)가 하늘 전체에 고르게 분포되어 있습니다. 기술적으로 말하자면, 그들은 황도를 따라 동일한 섹터로 배열됩니다.`,} },
      { type: "paragraph", text: { en: `Given the significance of the Nakshatras within Vedic Astrology, it is hardly surprising that Jyotish employs a zodiac system that remains permanently anchored to the fixed stars and therefore remains aligned with the Nakshatras themselves.`, hi: `वैदिक ज्योतिष में नक्षत्रों के महत्व को देखते हुए, यह कोई आश्चर्य की बात नहीं है कि ज्योतिष एक राशि चक्र प्रणाली को नियोजित करता है जो स्थायी रूप से निश्चित सितारों से जुड़ी रहती है और इसलिए स्वयं नक्षत्रों के साथ संरेखित रहती है।`, ja: `ヴェーダ占星術におけるナクシャトラの重要性を考えると、ジョーティッシュが永久に恒星に固定されたままであり、したがってナクシャトラ自体と一致し続ける黄道十二宮システムを採用していることは驚くべきことではありません。`, ko: `베다 점성술에서 나크샤트라의 중요성을 고려할 때, 조티쉬가 고정된 별에 영구적으로 고정되어 있어 나크샤트라 자체와 정렬된 상태를 유지하는 황도대 시스템을 사용하는 것은 놀라운 일이 아닙니다.`,} },
      eduImage(educationImages.nakshatrasStellar, {
        en: "Nakshatras — stellar constellations", hi: "नक्षत्र - तारकीय नक्षत्र", ja: "ナクシャトラ — 恒星星座", ko: "낙샤트라(Nakshatras) — 별의 별자리",
      }),
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "heading", level: 3, text: { en: `[1]`, hi: `[1]`, ja: `[1]`, ko: `[1]`,} },
      { type: "paragraph", text: { en: `The "fixed stars" are located so far from Earth that their angular movement relative to our Sun is extremely small, even across many thousands of years. For practical purposes, it is therefore reasonable to describe them as fixed or immovable.`, hi: `"स्थिर तारे" पृथ्वी से इतनी दूर स्थित हैं कि हमारे सूर्य के सापेक्ष उनकी कोणीय गति कई हजारों वर्षों में भी बेहद छोटी है। व्यावहारिक उद्देश्यों के लिए, उन्हें स्थिर या अचल के रूप में वर्णित करना उचित है।`, ja: `「恒星」は地球から非常に遠くに位置しているため、太陽に対するそれらの角の動きは、何千年にわたっても非常に小さいです。したがって、実際的な目的では、それらを固定または不動として説明するのが合理的です。`, ko: `"고정 별"은 지구에서 너무 멀리 떨어져 있기 때문에 수천 년에 걸쳐 태양에 대한 각운동이 극히 작습니다. 따라서 실용적인 목적을 위해 고정 또는 부동으로 설명하는 것이 합리적입니다.`,} },
      { type: "heading", level: 3, text: { en: `[2]`, hi: `[2]`, ja: `[2]`, ko: `[2]`,} },
      { type: "paragraph", text: { en: `The equinox point on Earth's orbit around the Sun gradually shifts relative to the background of the fixed stars due to a phenomenon known as the precession of the equinoxes. This well-established astronomical effect results from a slight wobble in Earth's rotational axis, similar to the motion of a spinning top whose axis slowly traces out a cone-shaped path. Earth takes approximately 26,000 years to complete one full precessional cycle.`, hi: `सूर्य के चारों ओर पृथ्वी की कक्षा पर विषुव बिंदु धीरे-धीरे विषुव की पूर्वता के रूप में जानी जाने वाली घटना के कारण स्थिर तारों की पृष्ठभूमि के सापेक्ष बदलता रहता है। यह अच्छी तरह से स्थापित खगोलीय प्रभाव पृथ्वी की घूर्णन धुरी में एक मामूली डगमगाहट के परिणामस्वरूप होता है, जो एक घूमते हुए शीर्ष की गति के समान है जिसकी धुरी धीरे-धीरे एक शंकु के आकार का पथ बनाती है। पृथ्वी को एक पूर्ण पूर्ववर्ती चक्र पूरा करने में लगभग 26,000 वर्ष लगते हैं।`, ja: `太陽の周りの地球の軌道上の春分点は、春分点の歳差運動として知られる現象により、恒星の背景に対して徐々に移動します。この確立された天文効果は、地球の回転軸のわずかなぐらつきによって生じます。これは、軸がゆっくりと円錐形の軌道を描くコマの動きに似ています。地球が完全な歳差運動サイクルを完了するには約 26,000 年かかります。`, ko: `태양 주위를 도는 지구 궤도의 분점은 분점 세차라고 알려진 현상으로 인해 고정된 별의 배경에 대해 점차적으로 이동합니다. 이 잘 확립된 천문학적 효과는 지구 회전축의 약간의 흔들림으로 인해 발생합니다. 이는 축이 원뿔 모양의 경로를 천천히 따라가는 회전하는 팽이의 움직임과 유사합니다. 지구는 하나의 완전한 세차주기를 완료하는 데 약 26,000년이 걸립니다.`,} },
      { type: "heading", level: 3, text: { en: `[3]`, hi: `[3]`, ja: `[3]`, ko: `[3]`,} },
      { type: "paragraph", text: { en: `As of 2021, the angular difference between the Tropical and Sidereal zodiacs is approximately 24 degrees. This value, or one very close to it, was derived by Lahiri and is widely accepted among Jyotish astrologers. Most modern astrological tables therefore use Lahiri's ayanamsa.`, hi: `2021 तक, उष्णकटिबंधीय और नाक्षत्र राशियों के बीच कोणीय अंतर लगभग 24 डिग्री है। यह मान, या इसके बहुत करीब, लाहिड़ी द्वारा निकाला गया था और ज्योतिषियों के बीच व्यापक रूप से स्वीकार किया जाता है। इसलिए अधिकांश आधुनिक ज्योतिषीय तालिकाएँ लाहिड़ी के अयनांश का उपयोग करती हैं।`, ja: `2021 年の時点で、熱帯黄道帯と恒星黄道帯の角度の差は約 24 度です。この値、またはそれに非常に近い値はラヒリによって導出され、ジョーティッシュ家の間で広く受け入れられています。したがって、現代の占星術表のほとんどはラヒリのアヤナムサを使用しています。`, ko: `2021년 현재 열대 황도대와 항성 황도대의 각도 차이는 약 24도입니다. 이 값 또는 그에 매우 가까운 값은 라히리(Lahiri)에 의해 파생되었으며 Jyotish 점성가들 사이에서 널리 받아들여지고 있습니다. 따라서 대부분의 현대 점성술 표는 라히리의 아야남사를 사용합니다.`,} },
      { type: "paragraph", text: { en: `The Tropical Zodiac moves relative to the Sidereal (fixed) Zodiac at a rate of approximately one degree every 71 years. Although this shift may appear small, it was observed by ancient Egyptian astronomers thousands of years ago. Over long periods, the accumulated effect becomes highly significant.`, hi: `उष्णकटिबंधीय राशि चक्र हर 71 वर्ष में लगभग एक डिग्री की दर से नाक्षत्र (स्थिर) राशि चक्र के सापेक्ष चलता है। हालाँकि यह बदलाव छोटा लग सकता है, इसे हजारों साल पहले प्राचीन मिस्र के खगोलविदों ने देखा था। लंबी अवधि में, संचित प्रभाव अत्यधिक महत्वपूर्ण हो जाता है।`, ja: `熱帯黄道帯は、恒星（固定）黄道帯に対して 71 年ごとに約 1 度の割合で移動します。この変化は小さいように見えるかもしれませんが、数千年前に古代エジプトの天文学者によって観察されました。長期間にわたって蓄積された効果は非常に重要になります。`, ko: `열대 황도대는 항성(고정) 황도대를 기준으로 71년마다 약 1도씩 이동합니다. 이러한 변화는 작은 것처럼 보일 수 있지만 수천 년 전에 고대 이집트 천문학자들에 의해 관찰되었습니다. 장기간에 걸쳐 축적된 효과는 매우 중요해집니다.`,} },
      { type: "heading", level: 3, text: { en: `[4]`, hi: `[4]`, ja: `[4]`, ko: `[4]`,} },
      { type: "paragraph", text: { en: `The difference in planetary positions between the two zodiac systems is currently about 24 degrees. For example, if the Sun is positioned at 14 degrees Virgo in Western Astrology, its Sidereal position would be calculated as:`, hi: `दोनों राशि प्रणालियों के बीच ग्रहों की स्थिति में अंतर वर्तमान में लगभग 24 डिग्री है। उदाहरण के लिए, यदि पश्चिमी ज्योतिष में सूर्य 14 डिग्री कन्या राशि पर स्थित है, तो इसकी नाक्षत्र स्थिति की गणना इस प्रकार की जाएगी:`, ja: `2 つの黄道帯システム間の惑星の位置の差は現在約 24 度です。たとえば、西洋占星術で太陽が乙女座 14 度に位置する場合、その恒星位置は次のように計算されます。`, ko: `두 황도대 시스템 사이의 행성 위치 차이는 현재 약 24도입니다. 예를 들어, 서양 점성술에서 태양이 처녀자리 14도에 위치하는 경우 항성체 위치는 다음과 같이 계산됩니다.`,} },
      { type: "paragraph", text: { en: `14° – 24° = –10° Virgo`, hi: `14° – 24° = -10° कन्या`, ja: `14° – 24° = –10° 乙女座`, ko: `14° – 24° = –10° 처녀자리`,} },
      { type: "paragraph", text: { en: `This indicates that the Sun is actually 10 degrees before the start of Virgo. In practical terms, it has moved backwards (anti-clockwise) into the previous sign, Leo, where its position becomes 20 degrees Leo (since –10 + 30 = 20).`, hi: `यह इंगित करता है कि सूर्य वास्तव में कन्या राशि की शुरुआत से 10 डिग्री पहले है। व्यावहारिक रूप से, यह पिछली राशि सिंह में पीछे की ओर (वामावर्त) चला गया है, जहां इसकी स्थिति 20 डिग्री सिंह हो जाती है (चूंकि -10 + 30 = 20)।`, ja: `これは、太陽が実際には乙女座の開始の10度前にあることを示しています。実際には、前の星座である獅子座まで後方 (反時計回り) に移動し、その位置は獅子座 20 度になります (-10 + 30 = 20 であるため)。`, ko: `이는 태양이 실제로 처녀자리가 시작되기 10도 전이라는 것을 나타냅니다. 실제적인 측면에서는 이전 기호인 사자자리로 뒤로(시계 반대 방향) 이동하여 위치가 사자자리 20도가 됩니다(–10 + 30 = 20이므로).`,} },
      { type: "paragraph", text: { en: `By contrast, if the Sun is located at 28 degrees Virgo in the Tropical Zodiac, the calculation becomes:`, hi: `इसके विपरीत, यदि सूर्य उष्णकटिबंधीय राशि चक्र में 28 डिग्री कन्या राशि पर स्थित है, तो गणना इस प्रकार है:`, ja: `対照的に、太陽が熱帯黄道帯の乙女座 28 度に位置する場合、計算は次のようになります。`, ko: `대조적으로, 태양이 열대 황도대에서 처녀자리 28도에 위치한다면 계산은 다음과 같습니다:`,} },
      { type: "paragraph", text: { en: `28° – 24° = 4° Virgo`, hi: `28° – 24° = 4° कन्या`, ja: `28° – 24° = 4° 乙女座`, ko: `28° – 24° = 4° 처녀자리`,} },
      { type: "paragraph", text: { en: `Although the Sun has still shifted backwards by the ayanamsa amount, it remains within Virgo and therefore does not change signs.`, hi: `हालाँकि सूर्य अभी भी अयनांश राशि से पीछे की ओर खिसका हुआ है, यह कन्या राशि में ही रहता है और इसलिए राशि परिवर्तन नहीं करता है।`, ja: `太陽は依然としてアヤナムサ量だけ後方に移動していますが、乙女座内に留まっているため、星座は変わりません。`, ko: `태양은 여전히 ​​아야남사 양만큼 뒤로 이동했지만 처녀자리 안에 남아 있으므로 별자리는 변하지 않습니다.`,} },
    ],
  },
  {
    id: "nakshatras-human-physiology",
    section: "nakshatras",
    title: { en: `The 27 Nakshatras in Human Physiology`, hi: `मानव शरीर विज्ञान में 27 नक्षत्र`, ja: `人体における27ナクシャトラ`, ko: `인간 생리학의 27가지 나크샤트라`,},
    related: ["nakshatras-stellar-1","sidereal-zodiac-p3","twelve-houses"],
    blocks: [
      { type: "heading", level: 2, text: { en: `The 27 Nakshatras in Human Physiology`, hi: `मानव शरीर विज्ञान में 27 नक्षत्र`, ja: `人体における27ナクシャトラ`, ko: `인간 생리학의 27가지 나크샤트라`,} },
      { type: "heading", level: 3, text: { en: `Understanding the 27 Nakshatras and Their Correspondence in the Human Body`, hi: `मानव शरीर में 27 नक्षत्रों और उनके पत्राचार को समझना`, ja: `27ナクシャトラと人体の対応を理解する`, ko: `27나크샤트라와 인체의 대응 이해`,} },
      { type: "paragraph", text: { en: `Think of the 27 Nakshatras (lunar constellations in Vedic astrology) as a network of specialized control centers in the brain — almost like a set of switches that manage how we stay alert, fall asleep, and dream. Each of these 27 groups helps regulate our body's automatic responses, like reflexes, breathing, heartbeat, and even how we experience and process pain. Interestingly, modern science shows there are also 27 corresponding groups of brain cells (neurons) that closely match the Nakshatras — not just in number, but also in their basic structure and the roles they play. This suggests a fascinating overlap between ancient astrological wisdom and modern neuroscience.`, hi: `27 नक्षत्रों (वैदिक ज्योतिष में चंद्र नक्षत्र) को मस्तिष्क में विशेष नियंत्रण केंद्रों के एक नेटवर्क के रूप में सोचें - लगभग स्विचों के एक सेट की तरह जो यह नियंत्रित करते हैं कि हम कैसे सतर्क रहते हैं, सोते हैं और सपने देखते हैं। इन 27 समूहों में से प्रत्येक हमारे शरीर की स्वचालित प्रतिक्रियाओं को विनियमित करने में मदद करता है, जैसे कि सजगता, श्वास, दिल की धड़कन, और यहां तक ​​कि हम दर्द का अनुभव और प्रक्रिया कैसे करते हैं। दिलचस्प बात यह है कि आधुनिक विज्ञान से पता चलता है कि मस्तिष्क कोशिकाओं (न्यूरॉन्स) के 27 संबंधित समूह भी हैं जो नक्षत्रों से निकटता से मेल खाते हैं - न केवल संख्या में, बल्कि उनकी मूल संरचना और उनके द्वारा निभाई जाने वाली भूमिकाओं में भी। यह प्राचीन ज्योतिषीय ज्ञान और आधुनिक तंत्रिका विज्ञान के बीच एक आकर्षक ओवरलैप का सुझाव देता है।`, ja: `27のナクシャトラ（ヴェーダ占星術における月の星座）を、脳内の専門的な制御中枢のネットワーク — 覚醒、睡眠、夢を司るスイッチの集合体のようなもの — と考えてみてください。これら27のグループはそれぞれ、反射、呼吸、心拍、さらには痛みの感じ方や処理の仕方など、身体の自動反応を調節する役割を担います。興味深いことに、現代科学でもナクシャトラと密接に対応する27の脳細胞（ニューロン）群が存在することが示されており、数だけでなく基本的な構造と機能の面でも一致しています。これは、古代の占星術的知恵と現代の神経科学との間に、魅力的な重なりがあることを示唆しています。`, ko: `27개의 나크샤트라(베다 점성술의 달 별자리)를 뇌의 전문 제어 센터 네트워크로 생각해 보세요. 이는 우리가 깨어 있고, 잠들고, 꿈을 꾸는 방법을 관리하는 스위치 세트와 거의 같습니다. 이 27개 그룹은 각각 반사 신경, 호흡, 심장 박동은 물론 통증을 경험하고 처리하는 방식과 같은 신체의 자동 반응을 조절하는 데 도움이 됩니다. 흥미롭게도 현대 과학에 따르면 나크샤트라와 밀접하게 일치하는 27개의 뇌 세포(뉴런) 그룹이 숫자뿐만 아니라 기본 구조와 수행 역할에서도 나타납니다. 이는 고대 점성술의 지혜와 현대 신경과학 사이의 매혹적인 중첩을 암시합니다.`,} },
      eduImage(educationImages.nakshatraWheel, {
        en: "The 27 nakshatras and zodiac signs in Jyotish", hi: "ज्योतिष में 27 नक्षत्र और राशियाँ", ja: "ジョーティッシュにおける27ナクシャトラと黄道十二宮", ko: "Jyotish의 27개 낙샤트라와 황도대 별자리",
      }),
      { type: "paragraph", text: { en: `When a baby is born, everything changes instantly. Inside the womb, the baby didn't need to worry about breathing on its own, eating, or keeping its body warm — the mother's body took care of all of that. But the moment of birth flips a switch: suddenly, the newborn has to independently manage all these basic survival functions. This massive shift is guided largely by a part of the brain called the hypothalamus, which in Vedic astrology is symbolically linked to the Moon. The hypothalamus works together with brainstem centers (linked to the Nakshatras) to help the baby adapt to this brand-new environment outside the womb.`, hi: `जब एक बच्चा पैदा होता है तो सब कुछ तुरंत बदल जाता है। गर्भ के अंदर, बच्चे को खुद सांस लेने, खाने या अपने शरीर को गर्म रखने के बारे में चिंता करने की ज़रूरत नहीं थी - माँ का शरीर इन सभी का ख्याल रखता था। लेकिन जन्म के क्षण में एक बदलाव आ जाता है: अचानक, नवजात शिशु को इन सभी बुनियादी अस्तित्व कार्यों को स्वतंत्र रूप से प्रबंधित करना पड़ता है। यह व्यापक बदलाव मुख्य रूप से मस्तिष्क के हाइपोथैलेमस नामक हिस्से द्वारा निर्देशित होता है, जो वैदिक ज्योतिष में प्रतीकात्मक रूप से चंद्रमा से जुड़ा हुआ है। हाइपोथैलेमस मस्तिष्क तंत्र केंद्रों (नक्षत्रों से जुड़ा हुआ) के साथ मिलकर काम करता है ताकि बच्चे को गर्भ के बाहर इस बिल्कुल नए वातावरण में अनुकूलित करने में मदद मिल सके।`, ja: `赤ちゃんが生まれると、すべてが一瞬にして変わります。子宮の中では、自分で呼吸したり、食べたり、体温を保ったりする必要はありませんでした — すべて母親の身体が担っていたからです。しかし誕生の瞬間にスイッチが切り替わり、新生児はこれらの基本的な生存機能を自ら管理しなければなりません。この大きな転換は、主に視床下部と呼ばれる脳の部位によって導かれます。ヴェーダ占星術では、視床下部は象徴的に月と結びつけられています。視床下部は、脳幹の中枢（ナクシャトラと結びつく）と協働し、赤ちゃんが子宮外という全く新しい環境に適応するのを助けます。`, ko: `아기가 태어나면 모든 것이 즉시 변합니다. 자궁 안에서 아기는 스스로 호흡하고, 먹고, 몸을 따뜻하게 유지하는 것에 대해 걱정할 필요가 없었습니다. 모든 것을 어머니의 몸이 처리했습니다. 그러나 태어나는 순간 스위치가 바뀌게 됩니다. 갑자기 신생아는 이 모든 기본적인 생존 기능을 독립적으로 관리해야 합니다. 이 엄청난 변화는 주로 베다 점성술에서 달과 상징적으로 연결되어 있는 시상하부라고 불리는 뇌의 일부에 의해 유도됩니다. 시상하부는 뇌간 센터(낙샤트라와 연결됨)와 함께 작동하여 아기가 자궁 밖의 새로운 환경에 적응하도록 돕습니다.`,} },
      { type: "paragraph", text: { en: `Before birth, though, the baby isn't operating on its own internal clock. Instead, its bodily rhythms — such as sleep patterns or internal cycles — are borrowed from the mother. The baby's nervous system develops in sync with her rhythms, almost like following her lead, while also slowly building its own independent rhythm in the background.`, hi: `हालाँकि, जन्म से पहले, बच्चा अपनी आंतरिक घड़ी पर काम नहीं कर रहा होता है। इसके बजाय, इसकी शारीरिक लय - जैसे नींद के पैटर्न या आंतरिक चक्र - माँ से उधार ली गई हैं। शिशु का तंत्रिका तंत्र उसकी लय के साथ तालमेल बिठाकर विकसित होता है, लगभग उसके नेतृत्व का अनुसरण करने जैसा, साथ ही पृष्ठभूमि में धीरे-धीरे अपनी स्वतंत्र लय का निर्माण भी करता है।`, ja: `しかし出生前、赤ちゃんは自分自身の体内時計で動いているわけではありません。むしろ、睡眠パターンや体内サイクルなどの身体リズムは、母親から借りている状態です。赤ちゃんの神経系は母親のリズムと同期しながら発達し、まるで彼女の導きに従うかのようでありながら、背景ではゆっくりと独自の独立したリズムを築いていきます。`, ko: `하지만 태어나기 전에 아기는 자체 내부 시계로 작동하지 않습니다. 대신, 수면 패턴이나 내부 주기와 같은 신체 리듬은 어미에게서 빌려옵니다. 아기의 신경계는 거의 아기의 인도를 따르는 것처럼 아기의 리듬에 맞춰 발달하는 동시에 배경에서 천천히 독립적인 리듬을 형성합니다.`,} },
      { type: "paragraph", text: { en: `The exact moment a baby takes its first breath is significant. According to Jyotish (Vedic astrology), that specific moment captures a unique snapshot: a particular state of the Moon (representing hypothalamic activity) combined with a particular alignment of the Nakshatras (representing brainstem activity). This precise combination is believed to set the tone for the person's entire life journey — marking the beginning of their individual biological and astrological rhythm. From that point forward, life continues in structured cycles: the daily rhythm of day turning into night, the monthly rhythm of lunar phases, and many other natural patterns that shape our existence over time.`, hi: `जिस क्षण शिशु पहली सांस लेता है वह महत्वपूर्ण होता है। ज्योतिष (वैदिक ज्योतिष) के अनुसार, वह विशिष्ट क्षण एक अद्वितीय स्नैपशॉट कैप्चर करता है: चंद्रमा की एक विशेष स्थिति (हाइपोथैलेमिक गतिविधि का प्रतिनिधित्व करती है) जो नक्षत्रों के एक विशेष संरेखण (ब्रेनस्टेम गतिविधि का प्रतिनिधित्व करती है) के साथ संयुक्त होती है। ऐसा माना जाता है कि यह सटीक संयोजन व्यक्ति की संपूर्ण जीवन यात्रा के लिए स्वर निर्धारित करता है - जो उनकी व्यक्तिगत जैविक और ज्योतिषीय लय की शुरुआत का प्रतीक है। उस बिंदु से आगे, जीवन संरचित चक्रों में जारी रहता है: दिन की दैनिक लय रात में बदल जाती है, चंद्र चरणों की मासिक लय, और कई अन्य प्राकृतिक पैटर्न जो समय के साथ हमारे अस्तित्व को आकार देते हैं।`, ja: `赤ちゃんが最初の息を吸う正確な瞬間は、非常に重要です。ジョーティッシュ（ヴェーダ占星術）によれば、その特定の瞬間は唯一のスナップショットを捉えます — 月の特定の状態（視床下部の活動を表す）と、ナクシャトラの特定の配置（脳幹の活動を表す）の組み合わせです。この精密な組み合わせが、その人の生涯全体の基調を定めると信じられています — 個人の生物学的・占星術的リズムの始まりを刻むのです。その瞬間以降、人生は構造化されたサイクルの中で続きます — 昼が夜に変わる日々のリズム、月相の月次リズム、そして時間をかけて私たちの存在を形作るその他多くの自然のパターンです。`, ko: `아기가 첫 숨을 쉬는 정확한 순간은 중요합니다. Jyotish(베다 점성술)에 따르면, 그 특정 순간은 독특한 스냅샷을 포착합니다. 즉, 달의 특정 상태(시상하부 활동을 나타냄)와 Nakshatras(뇌간 활동을 나타냄)의 특정 정렬이 결합된 것입니다. 이 정확한 조합은 개인의 전체 인생 여정의 분위기를 설정하고 개인의 생물학적 및 점성술 리듬의 시작을 표시하는 것으로 믿어집니다. 그 시점부터 삶은 구조화된 주기로 계속됩니다. 낮이 밤으로 바뀌는 일일 리듬, 달의 위상이 바뀌는 월별 리듬, 그리고 시간이 지남에 따라 우리의 존재를 형성하는 기타 많은 자연 패턴이 그것입니다.`,} },
    ],
  },
  {
    id: "planetary-forces",
    section: "introduction",
    title: { en: `Jyotish – Planetary Forces`, hi: `ज्योतिष - ग्रह बल`, ja: `ジョーティッシュ – 惑星軍`, ko: `Jyotish – 행성군`,},
    related: ["natural-benefics-malefics","planetary-strengths","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Planetary Forces`, hi: `ज्योतिष - ग्रह बल`, ja: `ジョーティッシュ – 惑星軍`, ko: `Jyotish – 행성군`,} },
      { type: "paragraph", text: { en: `Summary: This article addresses a common criticism made by some Western Astrologers regarding traditional Vedic Astrology—that it is limited or outdated because it uses only nine "planets." Jyotish maintains that there is no need to incorporate planets beyond Saturn, as it works directly with a field of perfectly codified information rather than with physical or subtle forces supposedly emitted by planets, asteroids, or other celestial bodies.`, hi: `सारांश: यह लेख पारंपरिक वैदिक ज्योतिष के संबंध में कुछ पश्चिमी ज्योतिषियों द्वारा की गई एक आम आलोचना को संबोधित करता है - कि यह सीमित या पुराना है क्योंकि यह केवल नौ "ग्रहों" का उपयोग करता है। ज्योतिष का मानना ​​है कि शनि से परे ग्रहों को शामिल करने की कोई आवश्यकता नहीं है, क्योंकि यह ग्रहों, क्षुद्रग्रहों या अन्य खगोलीय पिंडों द्वारा उत्सर्जित भौतिक या सूक्ष्म शक्तियों के बजाय सीधे पूरी तरह से संहिताबद्ध जानकारी के क्षेत्र के साथ काम करता है।`, ja: `概要: この記事は、伝統的なヴェーダ占星術に関して一部の西洋占星術師がよく行う批判、つまり、9 つの「惑星」しか使用していないため限界がある、または時代遅れであるという批判に対処します。ジョーティッシュは、惑星、小惑星、その他の天体から発せられるとされる物理的または微妙な力ではなく、完全に体系化された情報の分野と直接連携するため、土星以外の惑星を組み込む必要はないと主張している。`, ko: `요약: 이 기사는 전통적인 베다 점성술에 대해 일부 서양 점성가들이 제기한 일반적인 비판, 즉 9개의 "행성"만 사용하기 때문에 제한적이거나 시대에 뒤떨어진다는 비판을 다루고 있습니다. Jyotish는 행성, 소행성 또는 기타 천체에서 방출되는 것으로 추정되는 물리적 또는 미묘한 힘이 아닌 완벽하게 코드화된 정보 분야와 직접적으로 작동하기 때문에 토성 너머의 행성을 통합할 필요가 없다고 주장합니다.`,} },
      { type: "paragraph", text: { en: `Planetary ‘Forces’ Don’t Exist in Vedic Astrology`, hi: `वैदिक ज्योतिष में ग्रहीय 'बलों' का अस्तित्व नहीं है`, ja: `惑星の「力」はヴェーダ占星術には存在しない`, ko: `베다 점성술에는 행성의 '힘'이 존재하지 않습니다`,} },
      { type: "paragraph", text: { en: `Many Western Astrologers hold the view that planets—and even asteroids—emit some form of subtle influence or force, which has not yet been identified by modern science, and that these forces affect human life. Based on this assumption, they often argue that Jyotish Astrology is incomplete because it does not include the outer planets Uranus, Neptune, and Pluto, nor more recently recognized celestial objects such as Chiron.`, hi: `कई पश्चिमी ज्योतिषियों का मानना ​​है कि ग्रह-और यहां तक ​​कि क्षुद्रग्रह-किसी प्रकार का सूक्ष्म प्रभाव या बल उत्सर्जित करते हैं, जिसे अभी तक आधुनिक विज्ञान द्वारा पहचाना नहीं जा सका है, और ये बल मानव जीवन को प्रभावित करते हैं। इस धारणा के आधार पर, वे अक्सर तर्क देते हैं कि ज्योतिष अधूरा है क्योंकि इसमें बाहरी ग्रह यूरेनस, नेपच्यून और प्लूटो शामिल नहीं हैं, न ही हाल ही में मान्यता प्राप्त खगोलीय वस्तुएं जैसे कि चिरोन।`, ja: `多くの西洋占星術師は、惑星、さらには小惑星が、現代科学ではまだ特定されていない何らかの形の微妙な影響や力を発しており、それらの力が人間の生活に影響を与えるという見解を持っています。この仮定に基づいて、ジョーティッシュには外惑星の天王星、海王星、冥王星や、最近になって認識されたキロンなどの天体が含まれていないため、彼らは不完全であると主張することがよくあります。`, ko: `많은 서양 점성가들은 행성, 심지어 소행성조차 현대 과학에 의해 아직 확인되지 않은 어떤 형태의 미묘한 영향이나 힘을 방출하며 이러한 힘이 인간의 삶에 영향을 미친다는 견해를 가지고 있습니다. 이러한 가정에 기초하여, 그들은 조티쉬 점성술이 외행성인 천왕성, 해왕성, 명왕성이나 최근에 인식된 키론과 같은 천체를 포함하지 않기 때문에 불완전하다고 종종 주장합니다.`,} },
      { type: "paragraph", text: { en: `However, as discussed below, Vedic Astrology approaches the subject from an entirely different perspective. Jyotish works directly with a field of structured and codified information that is complete in itself, rather than with any form of planetary force.`, hi: `हालाँकि, जैसा कि नीचे चर्चा की गई है, वैदिक ज्योतिष इस विषय को पूरी तरह से अलग दृष्टिकोण से देखता है। ज्योतिष किसी भी प्रकार के ग्रहीय बल के बजाय सीधे संरचित और संहिताबद्ध जानकारी के क्षेत्र के साथ काम करता है जो अपने आप में पूर्ण है।`, ja: `ただし、以下で説明するように、ヴェーダ占星術はまったく異なる観点からこの主題にアプローチします。ジョーティッシュは、惑星の力ではなく、それ自体で完全な、構造化され体系化された情報のフィールドを直接操作します。`, ko: `그러나 아래에서 논의되는 것처럼 베다 점성술은 완전히 다른 관점에서 주제에 접근합니다. Jyotish는 어떤 형태의 행성 힘이 아니라 그 자체로 완전한 구조화되고 코드화된 정보 분야를 직접 사용하여 작업합니다.`,} },
      { type: "paragraph", text: { en: `Although Vedic Astrologers may occasionally use the phrase "planetary force" when communicating with clients, this should not be interpreted as referring to an actual physical force. Instead, it simply describes the influence or effect that a planet signifies within an individual's life.`, hi: `यद्यपि वैदिक ज्योतिषी कभी-कभी ग्राहकों के साथ संवाद करते समय "ग्रह बल" वाक्यांश का उपयोग कर सकते हैं, लेकिन इसकी व्याख्या वास्तविक भौतिक बल के संदर्भ में नहीं की जानी चाहिए। इसके बजाय, यह केवल उस प्रभाव या प्रभाव का वर्णन करता है जो एक ग्रह किसी व्यक्ति के जीवन में दर्शाता है।`, ja: `ヴェーダ占星術師はクライアントとコミュニケーションをとる際に「惑星の力」というフレーズを使用することがありますが、これを実際の物理的な力を指すものとして解釈すべきではありません。代わりに、個人の生活の中で惑星が意味する影響や効果を単に説明します。`, ko: `베다 점성가들이 고객과 의사소통할 때 때때로 "행성력"이라는 문구를 사용할 수 있지만, 이를 실제 물리적 힘을 지칭하는 것으로 해석해서는 안 됩니다. 대신, 이는 단순히 행성이 개인의 삶에 미치는 영향이나 효과를 설명합니다.`,} },
      { type: "heading", level: 3, text: { en: `Key Points in Support of the ‘Codified Information’ Viewpoint`, hi: `'संहिताबद्ध सूचना' दृष्टिकोण के समर्थन में मुख्य बिंदु`, ja: `「コード化された情報」の観点をサポートする重要なポイント`, ko: `'코드화된 정보' 관점을 뒷받침하는 핵심 사항`,} },
      { type: "paragraph", text: { en: `• Jyotish regards the planetary arrangements present at the moment of birth as a form of cosmic code. Skilled Vedic Astrologers interpret this code and translate it into predictions concerning returning karma carried over from previous incarnations.`, hi: `• ज्योतिष जन्म के समय मौजूद ग्रह व्यवस्था को ब्रह्मांडीय संहिता का एक रूप मानता है। कुशल वैदिक ज्योतिषी इस कोड की व्याख्या करते हैं और इसे पिछले अवतारों से प्राप्त कर्मों की वापसी से संबंधित भविष्यवाणियों में अनुवाद करते हैं।`, ja: `• ジョーティッシュは、誕生の瞬間に存在する惑星の配置を宇宙のコードの一種とみなします。熟練したヴェーダ占星術師はこのコードを解釈し、前世から引き継がれたカルマの帰還に関する予測に変換します。`, ko: `• Jyotish는 출생 순간에 존재하는 행성 배열을 우주 코드의 한 형태로 간주합니다. 숙련된 베다 점성가들은 이 암호를 해석하고 이를 이전 화신에서 이어진 카르마의 복귀에 관한 예측으로 해석합니다.`,} },
      { type: "paragraph", text: { en: `• The placement of the seven visible planets (up to and including Saturn), together with the two lunar nodes [1], within the twelve signs, twelve houses, and twenty-seven Nakshatras, represents a highly sophisticated system of encoded information. This information provides everything required for understanding the major areas of life—Dharma, Artha, Kama, and Moksha.`, hi: `• बारह राशियों, बारह घरों और सत्ताईस नक्षत्रों के भीतर दो चंद्र नोड्स [1] के साथ सात दृश्यमान ग्रहों (शनि तक और सहित) की स्थिति, एन्कोडेड जानकारी की एक अत्यधिक परिष्कृत प्रणाली का प्रतिनिधित्व करती है। यह जानकारी जीवन के प्रमुख क्षेत्रों- धर्म, अर्थ, काम और मोक्ष को समझने के लिए आवश्यक सभी चीजें प्रदान करती है।`, ja: `• 目に見える 7 つの惑星 (土星まで) と 2 つの月のノード [1] の、12 のサイン、12 ハウス、27 のナクシャトラ内への配置は、コード化された情報の高度に洗練されたシステムを表しています。この情報は、人生の主要な領域であるダルマ、アルタ、カーマ、モクシャを理解するために必要なすべてを提供します。`, ko: `• 12개의 별자리, 12개의 집, 27개의 나크샤트라 내에서 2개의 달 노드[1]와 함께 7개의 눈에 보이는 행성(토성까지 포함)의 배치는 매우 정교한 암호화된 정보 시스템을 나타냅니다. 이 정보는 다르마(Dharma), 아르타(Artha), 카마(Kama), 목샤(Moksha) 등 삶의 주요 영역을 이해하는 데 필요한 모든 것을 제공합니다.`,} },
      { type: "paragraph", text: { en: `• Planetary transits, as planets appear to move through the sidereal zodiac signs and houses, are likewise viewed as expressions of codified information rather than manifestations of physical forces.`, hi: `• ग्रहों का गोचर, जैसे ग्रह नक्षत्रीय राशियों और घरों से गुजरते हुए दिखाई देते हैं, वैसे ही उन्हें भौतिक शक्तियों की अभिव्यक्ति के बजाय संहिताबद्ध जानकारी की अभिव्यक्ति के रूप में देखा जाता है।`, ja: `• 惑星が恒星星座やハウスの中を移動しているように見える惑星の通過も、同様に、物理的な力の発現ではなく、体系化された情報の表現として見なされます。`, ko: `• 행성이 항성 황도대 별자리와 하우스를 통해 이동하는 것처럼 보이는 행성 통과는 마찬가지로 물리적 힘의 표현이라기보다는 코드화된 정보의 표현으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `• The absence of any physical force is further supported by a fundamental Jyotish principle: the effects of planets vary significantly according to an individual's Ascendant or rising sign [2]. No comparable concept exists within traditional Western Astrology. The same planet can produce very different outcomes depending upon the Ascendant. If a genuine physical force were involved, such variations would be difficult to explain.`, hi: `• किसी भी भौतिक बल की अनुपस्थिति को एक मौलिक ज्योतिष सिद्धांत द्वारा समर्थित किया गया है: किसी व्यक्ति के लग्न या उदीयमान राशि के अनुसार ग्रहों का प्रभाव काफी भिन्न होता है [2]। पारंपरिक पश्चिमी ज्योतिष में कोई तुलनीय अवधारणा मौजूद नहीं है। एक ही ग्रह लग्न के आधार पर बहुत भिन्न परिणाम दे सकता है। यदि वास्तविक भौतिक बल शामिल होता, तो ऐसी विविधताओं को समझाना मुश्किल होता।`, ja: `• 物理的な力が存在しないことは、基本的なジョーティッシュの原則によってさらに裏付けられています。つまり、惑星の影響は個人のアセンダントまたはライジング サインに応じて大きく異なります [2]。伝統的な西洋占星術にはこれに匹敵する概念は存在しません。同じ惑星でもアセンダントに応じて非常に異なる結果が生じる可能性があります。本物の物理的な力が関与している場合、そのような変動を説明するのは困難でしょう。`, ko: `• 물리적 힘이 없다는 점은 기본적인 Jyotish 원리에 의해 더욱 뒷받침됩니다. 즉, 행성의 효과는 개인의 어센던트 또는 상승 별자리에 따라 크게 달라집니다[2]. 전통적인 서양 점성술에는 비슷한 개념이 존재하지 않습니다. 같은 행성이라도 승천자에 따라 매우 다른 결과를 낳을 수 있습니다. 만약 진정한 물리적 힘이 관련되어 있다면 그러한 변화는 설명하기 어려울 것입니다.`,} },
      { type: "paragraph", text: { en: `• Jyotish also places great importance on Rahu and Ketu, the Moon's nodes. These have no physical substance whatsoever. They are simply mathematically calculated points where the Moon's orbit intersects the ecliptic [3]. Yet they indicate major karmic influences and tangible life experiences. If these points possess no material existence, it becomes difficult to argue that their effects result from any physical force.`, hi: `• ज्योतिष भी चंद्रमा के नोड्स राहु और केतु को बहुत महत्व देता है। इनमें कोई भी भौतिक पदार्थ नहीं है। वे बस गणितीय रूप से गणना किए गए बिंदु हैं जहां चंद्रमा की कक्षा क्रांतिवृत्त को काटती है [3]। फिर भी वे प्रमुख कार्मिक प्रभावों और वास्तविक जीवन अनुभवों का संकेत देते हैं। यदि इन बिंदुओं का कोई भौतिक अस्तित्व नहीं है, तो यह तर्क देना कठिन हो जाता है कि उनका प्रभाव किसी भौतिक बल से उत्पन्न होता है।`, ja: `• ジョーティッシュはまた、月のノードであるラーフとケートゥを非常に重要視します。これらには物理的な実体はまったくありません。それらは、月の軌道が黄道と交差する単純に数学的に計算された点です [3]。しかし、それらは大きなカルマ的影響と具体的な人生経験を示しています。これらの点が物質的な存在を持たない場合、その影響が物理的な力によるものであると主張するのは困難になります。`, ko: `• Jyotish는 또한 달의 노드인 Rahu와 Ketu를 매우 중요하게 생각합니다. 이것들은 물리적인 실체가 전혀 없습니다. 이는 단순히 달의 궤도가 황도와 교차하는 수학적으로 계산된 지점입니다[3]. 그러나 그것들은 주요 카르마적 영향과 실질적인 삶의 경험을 나타냅니다. 이러한 점이 물질적으로 존재하지 않는다면 그 효과가 물리적인 힘에 의한 것이라고 주장하기가 어려워집니다.`,} },
      { type: "paragraph", text: { en: `• Vedic Astrologers traditionally believe that Jyotish was "revealed" or "cognized." It was neither invented by humanity nor developed gradually through experimentation. Rather, it is regarded as Divine Knowledge that is complete in itself. Within this divine system there is no requirement to incorporate information from the outer planets or recently discovered asteroids. To do so would be viewed as a departure from the original teachings of the great sage Maharishi Parashara.`, hi: `• वैदिक ज्योतिषी परंपरागत रूप से मानते हैं कि ज्योतिष "प्रकट" या "पहचान" था। इसका आविष्कार न तो मानवता द्वारा किया गया था और न ही प्रयोग के माध्यम से धीरे-धीरे विकसित किया गया था। बल्कि इसे ईश्वरीय ज्ञान माना जाता है जो अपने आप में पूर्ण है। इस दिव्य प्रणाली के भीतर बाहरी ग्रहों या हाल ही में खोजे गए क्षुद्रग्रहों से जानकारी शामिल करने की कोई आवश्यकता नहीं है। ऐसा करना महान ऋषि महर्षि पराशर की मूल शिक्षाओं से विचलन के रूप में देखा जाएगा।`, ja: `• ヴェーダ占星術師は伝統的に、ジョーティッシュは「啓示」または「認識」されたと信じています。それは人類によって発明されたものでも、実験によって徐々に開発されたものでもありません。むしろ、それ自体で完全な神聖な知識とみなされます。この神聖なシステム内では、外惑星や最近発見された小惑星からの情報を組み込む必要はありません。そうすることは、偉大な聖者マハリシ・パラシャラの本来の教えから逸脱するとみなされるでしょう。`, ko: `• 베다 점성가들은 전통적으로 Jyotish가 "계시"되었거나 "인식"되었다고 믿습니다. 그것은 인류가 발명한 것도 아니고 실험을 통해 점진적으로 발전한 것도 아닙니다. 오히려 그것은 그 자체로 완전한 신성한 지식으로 간주됩니다. 이 신성한 시스템 내에는 외부 행성이나 최근 발견된 소행성의 정보를 통합할 필요가 없습니다. 그렇게 하는 것은 위대한 현자 마하리시 파라샤라(Maharishi Parashara)의 원래 가르침에서 벗어나는 것으로 간주될 것입니다.`,} },
      { type: "paragraph", text: { en: `• The idea of complete and perfect knowledge being provided by the Divine for the benefit of humanity is not unique to Jyotish. Similar principles are found in other Vedic sciences such as Ayurveda, the Vedic system of natural healthcare, and Vastu, the science of designing harmonious living environments.`, hi: `• मानवता के लाभ के लिए ईश्वर द्वारा प्रदान किए जाने वाले पूर्ण और परिपूर्ण ज्ञान का विचार ज्योतिष के लिए अद्वितीय नहीं है। इसी तरह के सिद्धांत अन्य वैदिक विज्ञानों जैसे आयुर्वेद, प्राकृतिक स्वास्थ्य देखभाल की वैदिक प्रणाली और वास्तु, सामंजस्यपूर्ण रहने वाले वातावरण को डिजाइन करने के विज्ञान में पाए जाते हैं।`, ja: `・完全かつ完全な知識が人類の利益のために神によって提供されるという考えは、ジョーティッシュに特有のものではありません。同様の原理は、自然医療のヴェーダ システムであるアーユルヴェーダや、調和のとれた生活環境を設計する科学であるヴァストゥなど、他のヴェーダ科学にも見られます。`, ko: `• 인류의 이익을 위해 신성이 제공하는 완전하고 완벽한 지식에 대한 아이디어는 Jyotish에만 국한된 것이 아닙니다. 유사한 원리는 자연 건강 관리의 베다 시스템인 Ayurveda와 조화로운 생활 환경을 설계하는 과학인 Vastu와 같은 다른 베다 과학에서도 발견됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Jyotish Astrologers Interpret the ‘Cosmic Codes’`, hi: `ज्योतिषी 'ब्रह्मांडीय कोड' की व्याख्या करते हैं`, ja: `ジョーティッシュ師が「宇宙の暗号」を解釈する`, ko: `Jyotish 점성가들은 '우주 코드'를 해석합니다.`,} },
      { type: "paragraph", text: { en: `To fully appreciate the foundations of Jyotish, we must move beyond purely mechanistic models of reality. The traditional Newtonian view, based on objects and forces, gives way to a deeper understanding in which consciousness is regarded as the fundamental basis of existence. At its core, the functioning of Vedic Astrology rests upon the Vedic model of reality.`, hi: `ज्योतिष की नींव की पूरी तरह से सराहना करने के लिए, हमें वास्तविकता के विशुद्ध रूप से यंत्रवत मॉडल से आगे बढ़ना चाहिए। वस्तुओं और शक्तियों पर आधारित पारंपरिक न्यूटोनियन दृष्टिकोण एक गहरी समझ का मार्ग प्रशस्त करता है जिसमें चेतना को अस्तित्व का मूल आधार माना जाता है। इसके मूल में, वैदिक ज्योतिष की कार्यप्रणाली वास्तविकता के वैदिक मॉडल पर आधारित है।`, ja: `ジョーティッシュの基礎を十分に理解するには、純粋に機械的な現実モデルを超えなければなりません。物体と力に基づく伝統的なニュートンの見方は、意識が存在の基本的な基盤であるとみなされる、より深い理解に取って代わられます。ヴェーダ占星術の機能の核心は、ヴェーダの現実モデルに基づいています。`, ko: `Jyotish의 기초를 충분히 이해하려면 순전히 기계적인 현실 모델을 넘어서야 합니다. 물체와 힘에 기초한 전통적인 뉴턴의 견해는 의식이 존재의 근본적인 기초로 간주되는 더 깊은 이해로 이어졌습니다. 근본적으로 베다 점성술의 기능은 베다 현실 모델에 기초합니다.`,} },
      { type: "paragraph", text: { en: `Jyotish emerges from a tradition that views the universe as one perfectly integrated whole. Underlying this totality is an all-pervading field of Cosmic Intelligence. In our essential nature, we are part of that Cosmic Intelligence. It is therefore not surprising that the intelligence responsible for creating the universe should also provide insights into our past, present, and potential future.`, hi: `ज्योतिष एक ऐसी परंपरा से उभरा है जो ब्रह्मांड को एक पूर्णतः एकीकृत संपूर्ण के रूप में देखती है। इस समग्रता के पीछे ब्रह्मांडीय बुद्धिमत्ता का एक सर्वव्यापी क्षेत्र है। अपनी मूल प्रकृति में, हम उस ब्रह्मांडीय बुद्धिमत्ता का हिस्सा हैं। इसलिए यह आश्चर्य की बात नहीं है कि ब्रह्मांड के निर्माण के लिए जिम्मेदार बुद्धिमत्ता को हमारे अतीत, वर्तमान और संभावित भविष्य के बारे में भी अंतर्दृष्टि प्रदान करनी चाहिए।`, ja: `ジョーティッシュは、宇宙を完全に統合された 1 つの全体として見る伝統から生まれました。この全体性の根底にあるのは、宇宙知性のあらゆる領域に浸透していることです。私たちの本質的な性質において、私たちは宇宙の知性の一部です。したがって、宇宙の創造に関与した知性が、私たちの過去、現在、そして潜在的な未来についての洞察も提供することは驚くべきことではありません。`, ko: `Jyotish는 우주를 하나의 완벽하게 통합된 전체로 보는 전통에서 탄생했습니다. 이 총체성의 기저에는 우주 지능(Cosmic Intelligence)이라는 모든 곳에 퍼져 있는 분야가 있습니다. 본질적인 특성상 우리는 우주 지능의 일부입니다. 그러므로 우주 창조를 담당하는 지능이 우리의 과거, 현재, 잠재적인 미래에 대한 통찰력도 제공해야 한다는 것은 놀라운 일이 아닙니다.`,} },
      { type: "paragraph", text: { en: `As the enlightened Vedic Master Sri Sri Ravi Shankar stated:`, hi: `जैसा कि प्रबुद्ध वैदिक गुरु श्री श्री रविशंकर ने कहा:`, ja: `啓発されたヴェーダのマスター、シュリ シュリ ラヴィ シャンカールは次のように述べています。`, ko: `깨달은 베다 스승인 스리 스리 라비 샹카르(Sri Sri Ravi Shankar)는 다음과 같이 말했습니다.`,} },
      { type: "paragraph", text: { en: `"The purpose of astrology is to take you to the ultimate truth that the entire universe is one organism. It's one Being, one consciousness, one Self, that manifests itself into this varied universe."`, hi: `"ज्योतिष का उद्देश्य आपको उस अंतिम सत्य तक ले जाना है कि संपूर्ण ब्रह्मांड एक जीव है। यह एक अस्तित्व, एक चेतना, एक स्व है, जो इस विविध ब्रह्मांड में प्रकट होता है।"`, ja: `「占星術の目的は、宇宙全体が一つの有機体であるという究極の真実にあなたを導くことです。この多様な宇宙に現れるのは、一つの存在、一つの意識、一つの自己です。」`, ko: `"점성술의 목적은 우주 전체가 하나의 유기체라는 궁극적인 진실을 알려주는 것입니다. 이 다양한 우주에 나타나는 것은 하나의 존재, 하나의 의식, 하나의 자아입니다."`,} },
      { type: "paragraph", text: { en: `(Published in the Art of Living's Daily Sutra, May 2003.)`, hi: `(आर्ट ऑफ लिविंग के दैनिक सूत्र, मई 2003 में प्रकाशित।)`, ja: `(2003 年 5 月、『暮らしの日々の経典』に掲載。)`, ko: `(2003년 5월, 생활예술일일경에 게재.)`,} },
      { type: "paragraph", text: { en: `In many respects, a birth chart can be compared to a strand of DNA within a sperm or egg cell. DNA stores vast amounts of information in an extremely condensed form. As time unfolds, that information is progressively expressed as tissues, organs, physical structures, and eventually a complete living being.`, hi: `कई मायनों में, जन्म कुंडली की तुलना शुक्राणु या अंडाणु कोशिका के भीतर डीएनए के एक स्ट्रैंड से की जा सकती है। डीएनए बड़ी मात्रा में जानकारी को अत्यंत संक्षिप्त रूप में संग्रहीत करता है। जैसे-जैसे समय बीतता है, वह जानकारी उत्तरोत्तर ऊतकों, अंगों, शारीरिक संरचनाओं और अंततः एक पूर्ण जीवित प्राणी के रूप में व्यक्त होती है।`, ja: `多くの点で、出生図は精子または卵細胞内の DNA 鎖にたとえることができます。 DNA は、膨大な量の情報を非常に凝縮された形で保存します。時間が経つにつれて、その情報は組織、器官、物理的構造として徐々に表現され、最終的には完全な生命体として表現されます。`, ko: `여러 측면에서 출생 차트는 정자나 난자 세포 내의 DNA 가닥에 비유될 수 있습니다. DNA는 엄청난 양의 정보를 극도로 압축된 형태로 저장합니다. 시간이 지남에 따라 그 정보는 점진적으로 조직, 기관, 물리적 구조로 표현되고 결국에는 완전한 생명체로 표현됩니다.`,} },
      { type: "paragraph", text: { en: `A similar process occurs in Jyotish. The information encoded within a birth chart gradually unfolds through time, manifesting as significant life events and karmic experiences—whether beneficial or challenging.`, hi: `ज्योतिष शास्त्र में भी ऐसी ही प्रक्रिया होती है। जन्म कुंडली के भीतर एन्कोड की गई जानकारी धीरे-धीरे समय के साथ सामने आती है, महत्वपूर्ण जीवन की घटनाओं और कर्म अनुभवों के रूप में प्रकट होती है - चाहे वह फायदेमंद हो या चुनौतीपूर्ण।`, ja: `同様のプロセスがジョーティッシュでも発生します。出生図内にエンコードされた情報は、時間の経過とともに徐々に明らかになり、有益な場合でも困難な場合でも、重要な人生の出来事やカルマ的経験として現れます。`, ko: `Jyotish에서도 비슷한 과정이 발생합니다. 출생 차트에 인코딩된 정보는 시간이 지남에 따라 점진적으로 전개되어 유익하든 도전적이든 중요한 인생 사건과 카르마 경험으로 나타납니다.`,} },
      { type: "paragraph", text: { en: `Jyotish Astrology consists of numerous axioms and mathematical rules that enable the astrologer to interpret how the highly encoded information within a birth chart may unfold into physical circumstances and karmic outcomes. This process is somewhat analogous to modern biochemistry, which can decode sections of DNA and relate them to recognizable physical characteristics.`, hi: `ज्योतिष में कई सिद्धांत और गणितीय नियम शामिल हैं जो ज्योतिषी को यह व्याख्या करने में सक्षम बनाते हैं कि जन्म कुंडली के भीतर अत्यधिक एन्कोडेड जानकारी भौतिक परिस्थितियों और कर्म परिणामों में कैसे प्रकट हो सकती है। यह प्रक्रिया कुछ हद तक आधुनिक जैव रसायन के समान है, जो डीएनए के अनुभागों को डिकोड कर सकती है और उन्हें पहचानने योग्य भौतिक विशेषताओं से जोड़ सकती है।`, ja: `ジョーティッシュは、占星術師が出生図内の高度に暗号化された情報が物理的状況やカルマ的結果にどのように展開するかを解釈できるようにする多数の公理と数学的規則で構成されています。このプロセスは、DNA のセクションを解読し、それらを認識可能な物理的特徴に関連付けることができる現代の生化学にある程度似ています。`, ko: `Jyotish 점성술은 점성가가 출생 차트 내의 고도로 암호화된 정보가 어떻게 물리적 상황과 카르마적 결과로 전개될 수 있는지 해석할 수 있도록 하는 수많은 공리와 수학적 규칙으로 구성됩니다. 이 과정은 DNA 부분을 해독하고 이를 인식 가능한 물리적 특성과 연관시킬 수 있는 현대 생화학과 다소 유사합니다.`,} },
      { type: "paragraph", text: { en: `For this reason, Jyotish does not require the concept of forces being emitted by planets or celestial bodies. It works directly with a field of information and intelligence that is already complete and self-contained.`, hi: `इस कारण से, ज्योतिष को ग्रहों या आकाशीय पिंडों द्वारा उत्सर्जित बलों की अवधारणा की आवश्यकता नहीं है। यह सीधे सूचना और खुफिया क्षेत्र के साथ काम करता है जो पहले से ही पूर्ण और आत्मनिर्भर है।`, ja: `このため、ジョーティッシュでは、惑星や天体から発せられる力の概念は必要ありません。それは、すでに完全で自己完結型の情報およびインテリジェンスの分野と直接連携します。`, ko: `이러한 이유로 Jyotish는 행성이나 천체에서 방출되는 힘의 개념을 요구하지 않습니다. 이는 이미 완전하고 독립적인 정보 및 지능 분야와 직접적으로 작동합니다.`,} },
      { type: "heading", level: 3, text: { en: `Footnotes`, hi: `फुटनोट`, ja: `脚注`, ko: `각주`,} },
      { type: "heading", level: 3, text: { en: `[1]`, hi: `[1]`, ja: `[1]`, ko: `[1]`,} },
      { type: "paragraph", text: { en: `Jyotish utilizes nine Grahas, or celestial influences, often translated as "planets." These include the Sun and Moon (which are not classified as planets from an astronomical perspective), Mercury, Venus, Mars, Jupiter, and Saturn. It also includes two calculated points known as Rahu and Ketu, the Moon's nodes, which are closely associated with eclipses.`, hi: `ज्योतिष नौ ग्रहों या आकाशीय प्रभावों का उपयोग करता है, जिन्हें अक्सर "ग्रह" के रूप में अनुवादित किया जाता है। इनमें सूर्य और चंद्रमा (जिन्हें खगोलीय दृष्टिकोण से ग्रहों के रूप में वर्गीकृत नहीं किया गया है), बुध, शुक्र, मंगल, बृहस्पति और शनि शामिल हैं। इसमें दो गणना बिंदु भी शामिल हैं जिन्हें राहु और केतु, चंद्रमा के नोड्स के रूप में जाना जाता है, जो ग्रहण से निकटता से जुड़े हुए हैं।`, ja: `ジョーティッシュは 9 つのグラハ、つまり「惑星」と訳されることもある天体の影響を利用します。これらには、太陽と月 (天文学的な観点からは惑星として分類されません)、水星、金星、火星、木星、土星が含まれます。また、月食と密接に関連するラーフとケトゥとして知られる 2 つの計算された点 (月のノード) も含まれています。`, ko: `Jyotish는 종종 "행성"으로 번역되는 9개의 Grahas, 즉 천상의 영향을 활용합니다. 여기에는 태양과 달(천문학적 관점에서 행성으로 분류되지 않음), 수성, 금성, 화성, 목성, 토성이 포함됩니다. 또한 일식과 밀접하게 연관되어 있는 달의 노드인 Rahu 및 Ketu로 알려진 두 개의 계산된 지점도 포함되어 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `[2]`, hi: `[2]`, ja: `[2]`, ko: `[2]`,} },
      { type: "paragraph", text: { en: `For example, in Jyotish the planet Mars is generally considered highly beneficial in the birth chart of an individual with a Leo Ascendant because it rules both the 4th house and the auspicious 9th house, thereby functioning as a functional benefic.`, hi: `उदाहरण के लिए, ज्योतिष में मंगल ग्रह को आमतौर पर सिंह लग्न वाले व्यक्ति की जन्म कुंडली में अत्यधिक लाभकारी माना जाता है क्योंकि यह चौथे घर और शुभ नौवें घर दोनों पर शासन करता है, जिससे एक कार्यात्मक लाभकारी के रूप में कार्य होता है।`, ja: `たとえば、ジョーティッシュでは、火星は一般に、獅子座アセンダントを持つ個人の出生図において非常に有益であると考えられています。これは、火星が4室と縁起の良い9室の両方を支配しており、それによって機能的な恩恵として機能しているためです。`, ko: `예를 들어, Jyotish에서 화성은 일반적으로 4하우스와 상서로운 9하우스를 모두 다스리고 기능적 혜택으로 기능하기 때문에 사자자리 어센던트를 가진 개인의 출생 차트에서 매우 유익한 것으로 간주됩니다.`,} },
      { type: "paragraph", text: { en: `By contrast, Mars is generally regarded as strongly unfavourable for someone with a Virgo Ascendant because it rules the 6th and 11th houses, making it both a functional and natural malefic.`, hi: `इसके विपरीत, मंगल को आम तौर पर कन्या लग्न वाले किसी व्यक्ति के लिए अत्यधिक प्रतिकूल माना जाता है क्योंकि यह 6ठे और 11वें घरों पर शासन करता है, जो इसे कार्यात्मक और प्राकृतिक दोनों तरह से हानिकारक बनाता है।`, ja: `対照的に、火星は一般に、乙女座アセンダントを持つ人にとって非常に不利であると考えられています。これは、火星が6室と11室を支配しており、機能的かつ自然な凶星であるためです。`, ko: `대조적으로, 화성은 일반적으로 처녀자리 어센던트를 가진 사람에게 매우 불리한 것으로 간주됩니다. 왜냐하면 화성은 6하우스와 11하우스를 지배하여 기능적이고 자연적인 흉성을 만들기 때문입니다.`,} },
      { type: "paragraph", text: { en: `Thus, the same planet can indicate positive outcomes for one individual and negative outcomes for another. Clearly, this cannot be explained by a physical force emanating from Mars itself. Rather, it supports the view that Jyotish operates through an integrated field of information or intelligence linking the individual to the Cosmic Totality.`, hi: `इस प्रकार, एक ही ग्रह एक व्यक्ति के लिए सकारात्मक परिणाम और दूसरे के लिए नकारात्मक परिणाम का संकेत दे सकता है। स्पष्ट रूप से, इसे मंगल से निकलने वाली किसी भौतिक शक्ति द्वारा नहीं समझाया जा सकता है। बल्कि, यह इस दृष्टिकोण का समर्थन करता है कि ज्योतिष व्यक्ति को ब्रह्मांडीय समग्रता से जोड़ने वाली सूचना या बुद्धिमत्ता के एक एकीकृत क्षेत्र के माध्यम से संचालित होता है।`, ja: `したがって、同じ惑星は、ある人にとってはポジティブな結果を示し、別の人にとってはネガティブな結果を示す可能性があります。明らかに、これは火星自体から発せられる物理的な力では説明できません。むしろ、ジョーティッシュは個人を宇宙の全体性に結び付ける統合された情報または知性の分野を通じて活動しているという見解を支持しています。`, ko: `따라서 동일한 행성은 한 개인에게는 긍정적인 결과를 나타낼 수 있고 다른 개인에게는 부정적인 결과를 나타낼 수 있습니다. 분명히 이것은 화성 자체에서 나오는 물리적 힘으로는 설명할 수 없습니다. 오히려 그것은 Jyotish가 개인을 우주 전체에 연결하는 통합된 정보 또는 지능 분야를 통해 작동한다는 견해를 뒷받침합니다.`,} },
      { type: "heading", level: 3, text: { en: `[3]`, hi: `[3]`, ja: `[3]`, ko: `[3]`,} },
      { type: "paragraph", text: { en: `"The lunar nodes are the orbital nodes of the Moon, that is, the two points at which the orbit of the Moon crosses the ecliptic. The ascending (or north) node is where the Moon moves into the northern ecliptic hemisphere, while the descending (or south) node is where the Moon enters the southern ecliptic hemisphere. Eclipses involving the Moon occur only near the lunar nodes. A solar eclipse occurs when the passage of the Moon through a node coincides with the new moon, while a lunar eclipse occurs when the passage coincides with the full moon."`, hi: `"चंद्र नोड्स चंद्रमा के कक्षीय नोड्स हैं, यानी, दो बिंदु जहां चंद्रमा की कक्षा क्रांतिवृत्त को पार करती है। आरोही (या उत्तर) नोड वह है जहां चंद्रमा उत्तरी क्रांतिवृत्त गोलार्ध में जाता है, जबकि अवरोही (या दक्षिण) नोड वह है जहां चंद्रमा दक्षिणी क्रांतिवृत्त गोलार्ध में प्रवेश करता है। चंद्रमा से जुड़े ग्रहण केवल चंद्र नोड्स के पास होते हैं। सूर्य ग्रहण तब होता है जब चंद्रमा एक नोड के माध्यम से गुजरता है अमावस्या के साथ मेल खाता है, जबकि चंद्र ग्रहण तब होता है जब मार्ग पूर्णिमा के साथ मेल खाता है।"`, ja: `「月の交点は、月の軌道の交点、つまり、月の軌道が黄道を横切る2つの点です。上昇（または北）交点は、月が黄道北半球に入る場所であり、下降（または南）交点は、月が黄道南半球に入る場所です。月が関係する日食は、月の交点の近くでのみ発生します。日食は、月の交点の近くでのみ発生します。月のノードを通過する部分が新月と一致し、月食はノードを通過する部分が満月と一致すると発生します。」`, ko: `"달 노드는 달의 궤도 노드, 즉 달의 궤도가 황도를 가로지르는 두 지점입니다. 상승(또는 북쪽) 노드는 달이 북 황도 반구로 이동하는 곳이고, 하강(또는 남쪽) 노드는 달이 남 황도 반구로 들어가는 곳입니다. 달과 관련된 일식은 달 노드 근처에서만 발생합니다. 일식은 달이 노드를 통과하는 것이 초승달과 일치할 때 발생합니다. 월식은 그 통로가 보름달과 일치할 때 발생합니다."`,} },
    ],
  },
  {
    id: "forecasting-analogies-1",
    section: "introduction",
    title: { en: `Jyotish – Forecasting Analogies`, hi: `ज्योतिष - पूर्वानुमान सादृश्य`, ja: `ジョーティッシュ – 予測のアナロジー`, ko: `Jyotish – 예측 유추`,},
    related: ["predictive-capabilities","cosmos-individual-1","jyotish-and-karma"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Jyotish – Forecasting Analogies`, hi: `ज्योतिष - पूर्वानुमान सादृश्य`, ja: `ジョーティッシュ – 予測のアナロジー`, ko: `Jyotish – 예측 유추`,} },
      { type: "paragraph", text: { en: `Summary: This article explores several analogies commonly used to explain the probabilistic nature of prediction in Vedic Astrology. These comparisons help illustrate how planetary arrangements can be used to assess the likelihood of future events and influences unfolding in an individual's life.`, hi: `सारांश: यह लेख वैदिक ज्योतिष में भविष्यवाणी की संभाव्य प्रकृति को समझाने के लिए आमतौर पर उपयोग की जाने वाली कई उपमाओं की पड़ताल करता है। ये तुलनाएँ यह समझाने में मदद करती हैं कि किसी व्यक्ति के जीवन में भविष्य की घटनाओं और प्रभावों की संभावना का आकलन करने के लिए ग्रहों की व्यवस्था का उपयोग कैसे किया जा सकता है।`, ja: `概要: この記事では、ヴェーダ占星術における予測の確率的性質を説明するために一般的に使用されるいくつかのアナロジーを検討します。これらの比較は、個人の人生に展開する将来の出来事や影響の可能性を評価するために惑星の配置がどのように使用できるかを説明するのに役立ちます。`, ko: `요약: 이 기사에서는 베다 점성술에서 예측의 확률적 특성을 설명하는 데 일반적으로 사용되는 몇 가지 비유를 탐구합니다. 이러한 비교는 행성 배열을 사용하여 미래 사건의 가능성과 개인의 삶에 미치는 영향을 평가하는 방법을 설명하는 데 도움이 됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Forecasting Analogies in Vedic Astrology`, hi: `वैदिक ज्योतिष में सादृश्यों का पूर्वानुमान लगाना`, ja: `ヴェーダ占星術における予測の類似点`, ko: `베다 점성술의 유추 예측`,} },
      { type: "heading", level: 3, text: { en: `Weather Forecasting Analogy`, hi: `मौसम पूर्वानुमान सादृश्य`, ja: `天気予報のたとえ`, ko: `일기예보 비유`,} },
      { type: "paragraph", text: { en: `Vedic Astrology is fundamentally probabilistic in nature. In this respect, it can be compared to a long-range weather forecasting system. Jyotish seeks to predict when and how the actions we have performed in the past—our accumulated karmas—are likely to return as present and future influences in our lives.`, hi: `वैदिक ज्योतिष मूलतः संभाव्य प्रकृति का है। इस संबंध में, इसकी तुलना लंबी दूरी की मौसम पूर्वानुमान प्रणाली से की जा सकती है। ज्योतिष यह भविष्यवाणी करना चाहता है कि अतीत में हमने जो कार्य किए हैं - हमारे संचित कर्म - वे कब और कैसे हमारे जीवन में वर्तमान और भविष्य के प्रभावों के रूप में वापस आने की संभावना है।`, ja: `ヴェーダ占星術は基本的に確率的な性質を持っています。この点で、これは長期天気予報システムと比較できます。ジョーティッシュは、私たちが過去に行った行動、つまり蓄積されたカルマが、私たちの生活に現在および将来の影響としていつどのように戻ってくるかを予測しようとしています。`, ko: `베다 점성술은 근본적으로 확률론적입니다. 이런 점에서 이는 장기 일기예보 시스템과 비교할 수 있습니다. Jyotish는 우리가 과거에 수행한 행동, 즉 축적된 카르마가 언제, 어떻게 우리 삶에 현재와 미래의 영향으로 돌아올 가능성이 있는지 예측하려고 합니다.`,} },
      { type: "paragraph", text: { en: `If potential "storms" can be seen approaching on the horizon, we have the opportunity to take appropriate action and reduce difficulties before they fully manifest. Likewise, when "fine weather" is indicated, we can move forward more easily, make progress, and fulfil our desires with less resistance.`, hi: `यदि संभावित "तूफानों" को क्षितिज पर आते देखा जा सकता है, तो हमारे पास उचित कार्रवाई करने और कठिनाइयों को पूरी तरह से प्रकट होने से पहले कम करने का अवसर है। इसी तरह, जब "अच्छे मौसम" का संकेत दिया जाता है, तो हम अधिक आसानी से आगे बढ़ सकते हैं, प्रगति कर सकते हैं, और कम प्रतिरोध के साथ अपनी इच्छाओं को पूरा कर सकते हैं।`, ja: `潜在的な「嵐」が地平線に近づいているのが見える場合、私たちはそれが完全に現れる前に適切な行動をとり、困難を軽減する機会があります。同様に、「晴天」が示されると、より抵抗が少なくなり、より簡単に前進し、進歩し、欲望を達成することができます。`, ko: `잠재적인 "폭풍"이 곧 다가오고 있는 것이 보이면, 우리는 그것이 완전히 나타나기 전에 적절한 조치를 취하고 어려움을 줄일 수 있는 기회를 갖게 됩니다. 마찬가지로, "날씨가 좋다"는 신호가 오면 우리는 더 쉽게 앞으로 나아갈 수 있고, 발전할 수 있으며, 더 적은 저항으로 우리의 욕구를 충족시킬 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Just as meteorologists cannot guarantee 100% accuracy in every forecast, Jyotish is not an exact science. Experienced and skilled Vedic Astrologers are generally considered capable of achieving prediction accuracies in the region of 70%. However, when numerous factors within a birth chart consistently point toward benefits or challenges in a particular area of life, the astrologer can make predictions with a much greater degree of confidence.`, hi: `जिस तरह मौसम विज्ञानी हर पूर्वानुमान में 100% सटीकता की गारंटी नहीं दे सकते, ज्योतिष कोई सटीक विज्ञान नहीं है। अनुभवी और कुशल वैदिक ज्योतिषियों को आम तौर पर 70% के क्षेत्र में भविष्यवाणी सटीकता प्राप्त करने में सक्षम माना जाता है। हालाँकि, जब जन्म कुंडली के कई कारक लगातार जीवन के किसी विशेष क्षेत्र में लाभ या चुनौतियों की ओर इशारा करते हैं, तो ज्योतिषी बहुत अधिक आत्मविश्वास के साथ भविष्यवाणियाँ कर सकता है।`, ja: `気象学者がすべての予報で 100% の正確性を保証できないのと同じように、ジョーティッシュは正確な科学ではありません。経験豊富で熟練したヴェーダ占星術師は、一般的に 70% 程度の予測精度を達成できると考えられています。ただし、出生図内の数多くの要素が人生の特定の分野における利点や課題を一貫して示している場合、占星術師はより高い自信を持って予測を行うことができます。`, ko: `기상학자가 모든 예측에서 100% 정확성을 보장할 수 없는 것처럼 Jyotish도 정확한 과학은 아닙니다. 경험이 많고 숙련된 베다 점성가는 일반적으로 70% 정도의 예측 정확도를 달성할 수 있는 것으로 간주됩니다. 그러나 출생 차트 내의 수많은 요소가 삶의 특정 영역에서 일관되게 이점이나 어려움을 지적할 때 점성가는 훨씬 더 큰 확신을 가지고 예측을 할 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Seed Development Analogy`, hi: `बीज विकास सादृश्य`, ja: `シード開発のアナロジー`, ko: `종자 발달 비유`,} },
      { type: "paragraph", text: { en: `Different seeds produce different types of trees. A botanist can examine two seeds and confidently predict that one will develop into a silver birch and the other into a redwood. Most people find nothing unusual about such a prediction.`, hi: `अलग-अलग बीज अलग-अलग प्रकार के पेड़ पैदा करते हैं। एक वनस्पतिशास्त्री दो बीजों की जांच कर सकता है और आत्मविश्वास से भविष्यवाणी कर सकता है कि एक सिल्वर बर्च और दूसरा रेडवुड में विकसित होगा। अधिकांश लोगों को ऐसी भविष्यवाणी में कुछ भी असामान्य नहीं लगता।`, ja: `種が異なれば、異なる種類の木が生まれます。植物学者は 2 つの種子を調べて、1 つはシラカバに、もう 1 つはセコイアに成長すると確信を持って予測できます。ほとんどの人は、そのような予測に何の異常も感じません。`, ko: `씨앗에 따라 다른 종류의 나무가 나옵니다. 식물학자는 두 개의 씨앗을 조사한 후 하나는 은자작나무로, 다른 하나는 삼나무로 성장할 것이라고 자신있게 예측할 수 있습니다. 대부분의 사람들은 그러한 예측에서 이상한 점을 찾지 못합니다.`,} },
      { type: "paragraph", text: { en: `The botanist cannot determine exactly how many branches each tree will eventually have, nor can he state its precise height, since these factors depend upon soil quality, climate, and environmental conditions. Likewise, he cannot predict the exact lifespan of each tree. Nevertheless, he can accurately describe their general characteristics and growth patterns.`, hi: `वनस्पतिशास्त्री सटीक रूप से यह निर्धारित नहीं कर सकता है कि अंततः प्रत्येक पेड़ की कितनी शाखाएँ होंगी, न ही वह इसकी सटीक ऊँचाई बता सकता है, क्योंकि ये कारक मिट्टी की गुणवत्ता, जलवायु और पर्यावरणीय स्थितियों पर निर्भर करते हैं। इसी तरह, वह प्रत्येक पेड़ के सटीक जीवनकाल की भविष्यवाणी नहीं कर सकता। फिर भी, वह उनकी सामान्य विशेषताओं और विकास पैटर्न का सटीक वर्णन कर सकता है।`, ja: `植物学者は、各木が最終的に何本の枝を持つことになるかを正確に決定することはできません。また、その正確な高さを言うこともできません。これらの要因は土壌の質、気候、環境条件に依存するためです。同様に、各木の正確な寿命を予測することもできません。それにもかかわらず、彼は彼らの一般的な特徴と成長パターンを正確に説明することができます。`, ko: `식물학자는 각 나무가 결국 몇 개의 가지를 가지게 될 것인지 정확히 결정할 수 없으며 정확한 높이도 말할 수 없습니다. 이러한 요소는 토양의 질, 기후 및 환경 조건에 따라 달라지기 때문입니다. 마찬가지로 그는 각 나무의 정확한 수명을 예측할 수 없습니다. 그럼에도 불구하고 그는 그들의 일반적인 특성과 성장 패턴을 정확하게 설명할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `A birth chart can be viewed in much the same way as a seed. Therefore, it should not be surprising that Vedic Astrologers are able to predict broad life trends and tendencies.`, hi: `जन्म कुंडली को बीज की तरह ही देखा जा सकता है। इसलिए, इसमें आश्चर्य नहीं होना चाहिए कि वैदिक ज्योतिषी व्यापक जीवन रुझानों और प्रवृत्तियों की भविष्यवाणी करने में सक्षम हैं।`, ja: `出生図はシードとほぼ同じように見ることができます。したがって、ヴェーダ占星術師が幅広い人生の傾向や傾向を予測できることは驚くべきことではありません。`, ko: `출생 차트는 씨앗과 거의 같은 방식으로 볼 수 있습니다. 그러므로 베다 점성가들이 광범위한 삶의 추세와 경향을 예측할 수 있다는 것은 놀라운 일이 아닙니다.`,} },
      { type: "paragraph", text: { en: `We know that the structure and characteristic development of a tree are encoded within the DNA contained in its seed. In a similar manner, the probable effects of our returning karmas—which themselves unfold according to the laws of nature—are reflected in the "code" contained within the planetary arrangements of the birth chart.`, hi: `हम जानते हैं कि एक पेड़ की संरचना और विशिष्ट विकास उसके बीज में मौजूद डीएनए के भीतर कूटबद्ध होते हैं। इसी प्रकार, हमारे वापस लौटने वाले कर्मों के संभावित प्रभाव - जो स्वयं प्रकृति के नियमों के अनुसार प्रकट होते हैं - जन्म कुंडली की ग्रहों की व्यवस्था के भीतर निहित "कोड" में परिलक्षित होते हैं।`, ja: `木の構造と特徴的な発達は、その種子に含まれる DNA 内にコード化されていることがわかっています。同様に、私たちが戻ってくるカルマの起こり得る影響は、それ自体が自然の法則に従って展開され、出生図の惑星配置に含まれる「コード」に反映されます。`, ko: `우리는 나무의 구조와 특징적인 발달이 나무의 씨앗에 포함된 DNA에 암호화되어 있다는 것을 알고 있습니다. 비슷한 방식으로, 자연의 법칙에 따라 펼쳐지는 우리의 되돌아오는 카르마의 예상되는 결과는 출생 차트의 행성 배열 내에 포함된 "코드"에 반영됩니다.`,} },
      { type: "paragraph", text: { en: `This viewpoint suggests that our time of birth is not merely a random event. Instead, it reflects the Vedic understanding that all life and matter are interconnected within a unified universe.`, hi: `यह दृष्टिकोण बताता है कि हमारे जन्म का समय महज़ एक आकस्मिक घटना नहीं है। इसके बजाय, यह वैदिक समझ को दर्शाता है कि सभी जीवन और पदार्थ एक एकीकृत ब्रह्मांड के भीतर परस्पर जुड़े हुए हैं।`, ja: `この視点は、私たちの誕生の時期が単なる偶然の出来事ではないことを示唆しています。むしろ、すべての生命と物質は統一された宇宙の中で相互に結びついているというヴェーダの理解を反映しています。`, ko: `이러한 관점은 우리의 탄생 시기가 단순히 우연한 사건이 아니라는 점을 시사합니다. 대신, 이는 모든 생명과 물질이 통일된 우주 내에서 상호 연결되어 있다는 베다의 이해를 반영합니다.`,} },
      { type: "heading", level: 3, text: { en: `Road Map Analogy`, hi: `रोड मैप सादृश्य`, ja: `ロードマップの類似点`, ko: `로드맵 비유`,} },
      { type: "paragraph", text: { en: `Vedic Astrology offers a perspective that transcends ordinary limitations of space and time. Rather than travelling along an unfamiliar road without guidance, it provides a view from above—almost as if observing the journey from a helicopter.`, hi: `वैदिक ज्योतिष एक ऐसा दृष्टिकोण प्रस्तुत करता है जो स्थान और समय की सामान्य सीमाओं से परे है। बिना किसी मार्गदर्शन के किसी अपरिचित सड़क पर यात्रा करने के बजाय, यह ऊपर से एक दृश्य प्रदान करता है - लगभग मानो हेलीकॉप्टर से यात्रा का अवलोकन कर रहा हो।`, ja: `ヴェーダ占星術は、通常の空間と時間の制限を超えた視点を提供します。案内なしで見知らぬ道を進むのではなく、まるでヘリコプターから旅を観察しているかのように、上空からの景色を眺めることができます。`, ko: `베다 점성술은 공간과 시간의 일반적인 한계를 초월하는 관점을 제공합니다. 안내 없이 낯선 길을 따라가는 것이 아니라 마치 헬리콥터에서 여행을 관찰하는 것처럼 위에서 내려다보는 풍경을 제공합니다.`,} },
      { type: "paragraph", text: { en: `From this higher vantage point, future turns, changes in terrain, and road conditions become visible before we encounter them. It is similar to navigating with a map instead of attempting to find the way without one.`, hi: `इस उच्च सुविधाजनक बिंदु से, भविष्य के मोड़, इलाके में परिवर्तन और सड़क की स्थिति हमारे सामने आने से पहले ही दिखाई देने लगती है। यह मानचित्र के बिना रास्ता खोजने का प्रयास करने के बजाय मानचित्र के साथ नेविगेट करने के समान है।`, ja: `この高い見晴らしの良い地点からは、将来の曲がり角、地形の変化、道路状況が、それらに遭遇する前に見えるようになります。これは、地図を使わずに道を探すのではなく、地図を使ってナビゲートすることに似ています。`, ko: `더 높은 유리한 지점에서 미래의 방향 전환, 지형 변화, 도로 상태를 우리가 만나기 전에 미리 볼 수 있습니다. 이는 지도 없이 길을 찾는 대신 지도를 가지고 길을 찾는 것과 비슷합니다.`,} },
      { type: "paragraph", text: { en: `Certain areas of life may resemble smooth, straight roads where progress comes easily. Other areas may contain bends, obstacles, or difficult terrain that require greater attention and care. These favourable and challenging periods also change over time as we move through life's journey.`, hi: `जीवन के कुछ क्षेत्र चिकनी, सीधी सड़कों जैसे हो सकते हैं जहाँ प्रगति आसानी से होती है। अन्य क्षेत्रों में मोड़, बाधाएँ या कठिन भूभाग हो सकते हैं जिन पर अधिक ध्यान और देखभाल की आवश्यकता होती है। जैसे-जैसे हम जीवन की यात्रा में आगे बढ़ते हैं, ये अनुकूल और चुनौतीपूर्ण समय भी समय के साथ बदलते रहते हैं।`, ja: `人生の特定の領域は、進歩が容易な滑らかでまっすぐな道に似ているかもしれません。他のエリアには、より注意と注意が必要な曲がり角、障害物、または困難な地形が含まれる場合があります。これらの有利な時期と困難な時期も、人生の旅路を進むにつれて時間の経過とともに変化します。`, ko: `삶의 어떤 영역은 쉽게 발전할 수 있는 평탄하고 곧은 길과 비슷할 수 있습니다. 다른 지역에는 더 많은 주의와 주의가 필요한 굽이진 곳, 장애물 또는 어려운 지형이 있을 수 있습니다. 이러한 유리한 시기와 어려운 시기는 우리가 삶의 여정을 거치면서 시간이 지남에 따라 변하기도 합니다.`,} },
      { type: "paragraph", text: { en: `Having access to the perspective offered by Vedic Astrology can therefore make life easier to navigate and potentially more fulfilling, as it helps us understand what may lie ahead and prepare accordingly.`, hi: `इसलिए वैदिक ज्योतिष द्वारा प्रस्तुत परिप्रेक्ष्य तक पहुंच होने से जीवन को आगे बढ़ाना आसान हो सकता है और संभावित रूप से अधिक संतुष्टिदायक हो सकता है, क्योंकि इससे हमें यह समझने में मदद मिलती है कि आगे क्या हो सकता है और उसके अनुसार तैयारी करें।`, ja: `したがって、ヴェーダ占星術が提供する視点にアクセスできれば、今後何が待ち受けているかを理解し、それに応じて準備するのに役立つため、人生をよりナビゲートしやすくなり、潜在的により充実したものにすることができます。`, ko: `따라서 베다 점성술이 제공하는 관점에 접근하면 앞으로 일어날 일을 이해하고 그에 따라 준비하는 데 도움이 되므로 인생을 더 쉽게 탐색하고 잠재적으로 더 만족스럽게 만들 수 있습니다.`,} },
    ],
  },
  {
    id: "cosmos-individual-1",
    section: "introduction",
    title: { en: `Relationship Between the Cosmos and the Individual`, hi: `ब्रह्मांड और व्यक्ति के बीच संबंध`, ja: `宇宙と個人の関係`, ko: `우주와 개인의 관계`,},
    related: ["forecasting-analogies-1","planetary-forces","origins-of-jyotish"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Relationship Between the Cosmos and the Individual`, hi: `ब्रह्मांड और व्यक्ति के बीच संबंध`, ja: `宇宙と個人の関係`, ko: `우주와 개인의 관계`,} },
      { type: "paragraph", text: { en: `Jyotish Astrology reveals the relationship between the cosmic totality and individual reality. The complete system of sidereal astrology was cognized by the ancient sage Maharishi Parashara, who is said to have revealed the mathematical and astronomical principles used to forecast future trends and prescribe remedial measures designed to minimise potential difficulties.`, hi: `ज्योतिष शास्त्र ब्रह्मांडीय समग्रता और व्यक्तिगत वास्तविकता के बीच संबंध को प्रकट करता है। नाक्षत्र ज्योतिष की पूरी प्रणाली को प्राचीन ऋषि महर्षि पराशर द्वारा मान्यता दी गई थी, जिनके बारे में कहा जाता है कि उन्होंने भविष्य के रुझानों की भविष्यवाणी करने और संभावित कठिनाइयों को कम करने के लिए डिज़ाइन किए गए उपचारात्मक उपायों को निर्धारित करने के लिए उपयोग किए जाने वाले गणितीय और खगोलीय सिद्धांतों का खुलासा किया था।`, ja: `ジョーティッシュは、宇宙の全体性と個人の現実との関係を明らかにします。恒星占星術の完全なシステムは古代の聖者マハリシ・パラシャラによって認識され、将来の傾向を予測し、潜在的な困難を最小限に抑えるための是正措置を処方するために使用される数学的および天文学的な原理を明らかにしたと言われています。`, ko: `조티쉬 점성술은 우주 전체와 개인의 현실 사이의 관계를 드러냅니다. 항성 점성술의 전체 시스템은 고대 현자 마하리시 파라샤라(Maharishi Parashara)에 의해 인식되었으며, 그는 미래의 추세를 예측하고 잠재적인 어려움을 최소화하기 위해 고안된 교정 조치를 처방하는 데 사용되는 수학적, 천문학적 원리를 밝혀냈다고 합니다.`,} },
      { type: "paragraph", text: { en: `According to this understanding, the cosmos is an intelligently organised and deeply interconnected whole. Events do not occur in isolation; rather, one event naturally leads to another through an ongoing process of unfoldment.`, hi: `इस समझ के अनुसार, ब्रह्मांड एक बुद्धिमानी से संगठित और गहराई से परस्पर जुड़ा हुआ संपूर्ण है। घटनाएँ अकेले नहीं घटतीं; बल्कि, एक घटना स्वाभाविक रूप से निरंतर जारी रहने वाली प्रक्रिया के माध्यम से दूसरी घटना की ओर ले जाती है।`, ja: `この理解によれば、宇宙は知的に組織化され、深く相互接続された全体です。イベントは単独で発生するわけではありません。むしろ、ある出来事は進行中の展開プロセスを通じて自然に別の出来事につながります。`, ko: `이러한 이해에 따르면 우주는 지능적으로 조직되고 깊이 상호 연결된 전체입니다. 이벤트는 단독으로 발생하지 않습니다. 오히려 하나의 사건은 계속되는 전개 과정을 통해 자연스럽게 다른 사건으로 이어진다.`,} },
      { type: "paragraph", text: { en: `From this perspective, the future can be understood by interpreting the code contained within the planetary arrangements present at the time of birth. Through this cosmic blueprint, Jyotish seeks to reveal the relationship between individual experience and the greater intelligence that governs the universe.`, hi: `इस दृष्टिकोण से जन्म के समय मौजूद ग्रहीय व्यवस्था में निहित कोड की व्याख्या करके भविष्य को समझा जा सकता है। इस ब्रह्मांडीय खाका के माध्यम से, ज्योतिष व्यक्तिगत अनुभव और ब्रह्मांड को नियंत्रित करने वाली महान बुद्धि के बीच संबंध को प्रकट करना चाहता है।`, ja: `この観点から、誕生時に存在する惑星配置に含まれるコードを解釈することで、未来を理解することができます。ジョーティッシュは、この宇宙の青写真を通じて、個人の経験と宇宙を支配するより大きな知性との関係を明らかにしようとしています。`, ko: `이러한 관점에서 미래는 탄생 당시 존재했던 행성 배열에 포함된 코드를 해석함으로써 이해될 수 있습니다. 이 우주 청사진을 통해 Jyotish는 개인의 경험과 우주를 지배하는 더 큰 지능 사이의 관계를 밝히려고 합니다.`,} },
    ],
  },
  {
    id: "planetary-antidotes",
    section: "remedies",
    title: { en: `Planetary Antidotes in Jyotish`, hi: `ज्योतिष में ग्रह मारक उपाय`, ja: `ジョーティッシュの惑星解毒剤`, ko: `Jyotish의 행성 해독제`,},
    related: ["gemstones","mantras","preventive-capabilities"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Planetary Antidotes in Jyotish`, hi: `ज्योतिष में ग्रह मारक उपाय`, ja: `ジョーティッシュの惑星解毒剤`, ko: `Jyotish의 행성 해독제`,} },
      { type: "paragraph", text: { en: `Summary: This article explores Remedial Measures or Planetary Antidotes (Upaye or Upayes) in Jyotish. It includes a detailed discussion of wearing gemstones associated with specific planets, chanting planetary mantras, performing charitable acts, and conducting Vedic rituals to harmonise planetary energies.`, hi: `सारांश: यह लेख ज्योतिष में उपचारात्मक उपायों या ग्रह मारक (उपाय या उपाय) की पड़ताल करता है। इसमें विशिष्ट ग्रहों से संबंधित रत्न पहनने, ग्रहों के मंत्रों का जाप करने, धर्मार्थ कार्य करने और ग्रहों की ऊर्जा में सामंजस्य स्थापित करने के लिए वैदिक अनुष्ठान करने की विस्तृत चर्चा शामिल है।`, ja: `概要: この記事では、ジョーティッシュにおける改善法または惑星への対処法 (Upaye または Upayes) について探ります。これには、特定の惑星に関連付けられた宝石の着用、惑星のマントラの唱え、慈善行為の実行、惑星のエネルギーを調和させるためのヴェーダ儀式の実施についての詳細な議論が含まれています。`, ko: `요약: 이 기사에서는 Jyotish의 치료 조치 또는 행성 해독제(Upaye 또는 Upayes)를 살펴봅니다. 여기에는 특정 행성과 관련된 보석 착용, 행성의 만트라 외침, 자선 행위 수행, 행성 에너지의 조화를 위한 베다 의식 수행에 대한 자세한 논의가 포함됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Planetary Antidotes (Upaye) – Remedial Measures in Jyotish`, hi: `ग्रह मारक उपाय (उपाय) - ज्योतिष में उपाय`, ja: `惑星への対処法 (Upaye) – ジョーティッシュの改善法`, ko: `행성 해독제(Upaye) – Jyotish의 치료 조치`,} },
      { type: "paragraph", text: { en: `Vedic Astrology is fundamentally karmic in nature. It predicts both the type and duration of positive and negative returning karma, helping us understand what experiences are likely to arise in different areas of life and, perhaps most importantly, when they are likely to occur.`, hi: `वैदिक ज्योतिष मूलतः कर्म प्रधान है। यह सकारात्मक और नकारात्मक रिटर्निंग कर्म के प्रकार और अवधि दोनों की भविष्यवाणी करता है, जिससे हमें यह समझने में मदद मिलती है कि जीवन के विभिन्न क्षेत्रों में क्या अनुभव उत्पन्न होने की संभावना है और, शायद सबसे महत्वपूर्ण बात यह है कि वे कब घटित होने की संभावना है।`, ja: `ヴェーダ占星術は基本的にカルマ的な性質を持っています。これは、ポジティブなカルマとネガティブなカルマの種類と期間の両方を予測し、人生のさまざまな分野でどのような経験が発生する可能性があるのか​​、そしておそらく最も重要なのは、それらがいつ発生する可能性があるのか​​を理解するのに役立ちます。`, ko: `베다 점성술은 근본적으로 본질적으로 카르마적입니다. 이는 긍정적인 카르마와 부정적인 카르마의 유형과 기간을 모두 예측하여 삶의 다양한 영역에서 어떤 경험이 발생할 가능성이 있는지, 그리고 아마도 가장 중요하게는 이러한 경험이 발생할 가능성이 있는 시기를 이해하는 데 도움이 됩니다.`,} },
      { type: "paragraph", text: { en: `One of the great strengths of Jyotish is that it comes from a tradition which teaches that suffering is not inevitable. It is therefore no surprise that Jyotish provides a range of practical techniques designed to deflect, minimise, or greatly reduce the effects of returning negative karma. These methods are commonly known as remedial measures or planetary antidotes (Upaye or Upayes).`, hi: `ज्योतिष की एक बड़ी ताकत यह है कि यह उस परंपरा से आता है जो सिखाती है कि दुख अपरिहार्य नहीं है। इसलिए इसमें कोई आश्चर्य की बात नहीं है कि ज्योतिष नकारात्मक कर्मों के प्रभावों को हटाने, कम करने या बहुत कम करने के लिए डिज़ाइन की गई व्यावहारिक तकनीकों की एक श्रृंखला प्रदान करता है। इन विधियों को आमतौर पर उपचारात्मक उपाय या ग्रह मारक (उपाय या उपाय) के रूप में जाना जाता है।`, ja: `ジョーティッシュの大きな強みの 1 つは、苦しみは避けられないものであると教える伝統に由来していることです。したがって、ジョーティッシュが、戻ってくる負のカルマの影響を逸らし、最小限に抑え、または大幅に軽減するように設計された一連の実践的なテクニックを提供することは驚くべきことではありません。これらの方法は一般に、改善法または惑星への対処法 (Upaye または Upayes) として知られています。`, ko: `Jyotish의 가장 큰 장점 중 하나는 고통이 불가피하지 않다고 가르치는 전통에서 유래했다는 것입니다. 따라서 Jyotish가 부정적인 카르마 반환의 영향을 편향, 최소화 또는 크게 줄이기 위해 고안된 다양한 실용적인 기술을 제공한다는 것은 놀라운 일이 아닙니다. 이러한 방법은 일반적으로 치료 조치 또는 행성 해독제(Upaye 또는 Upayes)로 알려져 있습니다.`,} },
      { type: "paragraph", text: { en: `A Vedic Astrologer can identify imbalances within an individual's birth chart by interpreting the code represented by the planetary positions at birth. Based on this analysis, practical recommendations can be given to help "avert the danger that has not yet arisen." While these remedies may not completely eliminate karma, they can certainly modify its effects and lessen its impact.`, hi: `एक वैदिक ज्योतिषी जन्म के समय ग्रहों की स्थिति द्वारा दर्शाए गए कोड की व्याख्या करके किसी व्यक्ति की जन्म कुंडली में असंतुलन की पहचान कर सकता है। इस विश्लेषण के आधार पर, "उस खतरे को टालने में मदद करने के लिए व्यावहारिक सिफारिशें दी जा सकती हैं जो अभी तक उत्पन्न नहीं हुआ है।" हालाँकि ये उपाय कर्म को पूरी तरह से समाप्त नहीं कर सकते हैं, लेकिन वे निश्चित रूप से इसके प्रभावों को संशोधित कर सकते हैं और इसके प्रभाव को कम कर सकते हैं।`, ja: `ヴェーダ占星術師は、出生時の惑星の位置によって表されるコードを解釈することで、個人の出生図内のアンバランスを特定できます。この分析に基づいて、「まだ生じていない危険を回避する」ための実践的な推奨事項を与えることができます。これらの治療法はカルマを完全に取り除くことはできないかもしれませんが、確実にその効果を修正し、その影響を軽減することができます。`, ko: `베다 점성가는 출생 시 행성 위치로 표시되는 코드를 해석하여 개인의 출생 차트 내 불균형을 식별할 수 있습니다. 이 분석을 바탕으로 "아직 발생하지 않은 위험을 방지"하는 데 도움이 되는 실용적인 권장 사항을 제시할 수 있습니다. 이러한 치료법이 카르마를 완전히 제거할 수는 없지만 카르마의 효과를 수정하고 영향을 줄일 수는 있습니다.`,} },
      eduImage(educationImages.planetaryAntidotes, {
        en: "Vedic ritual with offerings — a traditional planetary antidote",
        hi: "वैदिक अनुष्ठान और प्रसाद — एक पारंपरिक ग्रह मारक उपाय",
        ja: "供物を伴うヴェーダ儀式 — 伝統的な惑星への対処法",
        ko: "공물이 있는 베다 의식 — 전통적인 행성 해독제",
      }),
      { type: "paragraph", text: { en: `Planetary remedies are intended to balance negative planetary influences and restore greater harmony and equilibrium in life. They can also strengthen positive planetary influences, thereby maximising favourable returning karmas.`, hi: `ग्रहों के उपचार का उद्देश्य नकारात्मक ग्रहों के प्रभावों को संतुलित करना और जीवन में अधिक सामंजस्य और संतुलन बहाल करना है। वे सकारात्मक ग्रहों के प्रभाव को भी मजबूत कर सकते हैं, जिससे अनुकूल रिटर्न वाले कर्मों को अधिकतम किया जा सकता है।`, ja: `惑星のレメディは、惑星のマイナスの影響のバランスを取り、人生におけるより大きな調和と平衡を回復することを目的としています。また、惑星のポジティブな影響を強化し、それによって戻ってくる好ましいカルマを最大化することもできます。`, ko: `행성 치료는 부정적인 행성 영향의 균형을 맞추고 삶의 더 큰 조화와 균형을 회복하기 위한 것입니다. 그들은 또한 긍정적인 행성 영향력을 강화하여 유리한 복귀 카르마를 최대화할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The remedial measures prescribed in Jyotish generally fall into four main categories:`, hi: `ज्योतिष में बताए गए उपचारात्मक उपाय आम तौर पर चार मुख्य श्रेणियों में आते हैं:`, ja: `ジョーティッシュで規定されている是正措置は、通常、次の 4 つの主要なカテゴリに分類されます。`, ko: `Jyotish에 규정된 교정 조치는 일반적으로 네 가지 주요 범주로 나뉩니다.`,} },
      { type: "paragraph", text: { en: `• Wearing gemstones associated with a particular planet`, hi: `• किसी विशेष ग्रह से संबंधित रत्न धारण करना`, ja: `• 特定の惑星に関連した宝石を身につける`, ko: `• 특정 행성과 관련된 보석 착용`,} },
      { type: "paragraph", text: { en: `• Chanting planetary-related mantras`, hi: `• ग्रह संबंधी मंत्रों का जाप करें`, ja: `• 惑星関連のマントラを唱える`, ko: `• 행성과 관련된 주문을 외우기`,} },
      { type: "paragraph", text: { en: `• Performing specific acts of charity`, hi: `• दान के विशिष्ट कार्य करना`, ja: `• 特定の慈善行為の実行`, ko: `• 특정 자선 활동 수행`,} },
      { type: "paragraph", text: { en: `• Conducting Vedic rituals to balance planetary energies`, hi: `• ग्रहों की ऊर्जा को संतुलित करने के लिए वैदिक अनुष्ठानों का संचालन करना`, ja: `• 惑星エネルギーのバランスをとるためのヴェーダ儀式の実施`, ko: `• 행성 에너지의 균형을 맞추기 위한 베다 의식 수행`,} },
      { type: "paragraph", text: { en: `These remedies are not based on superstition. They have survived the test of time through countless generations. Their effectiveness is rooted in the Vedic understanding that everything in the universe is interconnected. This Vedic Model of Reality is increasingly finding support from modern scientific perspectives and is also reflected in the Vedic and Buddhist concept of Indra's Net [1].`, hi: `ये उपाय अंधविश्वास पर आधारित नहीं हैं. वे अनगिनत पीढ़ियों तक समय की कसौटी पर खरे उतरे हैं। उनकी प्रभावशीलता वैदिक समझ में निहित है कि ब्रह्मांड में सब कुछ आपस में जुड़ा हुआ है। वास्तविकता के इस वैदिक मॉडल को आधुनिक वैज्ञानिक दृष्टिकोण से तेजी से समर्थन मिल रहा है और यह इंद्र के जाल की वैदिक और बौद्ध अवधारणा में भी परिलक्षित होता है [1]।`, ja: `これらの治療法は迷信に基づいたものではありません。彼らは数え切れないほどの世代を経て、時の試練を乗り越えてきました。その有効性は、宇宙のすべてが相互につながっているというヴェーダの理解に根ざしています。このヴェーダの現実モデルは、現代科学の観点からますます支持されており、ヴェーダと仏教のインドラの網の概念にも反映されています [1]。`, ko: `이러한 치료법은 미신에 근거한 것이 아닙니다. 그들은 셀 수 없이 많은 세대를 거쳐 시간의 시험에서 살아남았습니다. 그 효과는 우주의 모든 것이 서로 연결되어 있다는 베다의 이해에 뿌리를 두고 있습니다. 현실에 대한 이 베다 모델은 현대 과학적 관점에서 점점 더 많은 지지를 얻고 있으며 인드라 그물(Indra's Net)의 베다 및 불교 개념에도 반영됩니다[1].`,} },
      { type: "paragraph", text: { en: `There is a famous lyric from a song by Joni Mitchell released in 1970: "We are stardust, we are golden." From the perspective of modern astrophysics, this is remarkably true. Nearly all the elements that make up the human body, apart from hydrogen, were forged in the interiors of stars billions of years ago. We therefore have a genuine connection with the stars because much of the material from which we are made originated there. Many people report that wearing a high-quality Jyotish gemstone reminds them of this connection at a very deep level.`, hi: `1970 में रिलीज़ जोनी मिशेल के एक गीत का एक प्रसिद्ध गीत है: "वी आर स्टारडस्ट, वी आर गोल्डन।" आधुनिक खगोल भौतिकी के दृष्टिकोण से, यह उल्लेखनीय रूप से सत्य है। हाइड्रोजन को छोड़कर, मानव शरीर को बनाने वाले लगभग सभी तत्व अरबों साल पहले तारों के आंतरिक भाग में निर्मित हुए थे। इसलिए तारों के साथ हमारा वास्तविक संबंध है क्योंकि जिन सामग्रियों से हम बने हैं उनमें से अधिकांश की उत्पत्ति वहीं हुई है। बहुत से लोग रिपोर्ट करते हैं कि उच्च गुणवत्ता वाला ज्योतिष रत्न पहनने से उन्हें बहुत गहरे स्तर पर इस संबंध की याद आती है।`, ja: `1970年にリリースされたジョニ・ミッチェルの曲に「私たちはスターダスト、私たちは黄金だ」という有名な歌詞があります。現代の天体物理学の観点から見ると、これは驚くほど真実です。水素を除く人体を構成するほぼすべての元素は、数十億年前に星の内部で作られました。したがって、私たちは星と真のつながりを持っています。なぜなら、私たちが作られている物質の多くは星から来ているからです。多くの人が、高品質のジョーティッシュの宝石を身に着けると、このつながりを非常に深いレベルで思い出させると報告しています。`, ko: `1970년에 발표된 조니 미첼(Joni Mitchell)의 노래에는 "We are stardust, we are gold"라는 유명한 가사가 있습니다. 현대 천체물리학의 관점에서 보면 이는 놀라운 사실이다. 수소를 제외하고 인체를 구성하는 거의 모든 요소는 수십억 년 전에 별 내부에서 만들어졌습니다. 따라서 우리를 구성하는 물질의 대부분이 별에서 유래되었기 때문에 우리는 별과 진정한 관계를 맺고 있습니다. 많은 사람들은 고품질의 Jyotish 보석을 착용하는 것이 매우 깊은 수준에서 이러한 연결을 상기시킨다고 보고합니다.`,} },
      { type: "paragraph", text: { en: `Although not specifically discussed in the classical Jyotish texts, many astrologers also agree that spiritual practices can significantly modify returning karma. In particular, mantra-based Vedic meditation techniques appear to have a profound effect. When astrologers examined the birth charts of long-term meditators, they often found that their actual life experiences were considerably more favourable than the charts alone might have suggested.`, hi: `यद्यपि शास्त्रीय ज्योतिष ग्रंथों में विशेष रूप से चर्चा नहीं की गई है, कई ज्योतिषी भी इस बात से सहमत हैं कि आध्यात्मिक अभ्यास रिटर्निंग कर्म को महत्वपूर्ण रूप से संशोधित कर सकते हैं। विशेष रूप से, मंत्र-आधारित वैदिक ध्यान तकनीकों का गहरा प्रभाव पड़ता है। जब ज्योतिषियों ने लंबे समय तक ध्यान करने वालों की जन्म कुंडली की जांच की, तो उन्होंने अक्सर पाया कि उनके वास्तविक जीवन के अनुभव अकेले चार्ट द्वारा सुझाए गए से कहीं अधिक अनुकूल थे।`, ja: `古典的なジョーティッシュの文献では特に議論されていませんが、多くの占星術師は、スピリチュアルな実践が戻ってくるカルマを大幅に変える可能性があることに同意しています。特に、マントラに基づいたヴェーダ瞑想テクニックは深い効果があるようです。占星術師が長期瞑想者の出生図を調べたとき、彼らの実際の人生経験は、図だけが示唆するよりもかなり好ましいことがよくわかりました。`, ko: `비록 고전 조티쉬 문헌에서 구체적으로 논의되지는 않았지만, 많은 점성가들 역시 영적인 수행이 카르마를 되돌리는데 큰 변화를 가져올 수 있다는 점에 동의합니다. 특히 만트라를 기반으로 한 베다 명상 기법은 지대한 영향을 미치는 것으로 보입니다. 점성가들이 장기 명상자의 출생 차트를 조사했을 때, 그들은 종종 그들의 실제 삶의 경험이 차트만으로 제시된 것보다 훨씬 더 유리하다는 사실을 발견했습니다.`,} },
      { type: "paragraph", text: { en: `For those fortunate enough to have a personal Guru, the Grace of the Guru can remove major obstacles from life. Such individuals should consider themselves especially blessed.`, hi: `उन भाग्यशाली लोगों के लिए जिनके पास व्यक्तिगत गुरु है, गुरु की कृपा जीवन से बड़ी बाधाओं को दूर कर सकती है। ऐसे व्यक्तियों को स्वयं को विशेष रूप से धन्य समझना चाहिए।`, ja: `個人的なグルを持つ幸運な人にとって、グルの恩寵は人生から大きな障害を取り除くことができます。そのような人は自分が特に恵まれていると考えるべきです。`, ko: `운이 좋게도 개인 전문가가 있는 사람들의 경우, 전문가의 은총이 삶의 주요 장애물을 제거할 수 있습니다. 그러한 사람들은 자신들이 특히 축복받았다고 생각해야 합니다.`,} },
    ],
  },
  {
    id: "gemstones",
    section: "remedies",
    title: { en: `Wearing Gemstones as Planetary Antidotes`, hi: `ग्रहों की मारक औषधि के रूप में रत्न धारण करना`, ja: `惑星への対処法として宝石を身につける`, ko: `행성 해독제로 보석 착용`,},
    related: ["planetary-antidotes","mantras","natural-benefics-malefics"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Wearing Gemstones as Planetary Antidotes`, hi: `ग्रहों की मारक औषधि के रूप में रत्न धारण करना`, ja: `惑星への対処法として宝石を身につける`, ko: `행성 해독제로 보석 착용`,} },
      { type: "paragraph", text: { en: `In Vedic Astrology, every planet is associated with a specific gemstone. For example, the Sun corresponds to ruby, Venus to diamond, and Saturn to blue sapphire. When an auspicious planet in the birth chart requires strengthening—and in Jyotish a stronger auspicious planet is generally beneficial—wearing the gemstone associated with that planet can help amplify its positive influence.`, hi: `वैदिक ज्योतिष में प्रत्येक ग्रह एक विशिष्ट रत्न से सम्बंधित है। उदाहरण के लिए, सूर्य माणिक से, शुक्र हीरे से, और शनि नीले नीलम से मेल खाता है। जब जन्म कुंडली में किसी शुभ ग्रह को मजबूत करने की आवश्यकता होती है - और ज्योतिष में एक मजबूत शुभ ग्रह आम तौर पर फायदेमंद होता है - तो उस ग्रह से संबंधित रत्न पहनने से उसके सकारात्मक प्रभाव को बढ़ाने में मदद मिल सकती है।`, ja: `ヴェーダ占星術では、すべての惑星は特定の宝石に関連付けられています。たとえば、太陽はルビー、金星はダイヤモンド、土星はブルー サファイアに対応します。出生図の縁起の良い惑星が強化を必要とする場合、そしてジョーティッシュでは、より強力な縁起の良い惑星は一般的に有益です。その惑星に関連付けられた宝石を身に着けることで、そのポジティブな影響を増幅させることができます。`, ko: `베다 점성술에서 모든 행성은 특정 보석과 연관되어 있습니다. 예를 들어, 태양은 루비에 해당하고, 금성은 다이아몬드에, 토성은 블루 사파이어에 해당합니다. 출생 차트에 있는 상서로운 행성이 강화가 필요한 경우(Jyotish에서는 더 강한 상서로운 행성이 일반적으로 유익함) 해당 행성과 관련된 보석을 착용하면 긍정적인 영향력을 증폭시키는 데 도움이 될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The key word here is auspicious. Only auspicious planets should be strengthened through gemstones. In this context, auspicious means a functional benefic. If a planet is not auspicious for a particular Ascendant, alternative remedial measures, such as mantras, are generally recommended instead.`, hi: `यहाँ मुख्य शब्द शुभ है। रत्नों के माध्यम से केवल शुभ ग्रहों को ही मजबूत करना चाहिए। इस सन्दर्भ में शुभ का अर्थ क्रियात्मक लाभ से है। यदि कोई ग्रह किसी विशेष लग्न के लिए शुभ नहीं है, तो आमतौर पर इसके बजाय मंत्र जैसे वैकल्पिक उपचार उपायों की सिफारिश की जाती है।`, ja: `The key word here is auspicious.縁起の良い惑星だけを宝石を通じて強化する必要があります。この文脈での縁起は、機能的な利益を意味します。特定のアセンダントにとって惑星が縁起が良くない場合は、通常、代わりにマントラなどの代替手段が推奨されます。`, ko: `여기서 핵심 단어는 길조입니다. 상서로운 행성만이 보석을 통해 강화되어야 합니다. 이러한 맥락에서 길조는 기능적 유익을 의미합니다. 행성이 특정 승천자에게 길조가 아닌 경우 일반적으로 만트라와 같은 대체 치료 조치가 권장됩니다.`,} },
      { type: "paragraph", text: { en: `Unfortunately, some modern Jyotish books fail to explain this important distinction clearly, which can lead to serious misunderstandings.`, hi: `दुर्भाग्य से, कुछ आधुनिक ज्योतिष पुस्तकें इस महत्वपूर्ण अंतर को स्पष्ट रूप से समझाने में विफल रहती हैं, जिससे गंभीर गलतफहमियाँ पैदा हो सकती हैं।`, ja: `残念ながら、現代のジョーティッシュの本の中にはこの重要な違いを明確に説明していないものがあり、重大な誤解を招く可能性があります。`, ko: `불행하게도 일부 현대 Jyotish 책에서는 이 중요한 차이점을 명확하게 설명하지 못하여 심각한 오해를 초래할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Because many planets rule two houses simultaneously, determining whether a planet is favourable or unfavourable for a particular Ascendant can become quite complex. As the Ascendant changes within the Sidereal Zodiac, the functional benefic or functional malefic nature of a planet also changes.`, hi: `चूँकि कई ग्रह एक साथ दो घरों पर शासन करते हैं, इसलिए यह निर्धारित करना कि कोई ग्रह किसी विशेष लग्न के लिए अनुकूल है या प्रतिकूल, काफी जटिल हो सकता है। जैसे-जैसे नक्षत्र राशि चक्र में लग्न बदलता है, ग्रह की कार्यात्मक शुभ या कार्यात्मक अशुभ प्रकृति भी बदल जाती है।`, ja: `多くの惑星は 2 つのハウスを同時に支配しているため、ある惑星が特定のアセンダントにとって有利か不利かを判断することは非常に複雑になる可能性があります。恒星黄道帯内でアセンダントが変化すると、惑星の機能的有益性または機能的凶悪性の性質も変化します。`, ko: `많은 행성이 두 하우스를 동시에 지배하기 때문에 행성이 특정 어센던트에게 유리한지 불리한지를 결정하는 것은 상당히 복잡할 수 있습니다. 항성 황도대 내에서 어센던트가 변경됨에 따라 행성의 기능적 유익성 또는 기능적 유해성도 변경됩니다.`,} },
      { type: "paragraph", text: { en: `This topic is discussed in greater detail elsewhere, but as a broad guideline—and Jyotish always has exceptions—any planet ruling the first, fifth, or ninth house is generally considered auspicious regardless of any secondary house ownership.`, hi: `इस विषय पर अन्यत्र अधिक विस्तार से चर्चा की गई है, लेकिन एक व्यापक दिशानिर्देश के रूप में - और ज्योतिष में हमेशा अपवाद होते हैं - पहले, पांचवें, या नौवें घर पर शासन करने वाले किसी भी ग्रह को आम तौर पर किसी भी द्वितीयक घर के स्वामित्व की परवाह किए बिना शुभ माना जाता है।`, ja: `このトピックについては他の場所で詳しく説明されていますが、大まかなガイドラインとして、ジョーティッシュには常に例外がありますが、第 2 ハウスの所有権に関係なく、第 1、第 5、または第 9 ハウスを支配する惑星は一般に縁起が良いと考えられます。`, ko: `이 주제는 다른 곳에서 더 자세히 논의되지만 광범위한 지침에 따라(Jyotish에는 항상 예외가 있습니다) 1하우스, 5하우스, 9하우스를 지배하는 모든 행성은 일반적으로 2차 하우스 소유권에 관계없이 상서로운 것으로 간주됩니다.`,} },
      { type: "heading", level: 3, text: { en: `Planet and Gemstone Associations in Jyotish`, hi: `ज्योतिष में ग्रह एवं रत्न संघ`, ja: `ジョーティッシュの惑星と宝石協会`, ko: `Jyotish의 행성 및 보석 협회`,} },
      { type: "paragraph", text: { en: `The traditional gemstone associations for the nine planets are as follows:`, hi: `नौ ग्रहों के लिए पारंपरिक रत्न संबंध इस प्रकार हैं:`, ja: `9 つの惑星の伝統的な宝石の関連付けは次のとおりです。`, ko: `9개의 행성에 대한 전통적인 보석 협회는 다음과 같습니다:`,} },
      { type: "paragraph", text: { en: `• Sun – Ruby`, hi: `• सूर्य - माणिक्य`, ja: `• サン – ルビー`, ko: `• 썬 – 루비`,} },
      { type: "paragraph", text: { en: `• Moon – Pearl`, hi: `• चन्द्रमा – मोती`, ja: `• ムーン – パール`, ko: `• 달 – 진주`,} },
      { type: "paragraph", text: { en: `• Mars – Red Coral`, hi: `• मंगल - लाल मूंगा`, ja: `• 火星 – 赤珊瑚`, ko: `• 화성 – 붉은 산호`,} },
      { type: "paragraph", text: { en: `• Mercury – Emerald`, hi: `• बुध-पन्ना`, ja: `• 水星 – エメラルド`, ko: `• 수성 – 에메랄드`,} },
      { type: "paragraph", text: { en: `• Jupiter – Yellow Sapphire`, hi: `• बृहस्पति - पीला नीलमणि`, ja: `• ジュピター – イエロー サファイア`, ko: `• 목성 – 옐로우 사파이어`,} },
      { type: "paragraph", text: { en: `• Venus – Diamond`, hi: `• शुक्र - हीरा`, ja: `• 金星 – ダイヤモンド`, ko: `• 금성 – 다이아몬드`,} },
      { type: "paragraph", text: { en: `• Saturn – Blue Sapphire`, hi: `• शनि-नीला नीलम`, ja: `• 土星 – ブルーサファイア`, ko: `• 토성 – 블루 사파이어`,} },
      { type: "paragraph", text: { en: `• Rahu – Gomed (Hessonite Garnet)`, hi: `• राहु - गोमेद (हेसोनाइट गार्नेट)`, ja: `• ラーフ – ゴメッド (ヘソナイト ガーネット)`, ko: `• 라후 – 고메드(헤소나이트 가넷)`,} },
      { type: "paragraph", text: { en: `• Ketu – Cat's Eye (Chrysoberyl)`, hi: `• केतु - बिल्ली की आँख (क्राइसोबेरील)`, ja: `• Ketu – キャッツアイ (クリソベリル)`, ko: `• Ketu – 고양이 눈(Chrysoberyl)`,} },
      { type: "paragraph", text: { en: `Note: Gomed is also known as Hessonite Garnet, while Cat's Eye generally refers to Chrysoberyl.`, hi: `नोट: गोमेद को हेसोनाइट गार्नेट के नाम से भी जाना जाता है, जबकि कैट्स आई आमतौर पर क्राइसोबेरील को संदर्भित करता है।`, ja: `注: ゴメッドはヘソナイト ガーネットとしても知られていますが、キャッツアイは一般的にクリソベリルを指します。`, ko: `참고: Gomed는 Hessonite Garnet으로도 알려져 있으며 Cat's Eye는 일반적으로 Chrysoberyl을 나타냅니다.`,} },
      eduImage(educationImages.gemstone2, {
        en: "Planet and gemstone associations in Jyotish (2)", hi: "ज्योतिष में ग्रह एवं रत्न संबंध (2)", ja: "ジョーティッシュにおける惑星と宝石の対応（2）", ko: "Jyotish의 행성 및 보석 협회 (2)",
      }),
      eduImage(educationImages.gemstone3, {
        en: "Planet and gemstone associations in Jyotish (3)", hi: "ज्योतिष में ग्रह एवं रत्न संबंध (3)", ja: "ジョーティッシュにおける惑星と宝石の対応（3）", ko: "Jyotish의 행성 및 보석 협회 (3)",
      }),
      eduImage(educationImages.gemstone1, {
        en: "Planet and gemstone associations in Jyotish (1)", hi: "ज्योतिष में ग्रह एवं रत्न संबंध (1)", ja: "ジョーティッシュにおける惑星と宝石の対応（1）", ko: "Jyotish의 행성 및 보석 협회 (1)",
      }),
      { type: "paragraph", text: { en: `Jyotish is also very specific regarding the weight and quality of gemstones, the metal in which they should be set, and even the finger on which they should be worn [2]. For remedial purposes, gemstones should ideally be natural rather than synthetic or laboratory-created [3].`, hi: `ज्योतिष रत्नों के वजन और गुणवत्ता, उन्हें किस धातु में स्थापित किया जाना चाहिए और यहां तक ​​कि उन्हें किस उंगली में पहना जाना चाहिए, इस संबंध में भी बहुत विशिष्ट है। उपचारात्मक उद्देश्यों के लिए, रत्न सिंथेटिक या प्रयोगशाला-निर्मित होने के बजाय आदर्श रूप से प्राकृतिक होने चाहिए [3]।`, ja: `ジョーティッシュはまた、宝石の重量と品質、宝石をはめ込む金属、さらには宝石を着用する指にさえも非常にこだわりがあります [2]。修復目的の場合、宝石は合成または実験室で作成されたものではなく、天然のものであることが理想的です [3]。`, ko: `Jyotish는 또한 보석의 무게와 품질, 보석을 장착해야 하는 금속, 심지어 보석을 착용해야 하는 손가락에 대해서도 매우 구체적입니다[2]. 치료 목적으로 원석은 합성이나 실험실에서 만들어진 것보다는 이상적으로 천연이어야 합니다[3].`,} },
      { type: "paragraph", text: { en: `To be effective, gemstones should remain in contact with the skin. This is typically achieved through specially designed ring settings or by wearing the stone as a pendant.`, hi: `प्रभावी होने के लिए, रत्नों को त्वचा के संपर्क में रहना चाहिए। यह आमतौर पर विशेष रूप से डिज़ाइन की गई रिंग सेटिंग्स के माध्यम से या पत्थर को पेंडेंट के रूप में पहनकर हासिल किया जाता है।`, ja: `効果を発揮するには、宝石が肌に触れたままにする必要があります。これは通常、特別にデザインされたリングのセッティング、または石をペンダントとして着用することによって実現されます。`, ko: `효과가 있으려면 보석이 피부에 접촉된 상태를 유지해야 합니다. 이는 일반적으로 특별히 디자인된 링 세팅을 통해 또는 스톤을 펜던트로 착용함으로써 달성됩니다.`,} },
      { type: "paragraph", text: { en: `Some Jyotish experts even suggest that the gold itself—provided it is 22-carat quality—may reduce a significant proportion of planetary negativity when worn in a chain or ring. If correct, this is certainly an interesting observation.`, hi: `कुछ ज्योतिष विशेषज्ञों का यह भी सुझाव है कि सोना - बशर्ते कि वह 22 कैरेट गुणवत्ता का हो - चेन या अंगूठी में पहनने पर ग्रहों की नकारात्मकता के एक महत्वपूर्ण अनुपात को कम कर सकता है। यदि सही है, तो यह निश्चित रूप से एक दिलचस्प अवलोकन है।`, ja: `一部のジョーティッシュ専門家は、金自体が（22カラットの品質であれば）チェーンやリングに身に着けると、惑星のネガティブな要素のかなりの部分を軽減できる可能性があるとさえ示唆しています。もし正しければ、これは確かに興味深い観察です。`, ko: `일부 Jyotish 전문가들은 금 자체가 22캐럿 품질이라면 체인이나 반지에 착용할 때 행성의 부정적인 영향을 상당 부분 줄일 수 있다고 제안합니다. 만약 맞다면 이것은 확실히 흥미로운 관찰입니다.`,} },
      { type: "paragraph", text: { en: `Compared with Western Astrology, the use of gemstones in Jyotish is far more personalised. Western systems typically assign a birthstone based upon an individual's Sun sign, whereas Vedic Astrology recommends gemstones based upon a detailed analysis of the entire birth chart.`, hi: `पश्चिमी ज्योतिष की तुलना में, ज्योतिष में रत्नों का उपयोग कहीं अधिक व्यक्तिगत है। पश्चिमी प्रणालियाँ आम तौर पर किसी व्यक्ति की सूर्य राशि के आधार पर जन्म का रत्न निर्धारित करती हैं, जबकि वैदिक ज्योतिष संपूर्ण जन्म कुंडली के विस्तृत विश्लेषण के आधार पर रत्न की सिफारिश करता है।`, ja: `Compared with Western Astrology, the use of gemstones in Jyotish is far more personalised.西洋のシステムでは通常、個人の太陽星座に基づいて誕生石を割り当てますが、ヴェーダ占星術では出生図全体の詳細な分析に基づいて宝石を推奨します。`, ko: `서양 점성술과 비교할 때 Jyotish의 보석 사용은 훨씬 더 개인화되어 있습니다. 서양 시스템은 일반적으로 개인의 태양 별자리를 기반으로 탄생석을 할당하는 반면, 베다 점성술은 전체 출생 차트의 상세한 분석을 기반으로 보석을 추천합니다.`,} },
      { type: "heading", level: 3, text: { en: `Semi-Precious Gemstone Equivalents`, hi: `अर्ध-कीमती रत्न समकक्ष`, ja: `半貴石相当品`, ko: `준보석 원석 등가물`,} },
      { type: "paragraph", text: { en: `If a high-quality precious gemstone is beyond our budget, certain semi-precious alternatives may be used. However, the general understanding is that they do not offer the same level of benefit or protection as the traditional precious stones.`, hi: `यदि उच्च गुणवत्ता वाला कीमती रत्न हमारे बजट से बाहर है, तो कुछ अर्ध-कीमती विकल्पों का उपयोग किया जा सकता है। हालाँकि, सामान्य समझ यह है कि वे पारंपरिक कीमती पत्थरों के समान लाभ या सुरक्षा प्रदान नहीं करते हैं।`, ja: `高品質の貴石が予算を超える場合は、特定の半貴石の代替品が使用される場合があります。しかし、一般的には、従来の宝石と同じレベルの利益や保護は提供されないということが理解されています。`, ko: `고품질의 귀중한 보석이 예산을 초과하는 경우 특정 준보석 대안이 사용될 수 있습니다. 그러나 일반적인 이해는 전통적인 보석과 동일한 수준의 혜택이나 보호를 제공하지 않는다는 것입니다.`,} },
      { type: "paragraph", text: { en: `In India, the following alternatives are commonly used:`, hi: `भारत में, निम्नलिखित विकल्प आमतौर पर उपयोग किए जाते हैं:`, ja: `インドでは、次の代替手段が一般的に使用されます。`, ko: `인도에서는 다음과 같은 대안이 일반적으로 사용됩니다.`,} },
      { type: "paragraph", text: { en: `• Red Spinel for the Sun`, hi: `• सूर्य के लिए लाल स्पिनल`, ja: `• 太陽のレッドスピネル`, ko: `• 태양을 위한 레드 스피넬`,} },
      { type: "paragraph", text: { en: `• Green Tourmaline for Mercury`, hi: `• बुध के लिए हरा टूमलाइन`, ja: `• 水星のグリーントルマリン`, ko: `• 수성용 녹색 전기석`,} },
      { type: "paragraph", text: { en: `• Yellow Topaz (preferred) or Yellow Citrine for Jupiter`, hi: `• बृहस्पति के लिए पीला पुखराज (पसंदीदा) या पीला सिट्रीन`, ja: `• 木星にはイエロー トパーズ (推奨) またはイエロー シトリン`, ko: `• 목성의 경우 노란색 토파즈(선호) 또는 노란색 황수정`,} },
      { type: "paragraph", text: { en: `• White Sapphire or Phenakite for Venus`, hi: `• शुक्र के लिए सफेद नीलम या फेनाकाइट`, ja: `• 金星の場合はホワイトサファイアまたはフェナカイト`, ko: `• 금성을 위한 화이트 사파이어 또는 페나카이트`,} },
      { type: "paragraph", text: { en: `• Blue Spinel for Saturn`, hi: `• शनि के लिए नीला स्पिनल`, ja: `• 土星のブルースピネル`, ko: `• 토성을 위한 블루 스피넬`,} },
      { type: "heading", level: 3, text: { en: `Wearing Gemstones Based on our Ascendant`, hi: `अपने लग्न के आधार पर रत्न धारण करें`, ja: `アセンダントに基づいた宝石を身につける`, ko: `우리의 승천자를 기반으로 한 보석 착용`,} },
      { type: "paragraph", text: { en: `If we know our Ascendant, or rising sign in the Sidereal Zodiac, we can safely wear the gemstone associated with the planet ruling that sign. This is considered a universally beneficial remedy and is something almost everyone can do to receive positive results.`, hi: `यदि हमें अपना लग्न, या नक्षत्रीय राशि में उदीयमान राशि पता है, तो हम उस राशि पर शासन करने वाले ग्रह से संबंधित रत्न सुरक्षित रूप से पहन सकते हैं। यह एक सार्वभौमिक लाभकारी उपाय माना जाता है और सकारात्मक परिणाम प्राप्त करने के लिए इसे लगभग हर कोई कर सकता है।`, ja: `自分のアセンダント、つまり恒星黄道帯の上昇星座を知っていれば、その星座を支配する惑星に関連付けられた宝石を安全に身につけることができます。これは普遍的に有益な治療法と考えられており、ほぼすべての人がポジティブな結果を得るために実行できることです。`, ko: `우리가 항성 황도대의 어센던트 또는 상승 별자리를 안다면, 우리는 그 별자리를 지배하는 행성과 관련된 보석을 안전하게 착용할 수 있습니다. 이는 보편적으로 유익한 치료법으로 간주되며 긍정적인 결과를 얻기 위해 거의 모든 사람이 할 수 있는 일입니다.`,} },
      eduImage(educationImages.signRulership, {
        en: "Planetary rulership of the twelve zodiac signs",
        hi: "बारह राशियों पर ग्रहों का शासन",
        ja: "十二星座に対する惑星の支配権",
        ko: "열두 별자리에 대한 행성의 지배권",
      }),
      { type: "paragraph", text: { en: `By strengthening the Ascendant Lord—the planet ruling the Ascendant—we also strengthen the overall chart. This can provide some assistance in mitigating difficulties shown elsewhere in the horoscope, although not to the same extent as remedies specifically targeted toward individual planetary issues.`, hi: `लग्न स्वामी को मजबूत करके - लग्न पर शासन करने वाला ग्रह - हम समग्र चार्ट को भी मजबूत करते हैं। यह कुंडली में अन्यत्र दर्शाई गई कठिनाइयों को कम करने में कुछ सहायता प्रदान कर सकता है, हालाँकि उस हद तक नहीं जितना कि विशेष रूप से व्यक्तिगत ग्रह संबंधी समस्याओं के लिए लक्षित उपाय।`, ja: `アセンダントロード（アセンダントを支配する惑星）を強化することで、チャート全体も強化します。これは、個々の惑星の問題を特に対象とした治療法と同程度ではありませんが、星占いの他の場所で示されている困難を軽減するのにある程度の助けとなります。`, ko: `승천자를 지배하는 행성인 승천 군주를 강화함으로써 우리는 전체 차트도 강화합니다. 이는 별점의 다른 부분에 표시된 어려움을 완화하는 데 어느 정도 도움이 될 수 있지만, 개별 행성 문제를 특별히 겨냥한 구제책과 같은 정도는 아닙니다.`,} },
      { type: "paragraph", text: { en: `Strengthening the Ascendant Lord generally produces positive effects. Some astrologers note a possible exception for Scorpio Ascendants because Mars rules both the first and sixth houses.`, hi: `लग्नेश को मजबूत करना आम तौर पर सकारात्मक प्रभाव पैदा करता है। कुछ ज्योतिषी वृश्चिक लग्न के लिए एक संभावित अपवाद मानते हैं क्योंकि मंगल पहले और छठे दोनों घरों पर शासन करता है।`, ja: `アセンダントロードを強化すると、一般にプラスの効果が得られます。一部の占星術師は、火星が第 1 室と第 6 室の両方を支配しているため、蠍座のアセンダントについては例外の可能性があると指摘しています。`, ko: `승천 군주를 강화하는 것은 일반적으로 긍정적인 효과를 가져옵니다. 일부 점성가들은 화성이 첫 번째 하우스와 여섯 번째 하우스를 모두 지배하기 때문에 전갈자리 승천자에 대해 예외가 있을 수 있다고 지적합니다.`,} },
      { type: "paragraph", text: { en: `If we already possess a Western-style birth chart based on the Tropical Zodiac, conversion to the Sidereal Zodiac can be achieved by subtracting the relevant Ayanamsha for the birth date [4]. Once this is done, the appropriate gemstone can be selected.`, hi: `यदि हमारे पास पहले से ही उष्णकटिबंधीय राशि चक्र पर आधारित पश्चिमी शैली की जन्म कुंडली है, तो जन्म तिथि के लिए प्रासंगिक अयनांश को घटाकर नाक्षत्र राशि चक्र में रूपांतरण प्राप्त किया जा सकता है [4]। एक बार यह हो जाने पर, उपयुक्त रत्न का चयन किया जा सकता है।`, ja: `熱帯黄道帯に基づいた西洋式出生図をすでに所有している場合は、生年月日から関連するアヤナムシャを減算することで恒星黄道帯への変換を達成できます [4]。これが完了すると、適切な宝石を選択できます。`, ko: `우리가 이미 열대 황도대를 기반으로 한 서양식 출생 차트를 보유하고 있는 경우, 생년월일에 해당하는 아야남샤를 빼면 항성 황도대로의 전환이 이루어질 수 있습니다[4]. 이 작업이 완료되면 적절한 보석을 선택할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Alternatively, various online tools based upon the Sidereal Zodiac can provide gemstone recommendations. Accurate birth times are essential for reliable results. If uncertainty exists regarding birth time, it is wise to compare multiple reports or consult an experienced Vedic Astrologer.`, hi: `वैकल्पिक रूप से, नाक्षत्र राशि चक्र पर आधारित विभिन्न ऑनलाइन उपकरण रत्न संबंधी सिफारिशें प्रदान कर सकते हैं। विश्वसनीय परिणामों के लिए सटीक जन्म समय आवश्यक है। यदि जन्म समय के संबंध में अनिश्चितता मौजूद है, तो कई रिपोर्टों की तुलना करना या किसी अनुभवी वैदिक ज्योतिषी से परामर्श करना बुद्धिमानी है।`, ja: `あるいは、恒星黄道帯に基づいたさまざまなオンライン ツールで、推奨宝石を提供することもできます。信頼性の高い結果を得るには、正確な出生時刻が不可欠です。出生時刻に関して不確実性がある場合は、複数のレポートを比較するか、経験豊富なヴェーダ占星術師に相談することが賢明です。`, ko: `또는 Sidereal Zodiac을 기반으로 하는 다양한 온라인 도구를 통해 보석 추천을 받을 수 있습니다. 신뢰할 수 있는 결과를 얻으려면 정확한 출생 시간이 필수적입니다. 출생 시간과 관련하여 불확실한 경우 여러 보고서를 비교하거나 숙련된 베다 점성가에게 문의하는 것이 현명합니다.`,} },
    ],
  },
  {
    id: "mantras",
    section: "remedies",
    title: { en: `Chanting Planetary Related Mantras to Remove Negative Karma`, hi: `नकारात्मक कर्मों को दूर करने के लिए ग्रह संबंधी मंत्रों का जाप करें`, ja: `惑星関連のマントラを唱えてネガティブなカルマを取り除く`, ko: `부정적인 카르마를 제거하기 위해 행성 관련 진언을 외우기`,},
    related: ["gemstones","vedic-rituals","charity"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Chanting Planetary Related Mantras to Remove Negative Karma`, hi: `नकारात्मक कर्मों को दूर करने के लिए ग्रह संबंधी मंत्रों का जाप करें`, ja: `惑星関連のマントラを唱えてネガティブなカルマを取り除く`, ko: `부정적인 카르마를 제거하기 위해 행성 관련 진언을 외우기`,} },
      { type: "paragraph", text: { en: `While gemstones can strengthen auspicious planets, wearing the gemstone associated with a functional malefic planet may actually increase difficulties. In such cases, chanting planetary mantras is often the preferred remedy.`, hi: `जबकि रत्न शुभ ग्रहों को मजबूत कर सकते हैं, किसी क्रियाशील अशुभ ग्रह से संबंधित रत्न पहनने से वास्तव में कठिनाइयां बढ़ सकती हैं। ऐसे मामलों में, ग्रह मंत्रों का जाप अक्सर पसंदीदा उपाय होता है।`, ja: `宝石は縁起の良い惑星を強化することができますが、機能的な凶星に関連付けられた宝石を身に着けると、実際には困難が増す可能性があります。そのような場合、惑星のマントラを唱えることが多くの場合好まれる治療法となります。`, ko: `보석은 상서로운 행성을 강화할 수 있지만, 기능적인 흉성 행성과 관련된 보석을 착용하면 실제로 어려움이 증가할 수 있습니다. 그러한 경우에는 행성 만트라를 외치는 것이 종종 선호되는 치료법입니다.`,} },
      { type: "paragraph", text: { en: `Mantras are traditionally recited in Sanskrit and are said to "upwardly manage" the forces of nature, or Devas. Specific mantras can be used to harmonise negative planetary influences. In a sense, mantras act like passwords that connect us to higher levels of consciousness and facilitate transcendence.`, hi: `मंत्रों को पारंपरिक रूप से संस्कृत में पढ़ा जाता है और कहा जाता है कि वे प्रकृति या देवों की शक्तियों को "ऊर्ध्वमुखी प्रबंधन" करते हैं। नकारात्मक ग्रहों के प्रभावों को संतुलित करने के लिए विशिष्ट मंत्रों का उपयोग किया जा सकता है। एक अर्थ में, मंत्र पासवर्ड की तरह काम करते हैं जो हमें चेतना के उच्च स्तर से जोड़ते हैं और गोचर की सुविधा प्रदान करते हैं।`, ja: `マントラは伝統的にサンスクリット語で唱えられ、自然の力、つまりデーヴァを「上向きに管理する」と言われています。特定のマントラを使用して、惑星のマイナスの影響を調和させることができます。ある意味、マントラは私たちをより高い意識レベルに結びつけ、超越を促進するパスワードのような役割を果たします。`, ko: `만트라는 전통적으로 산스크리트어로 낭송되며 자연의 힘, 즉 데바(Devas)를 "위로 관리"한다고 합니다. 특정 만트라를 사용하여 부정적인 행성 영향을 조화시킬 수 있습니다. 어떤 의미에서 만트라는 우리를 더 높은 의식 수준으로 연결하고 초월을 촉진하는 암호와 같은 역할을 합니다.`,} },
      { type: "paragraph", text: { en: `A Jyotish Astrologer can identify problematic planets in a birth chart and recommend suitable mantras to reduce their negative effects.`, hi: `एक ज्योतिषी जन्म कुंडली में समस्याग्रस्त ग्रहों की पहचान कर सकता है और उनके नकारात्मक प्रभावों को कम करने के लिए उपयुक्त मंत्रों की सिफारिश कर सकता है।`, ja: `ジョーティッシュ師は、出生図で問題のある惑星を特定し、その悪影響を軽減するために適切なマントラを推奨します。`, ko: `Jyotish 점성가는 출생 차트에서 문제가 있는 행성을 식별하고 부정적인 영향을 줄이기 위해 적합한 만트라를 추천할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `At their simplest, planetary mantras generally follow the pattern:`, hi: `अपने सरलतम रूप में, ग्रह मंत्र आम तौर पर पैटर्न का पालन करते हैं:`, ja: `最も単純な惑星のマントラは、一般に次のパターンに従います。`, ko: `가장 단순한 행성 만트라는 일반적으로 다음 패턴을 따릅니다.`,} },
      { type: "paragraph", text: { en: `"Om – [Planet's Sanskrit Name] – Namaha"`, hi: `"ओम - [ग्रह का संस्कृत नाम] - नमः"`, ja: `「オーム – [惑星のサンスクリット名] – ナマハ」`, ko: `"옴 – [행성의 산스크리트어 이름] – 나마하"`,} },
      { type: "paragraph", text: { en: `These are commonly repeated 108 times daily using a mala or rosary. The number 108 is derived from the nine planets multiplied by the twelve zodiac signs (9 × 12 = 108).`, hi: `इन्हें आमतौर पर माला या माला का उपयोग करके प्रतिदिन 108 बार दोहराया जाता है। संख्या 108 नौ ग्रहों को बारह राशियों से गुणा करने पर प्राप्त होती है (9 × 12 = 108)।`, ja: `これらは通常、数珠やロザリオを使用して毎日 108 回繰り返されます。 108 という数字は、9 つ​​の惑星と 12 の星座を掛け合わせたものです (9 × 12 = 108)。`, ko: `이것은 일반적으로 말라나 묵주를 사용하여 매일 108번 반복됩니다. 숫자 108은 9개의 행성에 12개의 황도대 별자리를 곱한 것(9 × 12 = 108)에서 파생됩니다.`,} },
      { type: "paragraph", text: { en: `For example, the mantra for Venus is:`, hi: `उदाहरण के लिए, शुक्र का मंत्र है:`, ja: `たとえば、金星のマントラは次のとおりです。`, ko: `예를 들어 금성의 주문은 다음과 같습니다.`,} },
      { type: "paragraph", text: { en: `"Om Shukraya Namaha"`, hi: `"ओम शुक्राय नमः"`, ja: `「オーム・シュクラヤ・ナマハ」`, ko: `"옴 슈크라야 나마하"`,} },
      { type: "heading", level: 3, text: { en: `Basic Planetary Mantras to Chant`, hi: `जपने योग्य मूल ग्रह मंत्र`, ja: `唱えるべき基本的な惑星マントラ`, ko: `노래하는 기본 행성 만트라`,} },
      { type: "paragraph", text: { en: `• Sun: Om Suryaya Namaha`, hi: `• सूर्य: ॐ सूर्याय नमः`, ja: `• 日曜日: オーム スーリヤヤ ナマハ`, ko: `• 일요일: 옴 수리야 나마하`,} },
      { type: "paragraph", text: { en: `• Moon: Om Somaya Namaha`, hi: `• चन्द्रमा: ॐ सोमाय नमः`, ja: `• 月: オーム ソマヤ ナマハ`, ko: `• 달: 옴 소마야 나마하`,} },
      { type: "paragraph", text: { en: `• Mars: Om Mangalaya Namaha`, hi: `• मंगल: ॐ मंगलाय नमः`, ja: `• 火星：オーム マンガラヤ ナマハ`, ko: `• 화성: Om Mangalaya Namaha`,} },
      { type: "paragraph", text: { en: `• Mercury: Om Budhaya Namaha`, hi: `• बुध: ॐ बुधाय नमः`, ja: `• 水星：オーム・ブダヤ・ナマハ`, ko: `• 머큐리: 옴 부다야 나마하`,} },
      { type: "paragraph", text: { en: `• Jupiter: Om Brihaspataye Namaha`, hi: `• बृहस्पति: ॐ बृं बृहस्पतये नमः`, ja: `• 木星：オーム・ブリハスパタエ・ナマハ`, ko: `• 목성: Om Brihaspataye Namaha`,} },
      { type: "paragraph", text: { en: `• Venus: Om Shukraya Namaha`, hi: `• शुक्र: ॐ शुक्राय नमः`, ja: `• 金星：オーム・シュクラヤ・ナマハ`, ko: `• 비너스: 옴 슈크라야 나마하`,} },
      { type: "paragraph", text: { en: `• Saturn: Om Shanaye Namaha`, hi: `• शनि: ॐ शनाय नमः`, ja: `• 土星：オーム・シャナイ・ナマハ`, ko: `• 토성: 옴 샤나예 나마하`,} },
      { type: "paragraph", text: { en: `• Rahu: Om Rahave Namaha`, hi: `• राहुः ॐ राहवे नमः`, ja: `• ラーフ：オーム・ラハベ・ナマハ`, ko: `• 라후: 옴 라하비 나마하`,} },
      { type: "paragraph", text: { en: `• Ketu: Om Ketave Namaha`, hi: `• केतु: ॐ केतवे नमः`, ja: `• ケトゥ: オム・ケタベ・ナマハ`, ko: `• 케투: 옴 케타브 나마하`,} },
      { type: "paragraph", text: { en: `Because correct pronunciation is important, it is advisable to learn from a reputable source.`, hi: `चूँकि सही उच्चारण महत्वपूर्ण है, इसलिए किसी प्रतिष्ठित स्रोत से सीखना उचित है।`, ja: `正しい発音は重要なので、信頼できる情報源から学ぶことをお勧めします。`, ko: `정확한 발음이 중요하기 때문에 평판이 좋은 곳에서 배우는 것이 좋습니다.`,} },
      { type: "paragraph", text: { en: `A Jyotish Astrologer may further refine the remedy by identifying the periods during which a planet's influence is strongest—particularly during its Maha Dasha—and recommending chanting during that specific timeframe.`, hi: `एक ज्योतिषी उस अवधि की पहचान करके उपाय को और अधिक परिष्कृत कर सकता है जिसके दौरान किसी ग्रह का प्रभाव सबसे मजबूत होता है - विशेष रूप से उसकी महादशा के दौरान - और उस विशिष्ट समय सीमा के दौरान जप की सिफारिश कर सकता है।`, ja: `ジョーティッシュ師は、惑星の影響が最も強い期間、特にマハ・ダシャーの期間を特定し、その特定の期間に詠唱することを推奨することで、この治療法をさらに改良する可能性があります。`, ko: `Jyotish 점성가는 행성의 영향력이 가장 강한 기간, 특히 Maha Dasha 기간을 식별하고 해당 특정 기간 동안 노래를 추천함으로써 치료법을 더욱 구체화할 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `Mantra for Harmony Between the Nine Planets`, hi: `नौ ग्रहों के बीच सामंजस्य के लिए मंत्र`, ja: `9つの惑星間の調和のためのマントラ`, ko: `9개 행성의 조화를 위한 만트라`,} },
      { type: "paragraph", text: { en: `Another option is the powerful Nav Graha mantra, which seeks to harmonise the energies of all nine planets simultaneously:`, hi: `दूसरा विकल्प शक्तिशाली नव ग्रह मंत्र है, जो एक साथ सभी नौ ग्रहों की ऊर्जाओं में सामंजस्य बिठाने का प्रयास करता है:`, ja: `もう 1 つのオプションは、9 つ​​の惑星すべてのエネルギーを同時に調和させようとする強力なナヴ グラハ マントラです。`, ko: `또 다른 옵션은 9개 행성의 에너지를 동시에 조화시키려는 강력한 Nav Graha 만트라입니다.`,} },
      { type: "paragraph", text: { en: `adityaaya cha somaaya mangalaaya budhaaya cha |`, hi: `आदित्याय च सोमाय मंगलाय बुधाय च |`, ja: `アディティヤヤ チャ ソマーヤ マンガラヤ ブダヤヤ チャ |`, ko: `adityaaya 차 somaaya mangalaaya budhaaya 차 |`,} },
      { type: "paragraph", text: { en: `guru shukra shanibhyash cha raahave ketave namaha ||`, hi: `गुरु शुक्र शनिभ्यश च राहवे केतवे नमः ||`, ja: `グル シュクラ シャニビヤシュ チャ ラーハベ ケタブ ナマハ ||`, ko: `전문가 shukra shanibhyash cha raahave ketave namaha ||`,} },
      { type: "paragraph", text: { en: `This mantra is relatively easy to learn through regular repetition.`, hi: `नियमित दोहराव के माध्यम से यह मंत्र सीखना अपेक्षाकृत आसान है।`, ja: `このマントラは定期的に繰り返すことで比較的簡単に習得できます。`, ko: `이 만트라는 정기적인 반복을 통해 비교적 쉽게 배울 수 있습니다.`,} },
      { type: "heading", level: 3, text: { en: `General Mantras for Removing Negativity and Suffering`, hi: `नकारात्मकता और दुख दूर करने के सामान्य मंत्र`, ja: `否定性と苦しみを取り除くための一般的なマントラ`, ko: `부정성과 고통을 제거하기 위한 일반적인 진언`,} },
      { type: "paragraph", text: { en: `A widely recommended mantra is:`, hi: `एक व्यापक रूप से अनुशंसित मंत्र है:`, ja: `広く推奨されるマントラは次のとおりです。`, ko: `널리 권장되는 만트라는 다음과 같습니다.`,} },
      { type: "paragraph", text: { en: `"Auṁ Namaḥ Śivāya" (Om Namah Shivaya)`, hi: `"ऊँ नमः शिवाय" (ओम नमः शिवाय)`, ja: `「Auṁ Namaḥ Śivāya」（オーム ナマ シヴァーヤ）`, ko: `"Auṁ Namaḥ Śivāya"(옴 나마 시바야)`,} },
      { type: "paragraph", text: { en: `This simple yet powerful mantra is traditionally believed to remove negativity and suffering.`, hi: `यह सरल लेकिन शक्तिशाली मंत्र पारंपरिक रूप से नकारात्मकता और पीड़ा को दूर करने वाला माना जाता है।`, ja: `このシンプルだが強力なマントラは、伝統的に否定性と苦しみを取り除くと信じられています。`, ko: `이 간단하면서도 강력한 만트라는 전통적으로 부정적인 생각과 고통을 제거한다고 믿어졌습니다.`,} },
      { type: "paragraph", text: { en: `An even more powerful option is the Maha Mrityunjaya Mantra, although it requires greater effort to learn correctly.`, hi: `एक और भी अधिक शक्तिशाली विकल्प महा मृत्युंजय मंत्र है, हालाँकि इसे सही ढंग से सीखने के लिए अधिक प्रयास की आवश्यकता होती है।`, ja: `さらに強力なオプションはマハ ムリティウンジャヤ マントラですが、正しく学ぶには多大な努力が必要です。`, ko: `훨씬 더 강력한 옵션은 Maha Mrityunjaya Mantra이지만 올바르게 배우려면 더 많은 노력이 필요합니다.`,} },
      { type: "paragraph", text: { en: `Why are these mantras considered so effective? It is often said that "Shiva sits above all the planets" [5]. In essence, this means that Shiva Tattva—Shiva Consciousness—has the power to transcend and override the planetary influences shown in a birth chart. Chanting Shiva mantras helps enliven this higher consciousness within our awareness [6].`, hi: `ये मंत्र इतने प्रभावशाली क्यों माने जाते हैं? अक्सर कहा जाता है कि "शिव सभी ग्रहों के ऊपर विराजमान हैं" [5]। संक्षेप में, इसका मतलब यह है कि शिव तत्व - शिव चेतना - में जन्म कुंडली में दिखाए गए ग्रहों के प्रभाव को पार करने और खत्म करने की शक्ति है। शिव मंत्रों का जाप हमारी जागरूकता के भीतर इस उच्च चेतना को जागृत करने में मदद करता है [6]।`, ja: `なぜこれらのマントラは非常に効果的だと考えられているのでしょうか？ 「シヴァはすべての惑星の上に座している」とよく言われます [5]。本質的に、これは、シヴァ タットヴァ、つまりシヴァ意識が、出生図に示されている惑星の影響を超越して無効にする力を持っていることを意味します。シヴァのマントラを唱えることは、私たちの意識の中でこの高次の意識を活性化するのに役立ちます[6]。`, ko: `이 만트라가 왜 그렇게 효과적인 것으로 간주됩니까? 종종 "시바는 모든 행성 위에 앉아 있다"고 말합니다 [5]. 본질적으로 이것은 Shiva Tattva, 즉 Shiva Consciousness가 출생 차트에 표시된 행성의 영향을 초월하고 무시할 수 있는 힘을 가지고 있음을 의미합니다. Shiva 만트라를 외우는 것은 우리의 인식 내에서 이러한 더 높은 의식을 활성화하는 데 도움이 됩니다[6].`,} },
    ],
  },
  {
    id: "charity",
    section: "remedies",
    title: { en: `Acts of Charity to Balance Planetary Energies`, hi: `ग्रहों की ऊर्जा को संतुलित करने के लिए दान के कार्य`, ja: `惑星のエネルギーのバランスをとるための慈善活動`, ko: `지구 에너지의 균형을 위한 자선 활동`,},
    related: ["planetary-antidotes","vedic-rituals","jyotish-and-karma"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Acts of Charity to Balance Planetary Energies`, hi: `ग्रहों की ऊर्जा को संतुलित करने के लिए दान के कार्य`, ja: `惑星のエネルギーのバランスをとるための慈善活動`, ko: `지구 에너지의 균형을 위한 자선 활동`,} },
      { type: "paragraph", text: { en: `Because the Vedic tradition sees all existence as interconnected, specific acts of charity are believed to reduce karmas associated with particular planets.`, hi: `चूँकि वैदिक परंपरा समस्त अस्तित्व को एक दूसरे से जुड़े हुए के रूप में देखती है, ऐसा माना जाता है कि दान के विशिष्ट कार्य विशेष ग्रहों से जुड़े कर्मों को कम करते हैं।`, ja: `ヴェーダの伝統ではすべての存在は相互につながっていると考えられているため、特定の慈善行為は特定の惑星に関連するカルマを軽減すると信じられています。`, ko: `베다 전통에서는 모든 존재가 서로 연결되어 있다고 보기 때문에 특정 자선 행위는 특정 행성과 관련된 카르마를 감소시키는 것으로 믿어집니다.`,} },
      { type: "paragraph", text: { en: `Even if one views these ideas symbolically, giving a portion of one's income to worthwhile causes remains beneficial. A living enlightened Vedic Saint encourages everyone to donate a small percentage of their income, explaining that doing so may reduce the likelihood of disputes, legal difficulties, and related challenges.`, hi: `भले ही कोई इन विचारों को प्रतीकात्मक रूप से देखे, अपनी आय का एक हिस्सा सार्थक कार्यों के लिए देना फायदेमंद रहता है। एक जीवित प्रबुद्ध वैदिक संत हर किसी को अपनी आय का एक छोटा प्रतिशत दान करने के लिए प्रोत्साहित करते हैं, यह समझाते हुए कि ऐसा करने से विवादों, कानूनी कठिनाइयों और संबंधित चुनौतियों की संभावना कम हो सकती है।`, ja: `たとえこれらの考えを象徴的に捉えていたとしても、収入の一部を価値ある活動に寄付することは有益であることに変わりはありません。生きている啓発されたヴェーダの聖者は、収入のわずかな割合を寄付することをすべての人に奨励し、そうすることで紛争、法的問題、および関連する問題の可能性が減る可能性があると説明しています。`, ko: `이러한 사상을 상징적으로 본다 하더라도, 소득의 일부를 가치 있는 일에 기부하는 것은 여전히 ​​유익합니다. 깨달은 살아있는 베다 성자는 모든 사람이 소득의 적은 부분을 기부하도록 권장하며 그렇게 하면 분쟁, 법적 어려움 및 관련 문제의 가능성을 줄일 수 있다고 설명합니다.`,} },
      { type: "paragraph", text: { en: `Some remedies are surprisingly simple. For example, feeding crows on a Saturday is traditionally believed to alleviate certain karmic burdens connected with Saturn.`, hi: `कुछ उपाय आश्चर्यजनक रूप से सरल हैं। उदाहरण के लिए, पारंपरिक रूप से माना जाता है कि शनिवार को कौवों को खाना खिलाने से शनि से जुड़े कुछ कर्म संबंधी बोझ कम हो जाते हैं।`, ja: `いくつかの治療法は驚くほど簡単です。たとえば、土曜日にカラスに餌をあげると、土星に関係する特定のカルマの重荷が軽減されると伝統的に信じられています。`, ko: `일부 치료법은 놀라울 정도로 간단합니다. 예를 들어, 토요일에 까마귀에게 먹이를 주는 것은 전통적으로 토성과 관련된 특정 카르마 부담을 완화하는 것으로 믿어집니다.`,} },
      { type: "paragraph", text: { en: `Since different planets are linked to specific days of the week, charitable acts are often performed on the day associated with the relevant planet.`, hi: `चूँकि विभिन्न ग्रह सप्ताह के विशिष्ट दिनों से जुड़े होते हैं, इसलिए धर्मार्थ कार्य अक्सर संबंधित ग्रह से जुड़े दिन पर किए जाते हैं।`, ja: `さまざまな惑星が特定の曜日に関連付けられているため、慈善活動は関連する惑星に関連付けられた日に行われることがよくあります。`, ko: `여러 행성이 특정 요일과 연결되어 있기 때문에 해당 행성과 관련된 날에 자선 활동이 수행되는 경우가 많습니다.`,} },
      { type: "paragraph", text: { en: `Although some may regard these practices as superstitious, they have endured across generations. Modern scientific interest in interconnected systems provides additional support for concepts long recognised by the ancient Vedic sages.`, hi: `हालाँकि कुछ लोग इन प्रथाओं को अंधविश्वासी मान सकते हैं, लेकिन ये पीढ़ियों से चली आ रही हैं। परस्पर जुड़ी प्रणालियों में आधुनिक वैज्ञानिक रुचि प्राचीन वैदिक ऋषियों द्वारा लंबे समय से मान्यता प्राप्त अवधारणाओं के लिए अतिरिक्त समर्थन प्रदान करती है।`, ja: `これらの習慣は迷信だと考える人もいるかもしれませんが、世代を超えて受け継がれてきました。相互接続されたシステムに対する現代の科学的関心は、古代ヴェーダの賢人によって長年認識されてきた概念をさらに裏付けるものとなっています。`, ko: `어떤 사람들은 이러한 관습을 미신이라고 생각할 수도 있지만, 이러한 관습은 여러 세대에 걸쳐 지속되어 왔습니다. 상호 연결된 시스템에 대한 현대 과학적 관심은 고대 베다 현자들이 오랫동안 인정한 개념에 대한 추가적인 지원을 제공합니다.`,} },
    ],
  },
  {
    id: "vedic-rituals",
    section: "remedies",
    title: { en: `Conducting Vedic Rituals to Remove Negativity`, hi: `नकारात्मकता को दूर करने के लिए वैदिक अनुष्ठानों का आयोजन`, ja: `否定的なものを取り除くためのヴェーダ儀式の実施`, ko: `부정성을 제거하기 위해 베다 의식 수행하기`,},
    related: ["mantras","charity","planetary-antidotes"],
    blocks: [
      { type: "heading", level: 2, text: { en: `Conducting Vedic Rituals to Remove Negativity`, hi: `नकारात्मकता को दूर करने के लिए वैदिक अनुष्ठानों का आयोजन`, ja: `否定的なものを取り除くためのヴェーダ儀式の実施`, ko: `부정성을 제거하기 위해 베다 의식 수행하기`,} },
      eduImage(educationImages.vedicRituals, {
        en: "Conducting Vedic rituals to remove negativity", hi: "नकारात्मकता को दूर करने के लिए वैदिक अनुष्ठानों का आयोजन", ja: "否定的なエネルギーを取り除くヴェーダ儀式", ko: "부정적인 생각을 제거하기 위해 베다 의식을 수행합니다.",
      }),
      { type: "paragraph", text: { en: `Since ancient times, Vedic rituals have been used to harmonise and manage the forces of nature. Traditional ceremonies known as Yagnas, Yajnas, or Yagyas were believed to bring timely rainfall, healthy crops, and prosperity.`, hi: `प्राचीन काल से, वैदिक अनुष्ठानों का उपयोग प्रकृति की शक्तियों में सामंजस्य और प्रबंधन के लिए किया जाता रहा है। माना जाता है कि पारंपरिक समारोह जिन्हें यज्ञ, यज्ञ या यज्ञ के नाम से जाना जाता है, समय पर वर्षा, स्वस्थ फसल और समृद्धि लाते हैं।`, ja: `古代以来、ヴェーダの儀式は自然の力を調和させ、管理するために使用されてきました。ヤグナス、ヤグナ、またはヤギャとして知られる伝統的な儀式は、適時の降雨、健全な作物、繁栄をもたらすと信じられていました。`, ko: `고대부터 베다 의식은 자연의 힘을 조화시키고 관리하는 데 사용되어 왔습니다. Yagnas, Yajnas 또는 Yagyas로 알려진 전통 의식은 시기적절한 비, 건강한 농작물 및 번영을 가져오는 것으로 믿어졌습니다.`,} },
      { type: "paragraph", text: { en: `In a similar way, difficulties caused by imbalanced planetary energies in a birth chart can be addressed through these sacred rituals.`, hi: `इसी तरह, जन्म कुंडली में असंतुलित ग्रह ऊर्जा के कारण होने वाली कठिनाइयों को इन पवित्र अनुष्ठानों के माध्यम से संबोधित किया जा सकता है।`, ja: `同様に、出生図における惑星エネルギーの不均衡によって引き起こされる困難も、これらの神聖な儀式を通じて対処することができます。`, ko: `비슷한 방식으로, 출생 차트에서 행성 에너지의 불균형으로 인한 어려움은 이러한 신성한 의식을 통해 해결될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `Some may interpret these ceremonies as "planet worship," but their purpose is much more subtle and profound. They may be better understood as a form of karmic engineering designed to modify returning karmas and reduce suffering.`, hi: `कुछ लोग इन समारोहों की व्याख्या "ग्रह पूजा" के रूप में कर सकते हैं, लेकिन उनका उद्देश्य कहीं अधिक सूक्ष्म और गहरा है। उन्हें कार्मिक इंजीनियरिंग के एक रूप के रूप में बेहतर ढंग से समझा जा सकता है जो रिटर्निंग कर्मों को संशोधित करने और पीड़ा को कम करने के लिए डिज़ाइन किया गया है।`, ja: `これらの儀式を「惑星崇拝」と解釈する人もいるかもしれませんが、その目的はもっと微妙で奥深いものです。それらは、戻ってくるカルマを修正し、苦しみを軽減するために設計されたカルマ工学の一形態としてよりよく理解されるかもしれません。`, ko: `어떤 사람들은 이러한 의식을 "행성 숭배"로 해석할 수도 있지만, 그 목적은 훨씬 더 미묘하고 심오합니다. 그것은 되돌아오는 카르마를 수정하고 고통을 줄이기 위해 고안된 카르마 공학의 한 형태로 더 잘 이해될 수 있습니다.`,} },
      { type: "paragraph", text: { en: `The procedures for conducting these rituals were traditionally regarded as Divine knowledge given for the benefit of humanity.`, hi: `इन अनुष्ठानों के संचालन की प्रक्रियाओं को पारंपरिक रूप से मानवता के लाभ के लिए दिया गया दिव्य ज्ञान माना जाता था।`, ja: `これらの儀式を行う手順は伝統的に、人類の利益のために与えられた神の知識とみなされてきました。`, ko: `이러한 의식을 수행하는 절차는 전통적으로 인류의 이익을 위해 주어진 신성한 지식으로 간주되었습니다.`,} },
      { type: "paragraph", text: { en: `When performed correctly, with the appropriate Vedic mantras and procedures, these ceremonies bring Graha Shanti—peace from the planets. They are ideally performed by highly trained pundits with elevated levels of consciousness.`, hi: `जब उचित वैदिक मंत्रों और प्रक्रियाओं के साथ सही ढंग से प्रदर्शन किया जाता है, तो ये समारोह ग्रह शांति लाते हैं - ग्रहों से शांति। इन्हें आदर्श रूप से चेतना के ऊंचे स्तर वाले उच्च प्रशिक्षित पंडितों द्वारा किया जाता है।`, ja: `適切なヴェーダのマントラと手順に従って正しく行われた場合、これらの儀式はグラハ シャンティ、つまり惑星からの平和をもたらします。これらは、意識レベルを高めた、高度に訓練された専門家によって実行されるのが理想的です。`, ko: `적절한 베다 만트라와 절차를 사용하여 올바르게 수행되면 이러한 의식은 Graha Shanti, 즉 행성의 평화를 가져옵니다. 이는 높은 수준의 의식을 지닌 고도로 훈련된 전문가에 의해 이상적으로 수행됩니다.`,} },
      { type: "paragraph", text: { en: `Their effectiveness is generally considered greatest when conducted in an Ashram or Temple according to traditional guidelines and with all required ingredients. They may be especially powerful when performed under the guidance of an enlightened Guru.`, hi: `उनकी प्रभावशीलता आम तौर पर तब सबसे अधिक मानी जाती है जब इसे किसी आश्रम या मंदिर में पारंपरिक दिशानिर्देशों के अनुसार और सभी आवश्यक सामग्रियों के साथ आयोजित किया जाता है। किसी प्रबुद्ध गुरु के मार्गदर्शन में किए जाने पर वे विशेष रूप से शक्तिशाली हो सकते हैं।`, ja: `一般に、その効果は、アシュラムまたは寺院で伝統的なガイドラインに従って、必要な材料をすべて使用して行われた場合に最大であると考えられています。啓発されたグルの指導の下で実行されると、特に強力になる可能性があります。`, ko: `그 효과는 일반적으로 전통적인 지침에 따라 모든 필수 재료를 사용하여 아쉬람이나 사원에서 수행될 때 가장 큰 것으로 간주됩니다. 깨달은 구루의 지도 아래 수행될 때 특히 강력할 수 있습니다.`,} },
      { type: "paragraph", text: { en: `These rituals can target the effects of a single problematic planet or, when necessary, address all nine planetary energies simultaneously to create balance, harmony, and peace throughout the chart.`, hi: `ये अनुष्ठान किसी एक समस्याग्रस्त ग्रह के प्रभावों को लक्षित कर सकते हैं या, जब आवश्यक हो, पूरे चार्ट में संतुलन, सद्भाव और शांति बनाने के लिए सभी नौ ग्रहों की ऊर्जा को एक साथ संबोधित कर सकते हैं।`, ja: `これらの儀式は、問題のある単一の惑星の影響をターゲットにすることも、必要に応じて、9 つの惑星のエネルギーすべてに同時に対処して、チャート全体のバランス、調和、平和を生み出すこともできます。`, ko: `이러한 의식은 문제가 있는 단일 행성의 영향을 목표로 삼을 수 있으며, 필요한 경우 9개 행성 에너지 모두를 동시에 다루어 차트 전체에 균형, 조화 및 평화를 만들 수 있습니다.`,} },
    ],
  }
];
